        /// <summary>Merge community-supplied custom engine defs into the
        /// local library. Reuses the file-based MergeImportedCustomEngines
        /// (Id-keyed dedup, local wins on collision with logging when
        /// content differs).</summary>
        public void ImportCommunityCustomEngines(List<CustomEngineDef> incoming)
        {
            if (incoming == null || incoming.Count == 0) return;
            MergeImportedCustomEngines(incoming);
            PersistSettingsCore();
        }

        /// <summary>Persist a freshly-downloaded community car preset into
        /// the user's library under the supplied preset name. Wraps
        /// CarPresetStore.Save with the curator's author + description so
        /// the row stays attributed in the preset manager Source column.</summary>
        // ---- Local duplicate-content detection (owner rule 2026-07-13):
        // the library must never hold two presets with identical tuning under
        // different names. Game comparison is attribution-blind (a differing
        // community description is not a different tune); car overrides carry
        // no attribution inside the Override, so their share-lineage hash is
        // already content-only. Overwriting an existing NAME (plain save /
        // preset auto-update) is never blocked; only creating a NEW name is
        // checked.

        /// <summary>The existing preset an import/save was refused for
        /// duplicating, for callers that want to phrase the message.</summary>
        internal string LastLocalDuplicateName { get; private set; }

        internal string FindGamePresetNameWithSameContent(GameSettingsSnapshot candidate, string excludeName = null)
        {
            if (candidate == null || Settings?.Presets == null) return null;
            string hash = PresetBodyHasher.ComputeGameSnapshotContentHash(candidate);
            if (hash == null) return null;
            foreach (var kv in Settings.Presets)
            {
                if (kv.Value == null) continue;
                if (excludeName != null
                    && string.Equals(kv.Key, excludeName, StringComparison.OrdinalIgnoreCase)) continue;
                if (string.Equals(PresetBodyHasher.ComputeGameSnapshotContentHash(kv.Value), hash,
                                  StringComparison.Ordinal))
                    return kv.Key;
            }
            return null;
        }

        internal string FindCarPresetNameWithSameContent(string carId, CarOverride candidate, string excludeName = null)
        {
            if (candidate == null || string.IsNullOrEmpty(carId)) return null;
            string hash = PresetBodyHasher.ComputeCarOverrideHash(candidate);
            if (hash == null) return null;
            var all = GetCarPresets(carId);
            if (all == null) return null;
            foreach (var kv in all)
            {
                if (kv.Value?.Override == null) continue;
                if (excludeName != null
                    && string.Equals(kv.Key, excludeName, StringComparison.OrdinalIgnoreCase)) continue;
                if (string.Equals(PresetBodyHasher.ComputeCarOverrideHash(kv.Value.Override), hash,
                                  StringComparison.Ordinal))
                    return kv.Key;
            }
            return null;
        }

        public void SaveImportedCommunityCarPreset(string carId, string presetName,
            string gameName, CarOverride ovr, string author, string description,
            string communitySourceId = null, bool? allowInPacks = null)
        {
            if (_carStore == null || string.IsNullOrEmpty(carId)
                || string.IsNullOrEmpty(presetName) || ovr == null) return;
            // Content dedup: a NEW name whose tuning already exists for this
            // car is skipped (re-saves of an existing name pass through).
            LastLocalDuplicateName = null;
            var existingForCar = GetCarPresets(carId);
            if (existingForCar == null || !existingForCar.ContainsKey(presetName))
            {
                string dup = FindCarPresetNameWithSameContent(carId, ovr);
                if (dup != null)
                {
                    LastLocalDuplicateName = dup;
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Skipped community car preset '{presetName}' for '{carId}': identical to '{dup}'.");
                    return;
                }
            }
            // Stamp the source id onto the override so the permission
            // gate + pack creator can identify this item by stable
            // server uuid, surviving rename / duplicate / re-import.
            ovr.CommunitySourceId = communitySourceId;
            // Stamp the original author's "ok to re-bundle" permission
            // onto the override so peer-to-peer export/import carries it
            // forward without depending on the DownloadedCommunityPresets
            // tracker, and so a tracker-less import still has the truth.
            if (allowInPacks.HasValue) ovr.CommunityAllowInPacks = allowInPacks;
            _carStore.Save(carId, presetName, gameName, ovr, isBuiltin: false,
                packName: "Community",
                author: author, description: description,
                authorVersion: null,
                defaultAuthor: null);
        }

        /// <summary>Persist a freshly-downloaded community GAME preset
        /// (a full GameSettingsSnapshot) into the user's library under
        /// presetName. Stamps Author / Description / PackName="Community"
        /// + the source server uuid so the Source column attributes the
        /// row and the permission gate can identify it.</summary>
        public bool SaveImportedCommunityGamePreset(string presetName,
            GameSettingsSnapshot snap, string author, string description,
            string communitySourceId = null, bool? allowInPacks = null)
        {
            if (string.IsNullOrEmpty(presetName) || snap == null) return false;
            if (IsBuiltinPreset(presetName) && !DevMode) return false;
            // Stamp attribution + source id onto the in-memory snapshot
            // before persistence so the JSON on disk + the cache both
            // carry the community lineage. CommunitySourceId is the
            // identity the permission gate trusts.
            snap.Author            = author;
            snap.Description       = description;
            snap.PackName          = "Community";
            snap.CommunitySourceId = communitySourceId;
            // Author's "ok to re-bundle" permission travels with the
            // snapshot so export/import preserves it.
            if (allowInPacks.HasValue) snap.CommunityAllowInPacks = allowInPacks;
            // Content dedup: a NEW name whose tuning already exists is
            // skipped (re-saves of an existing name, e.g. the preset
            // auto-update path, pass through).
            LastLocalDuplicateName = null;
            if (!Settings.Presets.ContainsKey(presetName))
            {
                string dup = FindGamePresetNameWithSameContent(snap);
                if (dup != null)
                {
                    LastLocalDuplicateName = dup;
                    SimHub.Logging.Current.Info(
                        $"[TF4ALL] Skipped community game preset '{presetName}': identical to '{dup}'.");
                    return false;
                }
            }
            return PersistGamePresetToFolder(presetName, snap);
        }


        /// <summary>Blocking fetch of the current community consensus for
        /// (game, carId)'s engine layout. Used by the share-prompt to render
        /// accurate "first / confirming / alternative" copy. Bounded
        /// timeout (default 2s) so a slow network doesn't stall the UI.
        /// Returns null on disabled / not configured / timeout / no row.
        /// EngineLayoutConsensus is internal to the plugin assembly; the
        /// payload bag is opaque enough that internal exposure is fine
        /// (no public clients of TrueforcePlugin look at it).</summary>
        internal EngineLayoutConsensus FetchEngineLayoutConsensus(string game, string carId)
        {
            return _community?.FetchEngineLayoutConsensus(game, carId,
                ComputeActiveCarVariantSignature(game, carId));
        }

        /// <summary>Build the per-variant fingerprint we attach to community
        /// submissions / votes / fetches so games that reuse the same car_id
        /// across in-game engine swaps (Forza) get one consensus row per
        /// variant instead of submitters silently overwriting each other.
        ///
        /// Three independent signals contribute when present, joined by
        /// ";" in fixed order so the same engine produces the same string
        /// across users:
        ///   cyl=N         - Forza is the primary cohort. Strongest single
        ///                   signal: a swap that changes the cylinder count
        ///                   is unambiguously a different engine.
        ///   maxrpm=BAND   - Hard rev ceiling. Banded to nearest 50 (near-exact,
        ///                   tighter than redline): it's the only discriminator
        ///                   Forza gives us and a deterministic spec, so it
        ///                   stays tight to separate close upgrade builds
        ///                   instead of merging them into one bucket.
        ///   redline=BAND  - Engaged rev-limiter point. Often equals or is
        ///                   close to maxrpm; banded too. When present and
        ///                   distinct from maxrpm it adds discrimination
        ///                   (sport vs race rev-limiter modes).
        /// All three are optional. Empty string when nothing is observed
        /// (sentinel for "no variant discriminator" - matches the server's
        /// default and the pre-variant single-row behavior).</summary>
        /// <summary>Public shortcut for <see
        /// cref="ComputeActiveCarVariantSignature"/> against the currently
        /// active car. Used by SettingsControl to stamp the in-flight
        /// fetch with the live signature so an in-session swap can
        /// invalidate the cache and trigger a re-fetch without waiting
        /// for a car change.</summary>
        public string ComputeActiveCarVariantSignatureForActive()
        {
            return ComputeActiveCarVariantSignature(_activeGame, _activeCarId);
        }

        internal string ComputeActiveCarVariantSignature(string game, string carId)
        {
            if (EnginePulse == null) return string.Empty;
            if (game != _activeGame || carId != _activeCarId) return string.Empty;
            var parts = new List<string>(3);
            // Cyl source: telemetry-direct (Forza UDP NumCylinders) first,
            // then resolver/bake-derived CatalogCyl as a fallback so
            // SimHub-fallback games (which don't expose NumCylinders in
            // their telemetry frame) still contribute cyl to the signature.
            int? cyl = ActiveCarEffectiveCyl();
            if (cyl.HasValue && cyl.Value >= 1 && cyl.Value <= 16)
                parts.Add("cyl=" + cyl.Value);
            int maxBand = BandMaxRpm(EnginePulse.ObservedMaxRpm);
            if (maxBand > 0) parts.Add("maxrpm=" + maxBand);
            int redBand = BandRpm(EnginePulse.ObservedRedlineRpm);
            if (redBand > 0) parts.Add("redline=" + redBand);
            return parts.Count == 0 ? string.Empty : string.Join(";", parts);
        }

        // Cyl source order: telemetry-direct (Forza UDP NumCylinders) →
        // resolver/bake-derived (CatalogCyl, populated by ResolveAndApplyCarFacts
        // for SimHub-fallback games via CarCylinderResolver) → null. Returns
        // null when neither is available (cars with no bake entry on a
        // SimHub-fallback game; the auto-create then skips cyl).
        private int? ActiveCarEffectiveCyl()
        {
            if (EnginePulse == null) return null;
            int? observed = EnginePulse.ObservedCyl;
            if (observed.HasValue && observed.Value >= 1 && observed.Value <= 16)
                return observed;
            int? catalog = EnginePulse.CatalogCyl;
            if (catalog.HasValue && catalog.Value >= 1 && catalog.Value <= 16)
                return catalog;
            return null;
        }

        // RPM banding for the variant signature lives in Core
        // (VariantSignatureMath) so it's unit-tested; these are thin
        // delegators that keep the call sites above unchanged. Redline bands
        // to 500 (loose, pools cross-user submissions); MaxRpm bands to 50
        // (near-exact: it's the only discriminator Forza gives us and it's a
        // deterministic spec, so it stays tight to separate close upgrade
        // builds).
        private static int BandRpm(double rpm) => VariantSignatureMath.BandRedline(rpm);

        private static int BandMaxRpm(double rpm) => VariantSignatureMath.BandMaxRpm(rpm);

        /// <summary>Write a User-source CarName fact onto the local CarFacts
        /// bundle for (game, carId). Updates the displayed name immediately
        /// (re-runs the resolution cascade) and persists settings. Returns
        /// false on invalid input.</summary>
        public bool WriteCarNameFact(string game, string carId, string name)
        {
            if (string.IsNullOrEmpty(game) || string.IsNullOrEmpty(carId)) return false;
            if (string.IsNullOrWhiteSpace(name)) return false;
            name = name.Trim();
            if (name.Length < 2 || name.Length > 96) return false;
            if (Settings == null) return false;
            if (Settings.CarFacts == null)
                Settings.CarFacts = new Dictionary<string, CarFactsBundle>();

            string key = game + "/" + carId;
            if (!Settings.CarFacts.TryGetValue(key, out var bundle) || bundle == null)
            {
                bundle = new CarFactsBundle();
                Settings.CarFacts[key] = bundle;
            }
            bundle.CarName = name;

            PersistSettingsCore();

            if (game == _activeGame && carId == _activeCarId)
                ResolveAndApplyCarFactsForActiveCar(carId, logResolution: true);
            return true;
        }

        /// <summary>Fire-and-forget submission of a car-name correction.
        /// Same gating as the engine_layout submission: no-op when
        /// CommunityEnabled is false OR backend isn't configured.</summary>
        public void SubmitCarNameToCommunity(string game, string carId, string name)
        {
            _community?.SubmitCarNameAsync(game, carId, name, CommunityNameLocaleSig());
            // Car facts are anonymous: the contribution note tracks whether a
            // submission actually went out, which needs community on + the
            // car-data sharing consent, not a signed-in account.
            if (Settings?.CommunityEnabled == true && Settings.AutoSubmitCarFacts)
                NoteMotdContribution(MotdContribution.CarFact);
        }

        // Map CarFactSource onto the source-label vocabulary the engine-layout
        // status renderer (SettingsControl.xaml.cs EngineLayoutAutoText)
        // already understands. Without this mapping the raw enum-name lowercase
        // ("scanner", "community", ...) falls through to the renderer's
        // "(heuristic: X)" catch-all and existing-cache users would see their
        // label silently regress from "cached from earlier session" to
        // "(heuristic: scanner)" on upgrade. Scanner-source variants in
        // Stage 1 are exclusively the cylinder-cache migration cohort, so
        // mapping them to "cache" preserves the pre-upgrade label exactly.
        private static string MapCarFactSourceToUiLabel(CarFactSource s)
        {
            switch (s)
            {
                case CarFactSource.Scanner:       return "cache";
                case CarFactSource.Community:     return "community";
                case CarFactSource.User:          return "user-set";
                case CarFactSource.UserVariant:   return "user-variant";
                case CarFactSource.GameTelemetry: return "telemetry";
                case CarFactSource.Baked:         return "baked";
                case CarFactSource.SwapOverride:  return "swap-override";
                default:                          return s.ToString().ToLowerInvariant();
            }
        }

        // NOTE (v0.1.25): MigrateSpikeTamingFlag used to live here. It inferred
        // FfbSpikeTamingEnabled from non-zero spike values for pre-v0.1.0
        // installs (flag defaulted false back then). Since v0.1.3 the flag
        // defaults true, so missing-key JSON already deserializes to enabled,
        // and the only state the inference could still match (flag false +
        // non-zero values) is a deliberate user disable, which by design keeps
        // the tuned values. It ran unguarded on every startup and force
        // re-enabled spike reduction after the user saved it off. Removed;
        // the persisted flag is now honored as saved. Do not reintroduce
        // value-based inference for this flag.

        // EnginePulse LoadLayer + HighRpmBoost shipped Off at 0.3 / 0.4 in
        // 0.1.7-0.1.8. In 0.1.9 the defaults flipped to On at 0.8 / 0.7. Saved
        // presets carry the old serialized values, so a flat default change
        // here doesn't reach them. Migrate per-field: if the saved value
        // exactly matches the prior default (Off + 0.3 / 0.4), treat it as
        // never-customized and upgrade. Any non-default tuning is preserved.
        // Touches Settings.EnginePulse, every game-preset snapshot, the live
        // CarOverrides cache, and rewrites any matching .tfcar.json files so
        // non-active per-car presets also pick up the new defaults.
        private void MigrateEngineHighRpmHelpersDefaults()
        {
            if (Settings == null) return;
            bool changed = false;

            if (MigrateEngineHighRpmFields(Settings.EnginePulse)) changed = true;

            if (Settings.Presets != null)
            {
                foreach (var snap in Settings.Presets.Values)
                {
                    if (snap?.EnginePulse == null) continue;
                    if (MigrateEngineHighRpmFields(snap.EnginePulse)) changed = true;
                }
            }

            if (Settings.CarOverrides != null)
            {
                foreach (var ovr in Settings.CarOverrides.Values)
                {
                    if (ovr?.EnginePulse == null) continue;
                    if (MigrateEngineHighRpmFields(ovr.EnginePulse)) changed = true;
                }
                // Resync _lastPersistedCarOverrides so dirty checks against the
                // live cache match the just-migrated values (otherwise every
                // car would read as dirty on first load).
                if (changed)
                {
                    foreach (var kv in Settings.CarOverrides)
                    {
                        if (kv.Value == null) continue;
                        _lastPersistedCarOverrides[kv.Key] = CloneCarOverride(kv.Value);
                    }
                }
            }

            // Rewrite .tfcar.json files for any non-active preset (or active
            // ones whose live cache we just migrated) so the new defaults
            // persist across launches.
            if (_carStore != null)
            {
                var loaded = _carStore.LoadAll();
                foreach (var carKv in loaded)
                {
                    foreach (var entry in carKv.Value.Values)
                    {
                        if (entry?.Override?.EnginePulse == null) continue;
                        if (MigrateEngineHighRpmFields(entry.Override.EnginePulse))
                        {
                            _carStore.Save(entry.CarId, entry.PresetName, entry.GameName,
                                           entry.Override, entry.IsBuiltin);
                            changed = true;
                        }
                    }
                }
            }

            if (changed)
            {
                PersistSettingsCore();
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Migrated EnginePulse LoadLayer / HighRpmBoost defaults "
                    + "(Off @ 0.3 / 0.4 -> On @ 0.8 / 0.7) for presets at the old defaults.");
            }
        }

        private static bool MigrateEngineHighRpmFields(EnginePulseSettings s)
        {
            if (s == null) return false;
            bool changed = false;
            if (!s.LoadLayerEnabled && System.Math.Abs(s.LoadLayerGain - 0.3f) < 0.001f)
            {
                s.LoadLayerEnabled = true;
                s.LoadLayerGain    = 0.80f;
                changed = true;
            }
            if (!s.HighRpmBoostEnabled && System.Math.Abs(s.HighRpmBoostAmount - 0.4f) < 0.001f)
            {
                s.HighRpmBoostEnabled = true;
                s.HighRpmBoostAmount  = 0.70f;
                changed = true;
            }
            return changed;
        }

        // ---------- per-section dirty check (vs active preset) ----------

        /// <summary>True iff the current values for this section differ from
        /// the active preset's snapshot. False when there's no active preset
        /// (no anchor). Used by the UI to show/hide per-section "Save" /
        /// "Revert" buttons based on actual drift, not on a sticky flag
        /// so changing a value and changing it back clears the dirty state.</summary>
        public bool IsSectionDirty(SectionKind kind)
        {
            if (Settings == null) return false;
            bool hasGamePreset = !string.IsNullOrEmpty(_activePresetName)
                && Settings.Presets != null
                && Settings.Presets.TryGetValue(_activePresetName, out var snap)
                && snap != null;

            if (hasGamePreset)
            {
                Settings.Presets.TryGetValue(_activePresetName, out snap);
                switch (kind)
                {
                    case SectionKind.Master:         return !MasterEquals(snap);
                    case SectionKind.Ducking:        return !DuckingEquals(snap);
                    case SectionKind.Airborne:       return !AirborneEquals(snap);
                    case SectionKind.ImplementThud:  return !ImplementThudEquals(snap);
                    case SectionKind.SpikeReduction: return !SpikeReductionEquals(snap);
                    case SectionKind.StationarySpring: return !StationarySpringEquals(snap);
                    case SectionKind.Audio:    return !EffectEquals(snap, EffectField.Audio);
                    case SectionKind.Engine:   return !EffectEquals(snap, EffectField.Engine);
                    case SectionKind.Bumps:    return !EffectEquals(snap, EffectField.Bumps);
                    case SectionKind.Traction: return !EffectEquals(snap, EffectField.Traction);
                    case SectionKind.AxleSlip:     return !EffectEquals(snap, EffectField.AxleSlip);
                    case SectionKind.KerbThump:    return !EffectEquals(snap, EffectField.KerbThump);
                    case SectionKind.LockupJudder: return !EffectEquals(snap, EffectField.LockupJudder);
                    case SectionKind.Shift:    return !EffectEquals(snap, EffectField.Shift);
                    case SectionKind.Abs:        return !EffectEquals(snap, EffectField.Abs);
                    case SectionKind.PitLimiter: return !EffectEquals(snap, EffectField.PitLimiter);
                    case SectionKind.Drs:        return !EffectEquals(snap, EffectField.Drs);
                    case SectionKind.Collision:  return !EffectEquals(snap, EffectField.Collision);
                    case SectionKind.RevLimiter: return !EffectEquals(snap, EffectField.RevLimiter);
                }
                return false;
            }

            // Fallback when no game preset is active: sections with a
            // per-car override compare live override vs saved override.
            // Sections without an override (or non-per-car kinds like
            // Master / Ducking) have no anchor and return false; the UI
            // layer falls back to sticky-true via SectionHasAnchor for
            // those.
            if (!string.IsNullOrEmpty(_activeCarId) && Settings.CarOverrides != null)
            {
                Settings.CarOverrides.TryGetValue(_activeCarId, out var liveCo);
                _lastPersistedCarOverrides.TryGetValue(_activeCarId, out var savedCo);
                switch (kind)
                {
                    case SectionKind.Audio:    if (liveCo?.AudioCapture != null) return !Eq(liveCo.AudioCapture, savedCo?.AudioCapture); break;
                    case SectionKind.Engine:   if (liveCo?.EnginePulse  != null) return !Eq(liveCo.EnginePulse,  savedCo?.EnginePulse);  break;
                    case SectionKind.Bumps:    if (liveCo?.RoadBumps    != null) return !Eq(liveCo.RoadBumps,    savedCo?.RoadBumps);    break;
                    case SectionKind.Traction: if (liveCo?.TractionLoss != null) return !Eq(liveCo.TractionLoss, savedCo?.TractionLoss); break;
                    case SectionKind.AxleSlip:   if (liveCo?.AxleSlip     != null) return !Eq(liveCo.AxleSlip,     savedCo?.AxleSlip);     break;
                    case SectionKind.KerbThump:  if (liveCo?.KerbThump    != null) return !Eq(liveCo.KerbThump,    savedCo?.KerbThump);    break;
                    case SectionKind.LockupJudder: if (liveCo?.LockupJudder != null) return !Eq(liveCo.LockupJudder, savedCo?.LockupJudder); break;
                    case SectionKind.Shift:    if (liveCo?.GearShift    != null) return !Eq(liveCo.GearShift,    savedCo?.GearShift);    break;
                    case SectionKind.Abs:        if (liveCo?.AbsClick     != null) return !Eq(liveCo.AbsClick,     savedCo?.AbsClick);     break;
                    case SectionKind.PitLimiter: if (liveCo?.PitLimiter   != null) return !Eq(liveCo.PitLimiter,   savedCo?.PitLimiter);   break;
                    case SectionKind.Drs:        if (liveCo?.Drs          != null) return !Eq(liveCo.Drs,          savedCo?.Drs);          break;
                    case SectionKind.Collision:  if (liveCo?.Collision    != null) return !Eq(liveCo.Collision,    savedCo?.Collision);    break;
                    case SectionKind.RevLimiter: if (liveCo?.RevLimiter   != null) return !Eq(liveCo.RevLimiter,   savedCo?.RevLimiter);   break;
                    case SectionKind.Airborne:   if (liveCo?.Airborne     != null) return !Eq(liveCo.Airborne,     savedCo?.Airborne);     break;
                }
            }
            return false;
        }

        /// <summary>True iff the section has either a game-preset snapshot
        /// or a per-car override to compare against. Used by the UI to
        /// pick between IsSectionDirty (precise) and sticky-true (fallback
        /// when no anchor exists).</summary>
        public bool SectionHasAnchor(SectionKind kind)
        {
            if (Settings == null) return false;
            GameSettingsSnapshot snap = null;
            bool hasGamePreset = !string.IsNullOrEmpty(_activePresetName)
                && Settings.Presets != null
                && Settings.Presets.TryGetValue(_activePresetName, out snap)
                && snap != null;
            // A game preset is only an ANCHOR for the sections it actually
            // carries. When the preset OMITS this section (a partial preset, or
            // one saved before the effect existed) it provides no saved baseline,
            // so we fall through to the per-car override check; with no override
            // either, the section has NO anchor and the UI uses sticky-true (an
            // edit shows dirty and stays dirty until saved). Without this an
            // omitted section read permanently dirty (Eq vs null) or - after the
            // null-guard in EffectEquals - permanently clean, masking real edits.
            if (hasGamePreset && PresetCarriesSection(snap, kind)) return true;

            // Master / Ducking / SpikeReduction are not per-car, so without
            // a game preset that carries them they have no anchor.
            if (kind == SectionKind.Master
                || kind == SectionKind.Ducking
                || kind == SectionKind.SpikeReduction
                || kind == SectionKind.StationarySpring
                || kind == SectionKind.ImplementThud) return false;
            if (string.IsNullOrEmpty(_activeCarId) || Settings.CarOverrides == null) return false;
            if (!Settings.CarOverrides.TryGetValue(_activeCarId, out var liveCo) || liveCo == null) return false;
            switch (kind)
            {
                case SectionKind.Audio:    return liveCo.AudioCapture != null;
                case SectionKind.Engine:   return liveCo.EnginePulse  != null;
                case SectionKind.Bumps:    return liveCo.RoadBumps    != null;
                case SectionKind.Traction: return liveCo.TractionLoss != null;
                case SectionKind.AxleSlip:   return liveCo.AxleSlip     != null;
                case SectionKind.KerbThump:  return liveCo.KerbThump    != null;
                case SectionKind.LockupJudder: return liveCo.LockupJudder != null;
                case SectionKind.Shift:    return liveCo.GearShift    != null;
                case SectionKind.Abs:        return liveCo.AbsClick     != null;
                case SectionKind.PitLimiter: return liveCo.PitLimiter   != null;
                case SectionKind.Drs:        return liveCo.Drs          != null;
                case SectionKind.Collision:  return liveCo.Collision    != null;
                case SectionKind.RevLimiter: return liveCo.RevLimiter   != null;
                case SectionKind.Airborne:   return liveCo.Airborne     != null;
            }
            return false;
        }

        /// <summary>True iff the preset snapshot actually carries this section.
        /// Master / Ducking / SpikeReduction live in always-present scalar fields
        /// so they're always carried; the effect sections are nullable objects a
        /// partial preset can omit. Used by SectionHasAnchor to decide whether the
        /// preset is a real baseline for the section or whether it has "no opinion"
        /// (omitted -> sticky-true edit tracking instead).</summary>
        private static bool PresetCarriesSection(GameSettingsSnapshot snap, SectionKind kind)
        {
            if (snap == null) return false;
            switch (kind)
            {
                case SectionKind.Master:
                case SectionKind.Ducking:
                case SectionKind.SpikeReduction: return true;
                case SectionKind.StationarySpring: return snap.StationarySpringEnabled != null;
                case SectionKind.Audio:      return snap.AudioCapture != null;
                case SectionKind.Engine:     return snap.EnginePulse  != null;
                case SectionKind.Bumps:      return snap.RoadBumps    != null;
                case SectionKind.Traction:   return snap.TractionLoss != null;
                case SectionKind.AxleSlip:   return snap.AxleSlip     != null;
                case SectionKind.KerbThump:  return snap.KerbThump    != null;
                case SectionKind.LockupJudder: return snap.LockupJudder != null;
                case SectionKind.Shift:      return snap.GearShift    != null;
                case SectionKind.Abs:        return snap.AbsClick     != null;
                case SectionKind.PitLimiter: return snap.PitLimiter   != null;
                case SectionKind.Drs:        return snap.Drs          != null;
                case SectionKind.Collision:  return snap.Collision    != null;
                case SectionKind.RevLimiter: return snap.RevLimiter   != null;
                case SectionKind.Airborne:   return snap.Airborne     != null;
                case SectionKind.ImplementThud: return snap.ImplementThud != null;
            }
            return true;
        }

        private bool MasterEquals(GameSettingsSnapshot snap)
        {
            // FFB scale is personal: for a community preset it isn't applied or
            // saved into the shared identity, so it must not count toward this
            // section's dirty state either (else applying a downloaded preset
            // would leave Master spuriously dirty). For the user's own presets
            // it's a full member (savable per-game). Master gain is NOT here: it
            // is a global setting (auto-persisted, never preset-scoped).
            bool personal = !string.IsNullOrEmpty(snap.CommunitySourceId);
            return (personal || EqF2(Settings.FfbScale,   snap.FfbScale))
                &&     Settings.FfbInvertSign          == snap.FfbInvertSign
                && EqF1(Settings.FfbSmoothTimeConstantMs, snap.FfbSmoothTimeConstantMs);
        }

        private bool SpikeReductionEquals(GameSettingsSnapshot snap)
        {
            return Settings.FfbSpikeTamingEnabled  == snap.FfbSpikeTamingEnabled
                &&     Settings.FfbSpikeUseSlewLimiter == snap.FfbSpikeUseSlewLimiter
                && EqI(Settings.FfbSpikeMaxLsbPerMs,  snap.FfbSpikeMaxLsbPerMs)
                && EqI(Settings.FfbPeakSoftLimitLsb,  snap.FfbPeakSoftLimitLsb);
        }

        // Stationary spring is a global (non-per-car) section. A preset saved
        // before the spring lived in the snapshot has null fields -> "no
        // opinion" -> not dirty (ApplyGamePreset leaves the live value alone),
        // mirroring AirborneEquals.
        private bool StationarySpringEquals(GameSettingsSnapshot snap)
        {
            if (snap.StationarySpringEnabled == null) return true;
            return Settings.StationarySpringEnabled        == snap.StationarySpringEnabled.Value
                && EqF2(Settings.StationarySpringStrength,  snap.StationarySpringStrength  ?? Settings.StationarySpringStrength)
                && EqI (Settings.StationarySpringCutoffKmh, snap.StationarySpringCutoffKmh ?? Settings.StationarySpringCutoffKmh);
        }

        private bool DuckingEquals(GameSettingsSnapshot snap)
        {
            return Settings.DuckingEnabled == snap.DuckingEnabled
                && EqF2(Settings.DuckDepth,    snap.DuckDepth)
                && EqI (Settings.DuckAttackMs, snap.DuckAttackMs)
                && EqI (Settings.DuckReleaseMs, snap.DuckReleaseMs)
                && Settings.DuckFrequencyAware == snap.DuckFrequencyAware;
        }

        // Airborne ducking: same scope-aware shape as EffectEquals (live car
        // override compares against the saved car baseline, falling back to
        // the preset when the car preset never saved this section; otherwise
        // global vs preset). A preset saved before this effect existed has no
        // Airborne block (snap.Airborne == null); treat that as "no opinion"
        // -> not dirty. ApplyGamePreset leaves the live Airborne value
        // untouched in that case, so comparing it against the shipped default
        // (the old behavior) wrongly lit the section dirty whenever the
        // carried-over value wasn't exactly the default.
        private bool AirborneEquals(GameSettingsSnapshot snap)
        {
            if (snap.Airborne == null) return true;
            if (_activeCarId != null && Settings.CarOverrides != null
                && Settings.CarOverrides.TryGetValue(_activeCarId, out var liveCo)
                && liveCo?.Airborne != null)
            {
                _lastPersistedCarOverrides.TryGetValue(_activeCarId, out var savedCo);
                return Eq(liveCo.Airborne, savedCo?.Airborne ?? snap.Airborne);
            }
            return Eq(Settings.Airborne, snap.Airborne);
        }

        // Implement thud is global-only with NO car-override arm (unlike
        // Airborne): SectionHasCarScope excludes it, so the comparison is
        // always live global vs preset. Null snapshot = the preset predates
        // the effect = "no opinion" -> not dirty (SectionHasAnchor's
        // PresetCarriesSection check gives such presets sticky-true edit
        // tracking instead).
        private bool ImplementThudEquals(GameSettingsSnapshot snap)
        {
            if (snap.ImplementThud == null) return true;
            return Eq(Settings.ImplementThud, snap.ImplementThud);
        }

        // Tolerances match the UI's display precision so that two values
        // displayed as the same string (e.g. "0.07", "60", "0.0") count as
        // equal, which is what users expect when they drag a slider away
        // and back. Without these, slider-snap noise stays "dirty" forever.
        // Round both sides to the precision the UI shows, then exact-compare.
        // Distance-based epsilon was off by a factor of two at the F2 boundary
        // (two values both displayed as "0.39" can differ by up to ~0.01,
        // but the old < 0.005 tolerance treated them as unequal -- so the
        // dirty marker stayed lit after a slider returned to the same
        // visible value).
        private static bool EqF2(double a, double b) => Math.Round(a, 2) == Math.Round(b, 2);
        private static bool EqF1(double a, double b) => Math.Round(a, 1) == Math.Round(b, 1);
        private static bool EqI (double a, double b) => Math.Round(a, 0) == Math.Round(b, 0);

        private enum EffectField { Audio, Engine, Bumps, Traction, Shift, Abs, PitLimiter, Drs, Collision, RevLimiter, AxleSlip, KerbThump, LockupJudder }

        /// <summary>Scope-aware equals for dirty detection.
        ///
        /// • If the active car has a per-car override for this section, the
        ///   "saved baseline" is the per-car file's content (tracked via
        ///   _lastPersistedCarOverrides). Edits to the override since the
        ///   last "For this car" save show as dirty.
        /// • Otherwise, the saved baseline is the active preset's global
        ///   section. Edits show as dirty until "Update game defaults".</summary>
        private bool EffectEquals(GameSettingsSnapshot snap, EffectField f)
        {
            string carId = _activeCarId;
            CarOverride liveCo = null;
            CarOverride savedCo = null;
            if (carId != null)
            {
                if (Settings.CarOverrides != null) Settings.CarOverrides.TryGetValue(carId, out liveCo);
                _lastPersistedCarOverrides.TryGetValue(carId, out savedCo);
            }
            switch (f)
            {
                // For a car-overridden section the saved baseline is the saved
                // override if one exists, ELSE the game default (snap): a car
                // with no saved override "follows the game default", so a draft
                // override whose values match the default must read clean. (This
                // is what lets toggling an effect off then back on clear the
                // dirty state when the car had no prior override.)
                //
                // Non-override branch: when the active preset doesn't CARRY this
                // section (snap.X == null - a partial preset, or one saved before
                // the effect existed), the preset has "no opinion" on it.
                // ApplyGamePreset leaves the live value untouched in that case, so
                // there's nothing to be dirty against: the section reads clean
                // until the user actually edits it. Without the snap.X == null
                // guard, Eq(non-null live, null) returns false and the section
                // lights up dirty the moment you switch to such a preset, even
                // though nothing was changed.
                case EffectField.Audio:
                    if (liveCo?.AudioCapture != null) return Eq(liveCo.AudioCapture, savedCo?.AudioCapture ?? snap.AudioCapture);
                    return snap.AudioCapture == null || Eq(Settings.AudioCapture, snap.AudioCapture);
                case EffectField.Engine:
                    if (liveCo?.EnginePulse  != null) return Eq(liveCo.EnginePulse,  savedCo?.EnginePulse  ?? snap.EnginePulse);
                    return snap.EnginePulse  == null || Eq(Settings.EnginePulse,  snap.EnginePulse);
                case EffectField.Bumps:
                    if (liveCo?.RoadBumps    != null) return Eq(liveCo.RoadBumps,    savedCo?.RoadBumps    ?? snap.RoadBumps);
                    return snap.RoadBumps    == null || Eq(Settings.RoadBumps,    snap.RoadBumps);
                case EffectField.Traction:
                    if (liveCo?.TractionLoss != null) return Eq(liveCo.TractionLoss, savedCo?.TractionLoss ?? snap.TractionLoss);
                    return snap.TractionLoss == null || Eq(Settings.TractionLoss, snap.TractionLoss);
                case EffectField.Shift:
                    if (liveCo?.GearShift    != null) return Eq(liveCo.GearShift,    savedCo?.GearShift    ?? snap.GearShift);
                    return snap.GearShift    == null || Eq(Settings.GearShift,    snap.GearShift);
                case EffectField.Abs:
                    if (liveCo?.AbsClick     != null) return Eq(liveCo.AbsClick,     savedCo?.AbsClick     ?? snap.AbsClick);
                    return snap.AbsClick     == null || Eq(Settings.AbsClick,     snap.AbsClick);
                case EffectField.PitLimiter:
                    if (liveCo?.PitLimiter   != null) return Eq(liveCo.PitLimiter,   savedCo?.PitLimiter   ?? snap.PitLimiter);
                    return snap.PitLimiter   == null || Eq(Settings.PitLimiter,   snap.PitLimiter);
                case EffectField.Drs:
                    if (liveCo?.Drs          != null) return Eq(liveCo.Drs,          savedCo?.Drs          ?? snap.Drs);
                    return snap.Drs          == null || Eq(Settings.Drs,          snap.Drs);
                case EffectField.Collision:
                    if (liveCo?.Collision    != null) return Eq(liveCo.Collision,    savedCo?.Collision    ?? snap.Collision);
                    return snap.Collision    == null || Eq(Settings.Collision,    snap.Collision);
                case EffectField.RevLimiter:
                    if (liveCo?.RevLimiter   != null) return Eq(liveCo.RevLimiter,   savedCo?.RevLimiter   ?? snap.RevLimiter ?? new RevLimiterSettings());
                    return snap.RevLimiter   == null || Eq(Settings.RevLimiter,   snap.RevLimiter);
                case EffectField.AxleSlip:
                    if (liveCo?.AxleSlip     != null) return Eq(liveCo.AxleSlip,     savedCo?.AxleSlip     ?? snap.AxleSlip);
                    return snap.AxleSlip     == null || Eq(Settings.AxleSlip,     snap.AxleSlip);
                case EffectField.KerbThump:
                    if (liveCo?.KerbThump    != null) return Eq(liveCo.KerbThump,    savedCo?.KerbThump    ?? snap.KerbThump);
                    return snap.KerbThump    == null || Eq(Settings.KerbThump,    snap.KerbThump);
                case EffectField.LockupJudder:
                    if (liveCo?.LockupJudder != null) return Eq(liveCo.LockupJudder, savedCo?.LockupJudder ?? snap.LockupJudder);
                    return snap.LockupJudder == null || Eq(Settings.LockupJudder, snap.LockupJudder);
            }
            return true;
        }

        private static bool Eq(EnginePulseSettings a, EnginePulseSettings b)
        {
            // Layout / CustomEngineId / CustomFiringPattern(Name) are legacy
            // fields since the 2026-07 engine centralization (the engine type
            // lives in Car facts now), so they no longer participate in
            // preset equality. EqIgnoringLayout and
            // IsEngineSectionOnlyLayoutDirty were deleted with the move: an
            // engine pick can't dirty a preset anymore.
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,      b.Gain)
                && EqF2(a.Pitch,     b.Pitch)
                && EqI (a.LowpassHz, b.LowpassHz)
                && a.Waveform == b.Waveform
                && a.ElectricMode == b.ElectricMode
                && a.LoadLayerEnabled    == b.LoadLayerEnabled
                && EqF2(a.LoadLayerGain,      b.LoadLayerGain)
                && a.HighRpmBoostEnabled == b.HighRpmBoostEnabled
                && EqF2(a.HighRpmBoostAmount, b.HighRpmBoostAmount);
        }
        private static bool Eq(RoadBumpsSettings a, RoadBumpsSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain, b.Gain)
                && EqI (a.Freq, b.Freq)
                && a.Waveform == b.Waveform
                && a.SurfaceEnabled == b.SurfaceEnabled
                && EqF2(a.SurfaceGain, b.SurfaceGain)
                && EqI (a.SurfaceFreq, b.SurfaceFreq)
                && a.SurfaceWaveform == b.SurfaceWaveform
                && EqI (a.SurfaceLowpassHz,  b.SurfaceLowpassHz)
                && EqI (a.SurfaceHighpassHz, b.SurfaceHighpassHz)
                && EqF2(a.SurfaceRumbleScale, b.SurfaceRumbleScale);
        }
        private static bool Eq(TractionLossSettings a, TractionLossSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,            b.Gain)
                && EqF2(a.Sensitivity,     b.Sensitivity)
                && EqI (a.Freq,            b.Freq)
                && EqI (a.NoiseLowpassHz,  b.NoiseLowpassHz)
                && EqI (a.NoiseHighpassHz, b.NoiseHighpassHz)
                && a.Waveform == b.Waveform;
        }
        private static bool Eq(AxleSlipSettings a, AxleSlipSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain, b.Gain)
                && a.PredictiveSlip     == b.PredictiveSlip
                && a.RevLockedRearPulse == b.RevLockedRearPulse
                && EqF2(a.FrontStrength, b.FrontStrength)
                && EqF2(a.RearStrength,  b.RearStrength)
                && EqI (a.FrontPitchHz,  b.FrontPitchHz)   // pitches display as integer Hz
                && EqI (a.RearPitchHz,   b.RearPitchHz)
                && EqF2(a.JudderDepth,   b.JudderDepth)
                && EqF2(a.OnsetUtil,     b.OnsetUtil);
        }
        private static bool Eq(KerbThumpSettings a, KerbThumpSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain, b.Gain)
                && EqI(a.Freq, b.Freq);   // Freq displays as an integer; compare at display precision
        }
        private static bool Eq(LockupJudderSettings a, LockupJudderSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain, b.Gain);
        }
        private static bool Eq(GearShiftSettings a, GearShiftSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain, b.Gain)
                && EqI (a.Freq, b.Freq)
                && a.Waveform == b.Waveform;
        }
        private static bool Eq(AbsClickSettings a, AbsClickSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,           b.Gain)
                && EqI (a.Freq,           b.Freq)
                && EqF1(a.PulseFreq,      b.PulseFreq)
                && EqF2(a.DutyCycle,      b.DutyCycle)
                && EqI (a.TickDurationMs, b.TickDurationMs)
                && a.Mode == b.Mode && a.Waveform == b.Waveform;
        }
        private static bool Eq(PitLimiterSettings a, PitLimiterSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,      b.Gain)
                && EqI (a.Freq,      b.Freq)
                && EqF1(a.PulseFreq, b.PulseFreq)
                && EqF2(a.DutyCycle, b.DutyCycle)
                && EqF2(a.ActiveAmp, b.ActiveAmp)
                && a.Waveform == b.Waveform;
        }
        private static bool Eq(DrsSettings a, DrsSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,           b.Gain)
                && EqI (a.ActivationFreq, b.ActivationFreq)
                && a.ActivationMs == b.ActivationMs
                && EqF2(a.ActivationAmp,  b.ActivationAmp)
                && EqI (a.SustainedFreq,  b.SustainedFreq)
                && EqF2(a.SustainedAmp,   b.SustainedAmp)
                && a.Waveform          == b.Waveform
                && a.SustainedWaveform == b.SustainedWaveform;
        }
        private static bool Eq(CollisionSettings a, CollisionSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,               b.Gain)
                && EqI (a.Freq,               b.Freq)
                && a.EnvelopeMs == b.EnvelopeMs
                && EqF2(a.MinThreshold,       b.MinThreshold)
                && EqF2(a.MinAmp,             b.MinAmp)
                && EqF2(a.MaxAmp,             b.MaxAmp)
                && EqF2(a.NormalizationScale, b.NormalizationScale)
                && a.RefractoryMs == b.RefractoryMs
                && a.Waveform == b.Waveform;
        }
        private static bool Eq(RevLimiterSettings a, RevLimiterSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,      b.Gain)
                && EqI (a.Freq,      b.Freq)
                && EqF1(a.PulseFreq, b.PulseFreq)
                && EqF2(a.DutyCycle, b.DutyCycle)
                && EqF2(a.ActiveAmp, b.ActiveAmp)
                && EqI (a.RedlineOffsetRpm, b.RedlineOffsetRpm)
                && a.Waveform == b.Waveform;
        }
        private static bool Eq(AudioCaptureSettings a, AudioCaptureSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled == b.Enabled
                && EqF2(a.Gain,             b.Gain)
                && EqI (a.LowpassCutoffHz,  b.LowpassCutoffHz)
                && EqI (a.HighpassCutoffHz, b.HighpassCutoffHz);
        }
        private static bool Eq(AirborneSettings a, AirborneSettings b)
        {
            if (a == null || b == null) return a == b;
            return a.Enabled          == b.Enabled
                && EqF2(a.Reduction, b.Reduction)
                && a.DuckEngine       == b.DuckEngine
                && a.DuckAudio        == b.DuckAudio
                && a.DuckRoadBumps    == b.DuckRoadBumps
                && a.DuckTractionLoss == b.DuckTractionLoss
                && a.DuckRevLimiter   == b.DuckRevLimiter
                && a.DuckGearShift    == b.DuckGearShift
                && a.DuckAbs          == b.DuckAbs
                && a.DuckPitLimiter   == b.DuckPitLimiter
                && a.DuckDrs          == b.DuckDrs
                && a.DuckCollision    == b.DuckCollision;
        }

        private static bool Eq(ImplementThudSettings a, ImplementThudSettings b)
        {
            if (ReferenceEquals(a, b)) return true;
            if (a == null || b == null) return false;
            return a.Enabled == b.Enabled
                && a.Gain == b.Gain
                && a.Freq == b.Freq
                && a.RaiseAmp == b.RaiseAmp
                && a.HumAmp == b.HumAmp
                && a.HumFreq == b.HumFreq
                && a.BendDepth == b.BendDepth
                && a.SpeedPitch == b.SpeedPitch
                && a.HarmonicAmp == b.HarmonicAmp
                && a.SpeedVolume == b.SpeedVolume
                && a.Waveform == b.Waveform;
        }

        // ---------- per-section revert (from active preset) ----------

        /// <summary>Section identifier used by <see cref="RevertSection"/>.
        /// Mirrors the per-section "Save…" / "Revert" buttons in the UI:
        /// Master and Ducking are global-only; the rest have a per-car
        /// override component that revert respects.</summary>
        public enum SectionKind { Master, Ducking, Audio, Engine, Bumps, Traction, Shift, Abs, SpikeReduction, PitLimiter, Drs, Collision, RevLimiter, Airborne, StationarySpring, AxleSlip, KerbThump, LockupJudder, ImplementThud }

        /// <summary>Revert one section to the active preset's saved snapshot.
        /// Scope-aware: if the snapshot has a per-car override for the
        /// current car, that override is restored; otherwise the override is
        /// dropped and the global section is restored. No-op when there's
        /// no active preset (nothing to revert to).</summary>
        public bool RevertSection(SectionKind kind)
        {
            if (Settings == null || string.IsNullOrEmpty(_activePresetName)) return false;
            if (Settings.Presets == null || !Settings.Presets.TryGetValue(_activePresetName, out var snap) || snap == null) return false;

            switch (kind)
            {
                case SectionKind.Master:
                    // FFB scale is personal: reverted only for locally-authored
                    // presets; a community preset's Master revert leaves the
                    // user's own personal value in place. Master gain is global
                    // (not preset-scoped), so revert never touches it.
                    if (string.IsNullOrEmpty(snap.CommunitySourceId))
                    {
                        Settings.FfbScale            = snap.FfbScale;
                    }
                    Settings.FfbInvertSign           = snap.FfbInvertSign;
                    Settings.FfbSmoothTimeConstantMs = snap.FfbSmoothTimeConstantMs;
                    if (_device != null)
                    {
                        _device.FfbScale                = Settings.FfbScale;
                        _device.FfbInvertSign           = Settings.FfbInvertSign;
                        _device.FfbSmoothTimeConstantMs = Settings.FfbSmoothTimeConstantMs;
                    }
                    return true;

                case SectionKind.SpikeReduction:
                    Settings.FfbSpikeTamingEnabled  = snap.FfbSpikeTamingEnabled;
                    Settings.FfbSpikeUseSlewLimiter = snap.FfbSpikeUseSlewLimiter;
                    Settings.FfbSpikeMaxLsbPerMs    = snap.FfbSpikeMaxLsbPerMs;
                    Settings.FfbPeakSoftLimitLsb    = snap.FfbPeakSoftLimitLsb;
                    if (_device != null)
                    {
                        _device.FfbSpikeTamingEnabled  = Settings.FfbSpikeTamingEnabled;
                        _device.FfbSpikeUseSlewLimiter = Settings.FfbSpikeUseSlewLimiter;
                        _device.FfbSpikeMaxLsbPerMs    = Settings.FfbSpikeMaxLsbPerMs;
                        _device.FfbPeakSoftLimitLsb    = Settings.FfbPeakSoftLimitLsb;
                    }
                    return true;

                case SectionKind.StationarySpring:
                    // Global section; restore from the preset's saved values, or
                    // the shipped defaults when the preset predates the field.
                    // ApplyStationarySpring reads Settings live each frame, so no
                    // _device push is needed.
                    Settings.StationarySpringEnabled   = snap.StationarySpringEnabled   ?? true;
                    Settings.StationarySpringStrength  = snap.StationarySpringStrength  ?? 0.5;
                    Settings.StationarySpringCutoffKmh = snap.StationarySpringCutoffKmh ?? 12.0;
                    return true;

                case SectionKind.Ducking:
                    Settings.DuckingEnabled = snap.DuckingEnabled;
                    Settings.DuckDepth      = snap.DuckDepth;
                    Settings.DuckAttackMs   = snap.DuckAttackMs;
                    Settings.DuckReleaseMs  = snap.DuckReleaseMs;
                    Settings.DuckFrequencyAware = snap.DuckFrequencyAware;
                    return true;

                case SectionKind.Airborne:
                    // Global section. Restore from the preset's saved block, or
                    // the shipped default when the preset predates the effect.
                    Settings.Airborne = Clone(snap.Airborne ?? new AirborneSettings());
                    ApplyAirborneSettings();
                    return true;

                case SectionKind.ImplementThud:
                    // Global section, same shape as Airborne.
                    Settings.ImplementThud = Clone(snap.ImplementThud ?? new ImplementThudSettings());
                    ApplyImplementThudSettings();
                    return true;

                case SectionKind.Engine:
                    RevertEffectScopeAware(
                        snap.EnginePulse,
                        snap.CarOverrides,
                        co => co?.EnginePulse,
                        s => Settings.EnginePulse = Clone(s),
                        (co, v) => co.EnginePulse = Clone(v),
                        co => co.EnginePulse = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Bumps:
                    RevertEffectScopeAware(
                        snap.RoadBumps,
                        snap.CarOverrides,
                        co => co?.RoadBumps,
                        s => Settings.RoadBumps = Clone(s),
                        (co, v) => co.RoadBumps = Clone(v),
                        co => co.RoadBumps = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Traction:
                    RevertEffectScopeAware(
                        snap.TractionLoss,
                        snap.CarOverrides,
                        co => co?.TractionLoss,
                        s => Settings.TractionLoss = Clone(s),
                        (co, v) => co.TractionLoss = Clone(v),
                        co => co.TractionLoss = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.AxleSlip:
                    RevertEffectScopeAware(
                        snap.AxleSlip,
                        snap.CarOverrides,
                        co => co?.AxleSlip,
                        s => Settings.AxleSlip = Clone(s),
                        (co, v) => co.AxleSlip = Clone(v),
                        co => co.AxleSlip = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.KerbThump:
                    RevertEffectScopeAware(
                        snap.KerbThump,
                        snap.CarOverrides,
                        co => co?.KerbThump,
                        s => Settings.KerbThump = Clone(s),
                        (co, v) => co.KerbThump = Clone(v),
                        co => co.KerbThump = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.LockupJudder:
                    RevertEffectScopeAware(
                        snap.LockupJudder,
                        snap.CarOverrides,
                        co => co?.LockupJudder,
                        s => Settings.LockupJudder = Clone(s),
                        (co, v) => co.LockupJudder = Clone(v),
                        co => co.LockupJudder = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Shift:
                    RevertEffectScopeAware(
                        snap.GearShift,
                        snap.CarOverrides,
                        co => co?.GearShift,
                        s => Settings.GearShift = Clone(s),
                        (co, v) => co.GearShift = Clone(v),
                        co => co.GearShift = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Abs:
                    RevertEffectScopeAware(
                        snap.AbsClick,
                        snap.CarOverrides,
                        co => co?.AbsClick,
                        s => Settings.AbsClick = Clone(s),
                        (co, v) => co.AbsClick = Clone(v),
                        co => co.AbsClick = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.PitLimiter:
                    RevertEffectScopeAware(
                        snap.PitLimiter,
                        snap.CarOverrides,
                        co => co?.PitLimiter,
                        s => Settings.PitLimiter = Clone(s),
                        (co, v) => co.PitLimiter = Clone(v),
                        co => co.PitLimiter = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Drs:
                    RevertEffectScopeAware(
                        snap.Drs,
                        snap.CarOverrides,
                        co => co?.Drs,
                        s => Settings.Drs = Clone(s),
                        (co, v) => co.Drs = Clone(v),
                        co => co.Drs = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Collision:
                    RevertEffectScopeAware(
                        snap.Collision,
                        snap.CarOverrides,
                        co => co?.Collision,
                        s => Settings.Collision = Clone(s),
                        (co, v) => co.Collision = Clone(v),
                        co => co.Collision = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.RevLimiter:
                    RevertEffectScopeAware(
                        snap.RevLimiter,
                        snap.CarOverrides,
                        co => co?.RevLimiter,
                        s => Settings.RevLimiter = Clone(s),
                        (co, v) => co.RevLimiter = Clone(v),
                        co => co.RevLimiter = null);
                    ApplyActiveCarOverride();
                    return true;

                case SectionKind.Audio:
                    RevertEffectScopeAware(
                        snap.AudioCapture,
                        snap.CarOverrides,
                        co => co?.AudioCapture,
                        s => Settings.AudioCapture = CloneOrNull(s),
                        (co, v) => co.AudioCapture = CloneOrNull(v),
                        co => co.AudioCapture = null);
                    ApplyActiveCarOverride();
                    if (_audio != null && Settings.AudioCapture != null)
                    {
                        _audio.Enabled          = Settings.AudioCapture.Enabled;
                        _audio.Gain             = Settings.AudioCapture.Gain;
                        _audio.LowpassCutoffHz  = Settings.AudioCapture.LowpassCutoffHz;
                        _audio.HighpassCutoffHz = Settings.AudioCapture.HighpassCutoffHz;
                    }
                    return true;
            }
            return false;
        }

        /// <summary>Generic per-effect revert. Scope-aware:
        ///   * If the live car override has this section, the user is
        ///     editing in car-preset scope; restore from the on-disk car
        ///     preset (cached as _lastPersistedCarOverrides). If the saved
        ///     car preset didn't include this section, drop the override
        ///     (section falls back to global).
        ///   * Otherwise, restore the global section from the active
        ///     game-preset snapshot.
        ///   * The legacy snap.CarOverrides path is kept for old presets
        ///     that still carry per-car data; modern (Model G) presets
        ///     have snap.CarOverrides == null and only the live-override
        ///     branch fires.
        /// Caller is responsible for pushing the resulting state live
        /// (ApplyActiveCarOverride etc.).</summary>
        private void RevertEffectScopeAware<TSection>(
            TSection snapGlobal,
            Dictionary<string, CarOverride> snapOverrides,
            Func<CarOverride, TSection> getSnapCarSection,
            Action<TSection> applyToGlobal,
            Action<CarOverride, TSection> applyToCarOverride,
            Action<CarOverride> clearCarOverride) where TSection : class
        {
            string carId = _activeCarId;

            // Live car-preset override path: dirty came from car-preset
            // edits, so revert restores the saved car preset's section.
            if (carId != null && Settings.CarOverrides != null
                && Settings.CarOverrides.TryGetValue(carId, out var liveCo) && liveCo != null
                && getSnapCarSection(liveCo) != null)
            {
                _lastPersistedCarOverrides.TryGetValue(carId, out var savedCo);
                var savedCarSection = savedCo != null ? getSnapCarSection(savedCo) : null;
                if (savedCarSection != null)
                {
                    applyToCarOverride(liveCo, savedCarSection);
                }
                else
                {
                    // Section wasn't in the saved car preset; drop the
                    // override so the section falls back to the game-preset
                    // global (restored below).
                    clearCarOverride(liveCo);
                    if (snapGlobal != null) applyToGlobal(snapGlobal);
                }
                return;
            }

            // Legacy snap.CarOverrides path (pre-Model-G presets).
            CarOverride snapCar = null;
            if (carId != null && snapOverrides != null) snapOverrides.TryGetValue(carId, out snapCar);
            var snapCarSection = snapCar != null ? getSnapCarSection(snapCar) : null;
            if (snapCarSection != null && carId != null)
            {
                if (Settings.CarOverrides == null) Settings.CarOverrides = new Dictionary<string, CarOverride>();
                if (!Settings.CarOverrides.TryGetValue(carId, out liveCo) || liveCo == null)
                    Settings.CarOverrides[carId] = liveCo = new CarOverride();
                applyToCarOverride(liveCo, snapCarSection);
                return;
            }

            // Plain global revert: no per-car scope involved.
            if (snapGlobal != null) applyToGlobal(snapGlobal);
        }

        /// <summary>Apply a named preset from the library. Sets it as the
        /// currently-active preset. No game default is changed.</summary>
        /// <returns>true if applied; false if the preset name doesn't exist.</returns>
        public bool ApplyPreset(string presetName)
        {
            if (Settings?.Presets == null || string.IsNullOrEmpty(presetName)) return false;
            if (!Settings.Presets.TryGetValue(presetName, out var snap) || snap == null) return false;
            ApplyGamePreset(snap);
            _activePresetName = presetName;
            SimHub.Logging.Current.Info($"[TF4ALL] Applied preset '{presetName}'.");
            return true;
        }

        /// <summary>Apply a preset but keep the user's current personal FFB
        /// scale. For the duplicate-reuse save paths: two presets count as
        /// "identical" with FfbScale excluded from the content hash, so a
        /// save that reuses an existing preset must not adopt that preset's
        /// stored FFB and yank live wheel strength (the user tuned it since).
        /// MasterGain is never applied from a preset, so FfbScale is the only
        /// personal field to protect.</summary>
        public bool ApplyPresetKeepingPersonalFfb(string presetName)
        {
            if (Settings == null) return false;
            float keepFfb = Settings.FfbScale;
            if (!ApplyPreset(presetName)) return false;
            if (Math.Abs(Settings.FfbScale - keepFfb) > 1e-6f)
            {
                Settings.FfbScale = keepFfb;
                if (_device != null) _device.FfbScale = keepFfb;
            }
            return true;
        }

        /// <summary>Snapshot the current settings into the library under the
        /// given name. Overwrites any existing preset with that name. Sets it
        /// as the active preset. Refuses to overwrite built-in presets, the
        /// UI must fork to a user-named preset for those.</summary>
        public bool SavePresetAs(string presetName)
        {
            if (Settings == null || string.IsNullOrEmpty(presetName)) return false;
            // Clear any stale duplicate name from a prior call up front, before
            // any early return. A non-duplicate refusal below (built-in name,
            // write failure) must not leave a caller's ReuseDuplicateOrNull
            // acting on a duplicate name recorded by an earlier save.
            LastLocalDuplicateName = null;
            // Non-dev: built-ins are read-only (caller forks). DEV authoring
            // mode may overwrite a built-in in place; user presets always save.
            if (IsBuiltinPreset(presetName) && !DevMode)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Refusing to overwrite built-in preset '{presetName}'.");
                return false;
            }
            // Fold in-car draft edits into the globals first so the snapshot
            // below captures what the user is actually hearing. Without this,
            // the header Save / fork / save-as paths silently wrote the
            // pre-edit globals and the edited sections stayed dirty (the
            // per-effect save popover got this right via PromoteSectionToGlobal;
            // the whole-preset paths never did).
            FoldDraftSectionsIntoGlobals();
            // Skip the active-preset rename + log on disk failure so the
            // UI's "Saved as X" status doesn't drift from the on-disk
            // truth. The PersistGamePresetToFolder warn-log records the
            // exception details.
            var fresh = SnapshotCurrentAsPreset();
            // Carry forward community-upload tracking when we're overwriting
            // an existing preset by name. SnapshotCurrentAsPreset() rebuilds
            // from the live Settings.* fields, which don't hold per-preset
            // upload metadata; without this carry-forward, every Save would
            // null out CommunityUploadedById / etc and the Share button
            // gate would think the preset was never uploaded - silently
            // skipping the Update-vs-Share-as-new chooser on the next
            // share, and starting a duplicate community row.
            if (Settings.Presets != null
                && Settings.Presets.TryGetValue(presetName, out var prior)
                && prior != null)
            {
                fresh.CommunitySourceId          = prior.CommunitySourceId;
                fresh.CommunityUploadedById      = prior.CommunityUploadedById;
                fresh.CommunityUploadedByUserId  = prior.CommunityUploadedByUserId;
                fresh.CommunityUploadedBodyHash  = prior.CommunityUploadedBodyHash;
                fresh.CommunityUploadedVersion   = prior.CommunityUploadedVersion;
            }
            // New-name saves must not duplicate an existing preset's tuning
            // (owner rule 2026-07-13); overwriting the same name is the
            // normal save path and always proceeds. Callers can read
            // LastLocalDuplicateName to phrase the refusal.
            LastLocalDuplicateName = null;
            if (Settings.Presets == null || !Settings.Presets.ContainsKey(presetName))
            {
                string dup = FindGamePresetNameWithSameContent(fresh, excludeName: presetName);
                if (dup != null)
                {
                    LastLocalDuplicateName = dup;
                    SimHub.Logging.Current.Warn(
                        $"[TF4ALL] Refusing to save '{presetName}': identical to existing preset '{dup}'.");
                    return false;
                }
            }
            if (!PersistGamePresetToFolder(presetName, fresh)) return false;
            _activePresetName = presetName;
            PersistSettingsCore();
            RequestAutoBackup();   // preset file changed: arm auto-sync (no-op unless enabled)
            SimHub.Logging.Current.Info($"[TF4ALL] Saved preset '{presetName}'.");
            return true;
        }

        /// <summary>Save ONLY the targeted section into the active preset's
        /// in-memory snapshot, leaving every other section untouched on disk.
        /// Inverse of <see cref="RevertSection"/>. Returns false when the
        /// active preset is missing or built-in (built-ins can't be
        /// overwritten in place; caller forks instead). Caller is
        /// responsible for clearing the section's dirty bit + refreshing
        /// the UI.</summary>
        public bool SaveSectionToActivePreset(SectionKind kind)
        {
            if (Settings?.Presets == null) return false;
            if (string.IsNullOrEmpty(_activePresetName)) return false;
            if (IsBuiltinPreset(_activePresetName) && !DevMode) return false; // DEV may edit built-ins in place
            if (!Settings.Presets.TryGetValue(_activePresetName, out var snap) || snap == null) return false;

            switch (kind)
            {
                case SectionKind.Master:
                    snap.FfbScale                = Settings.FfbScale;
                    snap.FfbInvertSign           = Settings.FfbInvertSign;
                    snap.FfbSmoothTimeConstantMs = Settings.FfbSmoothTimeConstantMs;
                    break;
                case SectionKind.SpikeReduction:
                    snap.FfbSpikeTamingEnabled  = Settings.FfbSpikeTamingEnabled;
                    snap.FfbSpikeUseSlewLimiter = Settings.FfbSpikeUseSlewLimiter;
                    snap.FfbSpikeMaxLsbPerMs    = Settings.FfbSpikeMaxLsbPerMs;
                    snap.FfbPeakSoftLimitLsb    = Settings.FfbPeakSoftLimitLsb;
                    break;
                case SectionKind.StationarySpring:
                    snap.StationarySpringEnabled   = Settings.StationarySpringEnabled;
                    snap.StationarySpringStrength  = Settings.StationarySpringStrength;
                    snap.StationarySpringCutoffKmh = Settings.StationarySpringCutoffKmh;
                    break;
                case SectionKind.Ducking:
                    snap.DuckingEnabled = Settings.DuckingEnabled;
                    snap.DuckDepth     = Settings.DuckDepth;
                    snap.DuckAttackMs  = Settings.DuckAttackMs;
                    snap.DuckReleaseMs = Settings.DuckReleaseMs;
                    snap.DuckFrequencyAware = Settings.DuckFrequencyAware;
                    break;
                case SectionKind.Airborne:
                    snap.Airborne = Clone(Settings.Airborne);
                    break;
                case SectionKind.ImplementThud:
                    snap.ImplementThud = Clone(Settings.ImplementThud);
                    break;
                case SectionKind.Engine:     snap.EnginePulse  = Clone(Settings.EnginePulse);     break;
                case SectionKind.Bumps:      snap.RoadBumps    = Clone(Settings.RoadBumps);       break;
                case SectionKind.Traction:   snap.TractionLoss = Clone(Settings.TractionLoss);    break;
                case SectionKind.AxleSlip:   snap.AxleSlip     = Clone(Settings.AxleSlip);        break;
                case SectionKind.KerbThump:  snap.KerbThump    = Clone(Settings.KerbThump);       break;
                case SectionKind.LockupJudder: snap.LockupJudder = Clone(Settings.LockupJudder);  break;
                case SectionKind.Shift:      snap.GearShift    = Clone(Settings.GearShift);       break;
                case SectionKind.Abs:        snap.AbsClick     = Clone(Settings.AbsClick);        break;
                case SectionKind.PitLimiter: snap.PitLimiter   = Clone(Settings.PitLimiter);      break;
                case SectionKind.Drs:        snap.Drs          = Clone(Settings.Drs);             break;
                case SectionKind.Collision:  snap.Collision    = Clone(Settings.Collision);       break;
                case SectionKind.RevLimiter: snap.RevLimiter   = Clone(Settings.RevLimiter);      break;
                case SectionKind.Audio:      snap.AudioCapture = CloneOrNull(Settings.AudioCapture); break;
                default: return false;
            }
            // Clear the seeded-preset sentinel on first edit so the row
            // becomes the user's work the moment they touch a slider.
            // (Without this clear, the PackName sentinel would block the
            // attribution stamp below and the next backfill prompt.)
            if (string.Equals(NullIfBlank(snap.PackName), SeededPresetSentinel, StringComparison.Ordinal))
                snap.PackName = null;
            // Attribute the section edit to the current author when the
            // preset doesn't already carry attribution (community packs +
            // already-stamped local saves keep theirs).
            if (NullIfBlank(snap.Author) == null && NullIfBlank(snap.PackName) == null)
                snap.Author = CurrentAuthorForStamp();
            // Persist the whole preset to its file (user library or, for DEV
            // editing a built-in, the built-in folder). If the disk write
            // fails, propagate the failure to the caller so the UI doesn't
            // clear its dirty bit on a section edit that was never saved.
            if (!PersistGamePresetToFolder(_activePresetName, snap))
            {
                SimHub.Logging.Current.Warn(
                    $"[TF4ALL] Couldn't save {kind} into preset '{_activePresetName}'.");
                return false;
            }
            PersistSettingsCore();
            RequestAutoBackup();   // preset file changed: arm auto-sync (no-op unless enabled)
            SimHub.Logging.Current.Info($"[TF4ALL] Saved {kind} into preset '{_activePresetName}' (scoped).");
            return true;
        }

        /// <summary>Save ONLY the targeted section into the active car's
        /// preset file on disk. Patches the in-memory "last persisted" car
        /// override snapshot for this section (using the live value),
        /// writes the patched override out, and updates the persisted
        /// snapshot. Other sections in the car preset file stay at their
        /// previously-saved values. Returns false on built-ins (forks
        /// instead) or when there's no active car / car preset.</summary>
        public bool SaveSectionToActiveCarOverride(SectionKind kind)
        {
            if (_carStore == null || string.IsNullOrEmpty(_activeCarId)) return false;
            string presetName = GetActiveCarPresetName(_activeCarId);
            if (string.IsNullOrEmpty(presetName)) return false;
            bool isBuiltin = IsCarPresetBuiltin(_activeCarId, presetName);
            if (isBuiltin && !DevMode) return false;   // non-dev: caller forks
            if (Settings?.CarOverrides == null) return false;
            if (!Settings.CarOverrides.TryGetValue(_activeCarId, out var live) || live == null) return false;

            // Build the to-be-persisted override by starting from whatever's
            // currently on disk (cached in _lastPersistedCarOverrides) and
            // patching in just the targeted section from live.
            CarOverride patched;
            if (_lastPersistedCarOverrides.TryGetValue(_activeCarId, out var prev) && prev != null)
                patched = CloneCarOverride(prev);
            else
                patched = new CarOverride();

            switch (kind)
            {
                case SectionKind.Engine:     patched.EnginePulse  = live.EnginePulse  != null ? Clone(live.EnginePulse)  : null; break;
                case SectionKind.Bumps:      patched.RoadBumps    = live.RoadBumps    != null ? Clone(live.RoadBumps)    : null; break;
                case SectionKind.Traction:   patched.TractionLoss = live.TractionLoss != null ? Clone(live.TractionLoss) : null; break;
                case SectionKind.AxleSlip:   patched.AxleSlip     = live.AxleSlip     != null ? Clone(live.AxleSlip)     : null; break;
                case SectionKind.KerbThump:  patched.KerbThump    = live.KerbThump    != null ? Clone(live.KerbThump)    : null; break;
                case SectionKind.LockupJudder: patched.LockupJudder = live.LockupJudder != null ? Clone(live.LockupJudder) : null; break;
                case SectionKind.Shift:      patched.GearShift    = live.GearShift    != null ? Clone(live.GearShift)    : null; break;
                case SectionKind.Abs:        patched.AbsClick     = live.AbsClick     != null ? Clone(live.AbsClick)     : null; break;
                case SectionKind.PitLimiter: patched.PitLimiter   = live.PitLimiter   != null ? Clone(live.PitLimiter)   : null; break;
                case SectionKind.Drs:        patched.Drs          = live.Drs          != null ? Clone(live.Drs)          : null; break;
                case SectionKind.Collision:  patched.Collision    = live.Collision    != null ? Clone(live.Collision)    : null; break;
                case SectionKind.RevLimiter: patched.RevLimiter   = live.RevLimiter   != null ? Clone(live.RevLimiter)   : null; break;
                case SectionKind.Audio:      patched.AudioCapture = CloneOrNull(live.AudioCapture); break;
                case SectionKind.Airborne:   patched.Airborne     = live.Airborne     != null ? Clone(live.Airborne)     : null; break;
                default: return false;
            }

            if (isBuiltin)
            {
                // DEV: write through to the factory folder. LoadAndMigrateCarPresets
                // (called inside the helper) refreshes the live + persisted caches.
                WriteCarBuiltinThroughDev(_activeCarId, presetName, patched);
            }
            else
            {
                // Save reports I/O failure via its return. On failure leave
                // the baseline as-is so the section stays dirty and the
                // caller can retry, instead of marking it saved against a
                // file that was never written.
                if (!_carStore.Save(_activeCarId, presetName, _activeGame ?? "", patched, isBuiltin: false,
                        defaultAuthor: CurrentAuthorForStamp()))
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Save of section {kind} into car preset '{presetName}' for '{_activeCarId}' failed (see prior log line).");
                    return false;
                }
                // Match Save's keep-rule (empty-but-tracked files are kept).
                if (patched.IsEmpty && !patched.HasCommunityTracking)
                    _lastPersistedCarOverrides.Remove(_activeCarId);
                else
                    _lastPersistedCarOverrides[_activeCarId] = CloneCarOverride(patched);
            }
            SimHub.Logging.Current.Info($"[TF4ALL] Saved {kind} into car preset '{presetName}' for '{_activeCarId}' (scoped).");
            return true;
        }

        /// <summary>Delete a preset from the library. Also clears any
        /// GameDefaults entries that pointed to this preset. Refuses on
        /// built-in presets, they're factory defaults the user can always
        /// fall back to.</summary>
        public bool DeletePreset(string presetName)
        {
            if (Settings?.Presets == null || string.IsNullOrEmpty(presetName)) return false;
            bool wasBuiltin = IsBuiltinPreset(presetName);
            // Non-dev: built-ins are protected. DEV authoring may delete them
            // (also removes the folder file + its default bindings below).
            if (wasBuiltin && !DevMode)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Refusing to delete built-in preset '{presetName}'.");
                return false;
            }

            // Delete the preset file from its source folder + drop any defaults
            // (in that folder) that pointed at the now-deleted preset.
            try
            {
                string folder = wasBuiltin ? BuiltinPresets.CurrentFolder : UserPresets.CurrentFolder;
                BuiltinPresetWriter.DeleteGame(folder, presetName);
                // Remove default bindings that referenced this preset in the
                // folder. Defaults live in user library by default; if the
                // built-in folder has a default to this name, drop that too.
                foreach (var src in new[] { UserPresets.GameDefaults, wasBuiltin ? BuiltinPresets.GameDefaultBindings : null })
                {
                    if (src == null) continue;
                    var hits = new List<string>();
                    foreach (var kv in src)
                        if (kv.Value == presetName) hits.Add(kv.Key);
                    string defFolder = src == UserPresets.GameDefaults ? UserPresets.CurrentFolder : BuiltinPresets.CurrentFolder;
                    foreach (var k in hits) BuiltinPresetWriter.RemoveGameDefault(defFolder, k);
                }
                if (wasBuiltin) BuiltinPresets.Reload(); else UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Delete '{presetName}' failed: {ex.Message}");
                return false;
            }

            if (_activePresetName == presetName) _activePresetName = null;
            PersistSettingsCore();
            RequestAutoBackup();   // preset file deleted: arm auto-sync so the deletion propagates
            SimHub.Logging.Current.Info($"[TF4ALL] Deleted preset '{presetName}'.");
            return true;
        }

        /// <summary>Bind a preset as the auto-load default for the active game.
        /// Subsequent game changes into this game will apply the preset.</summary>
        public void SetDefaultPresetForActiveGame(string presetName)
        {
            if (string.IsNullOrEmpty(_activeGame)) return;
            SetDefaultPresetForGame(_activeGame, presetName);
        }

        /// <summary>Remove the auto-load binding for the active game.</summary>
        public void ClearDefaultPresetForActiveGame()
        {
            if (string.IsNullOrEmpty(_activeGame)) return;
            ClearDefaultPresetForGame(_activeGame);
        }

        /// <summary>Rename a game preset in the library. Updates any
        /// GameDefaults entries that pointed to the old name and the
        /// ActivePresetName if it was the renamed one. Refuses on built-ins
        /// (factory names are part of the brand) and when the target name
        /// already exists. Used by the preset manager.</summary>
        public bool RenamePreset(string oldName, string newName)
        {
            if (Settings?.Presets == null) return false;
            if (string.IsNullOrEmpty(oldName) || string.IsNullOrEmpty(newName)) return false;
            if (string.Equals(oldName, newName, StringComparison.Ordinal)) return true;
            bool wasBuiltin = IsBuiltinPreset(oldName);
            // Non-dev: built-in names are part of the brand. DEV authoring may
            // rename them (renames the folder file + repoints defaults below).
            if (wasBuiltin && !DevMode)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Refusing to rename built-in preset '{oldName}'.");
                return false;
            }
            if (!Settings.Presets.TryGetValue(oldName, out var snap) || snap == null) return false;
            if (Settings.Presets.ContainsKey(newName)) return false;

            // Rename the file in the right folder; RenameGame also repoints any
            // game-defaults entries in that folder from old -> new.
            try
            {
                string folder = wasBuiltin ? BuiltinPresets.CurrentFolder : UserPresets.CurrentFolder;
                BuiltinPresetWriter.RenameGame(folder, oldName, newName);
                if (wasBuiltin) BuiltinPresets.Reload(); else UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Rename '{oldName}' -> '{newName}' failed: {ex.Message}");
                return false;
            }

            if (_activePresetName == oldName) _activePresetName = newName;
            PersistSettingsCore();
            RequestAutoBackup();   // preset renamed (file path changed): arm auto-sync
            SimHub.Logging.Current.Info($"[TF4ALL] Renamed preset '{oldName}' to '{newName}'.");
            return true;
        }

        /// <summary>Deep-copy a preset. JSON round-trip so the clone is
        /// independent of the source. newName null/blank = auto-name with the
        /// library's numeric-suffix convention ("Source (2)", first free
        /// number): Duplicate is the one sanctioned way to hold two presets
        /// with identical tuning, so it self-names instead of prompting and
        /// can never collide (owner call 2026-07-13). Returns the final name,
        /// or null on failure / explicit-name collision.</summary>
        public string DuplicatePreset(string sourceName, string newName = null)
        {
            if (Settings?.Presets == null) return null;
            if (string.IsNullOrEmpty(sourceName)) return null;
            if (!Settings.Presets.TryGetValue(sourceName, out var snap) || snap == null) return null;
            if (string.IsNullOrWhiteSpace(newName)) newName = MakeUniqueGamePresetName(sourceName);
            else if (Settings.Presets.ContainsKey(newName)) return null;

            // The duplicate always lands in the USER library (a copy of a
            // built-in becomes a normal user preset; the owner uses DEV +
            // Export-as-built-in to promote one). Stamp the duplicator as
            // the author when the source had none (the user IS the author
            // of this divergent copy); preserve existing attribution so
            // forks of a community pack stay linked to their origin.
            if (NullIfBlank(snap.Author) == null && NullIfBlank(snap.PackName) == null)
            {
                snap = Newtonsoft.Json.JsonConvert.DeserializeObject<GameSettingsSnapshot>(
                    Newtonsoft.Json.JsonConvert.SerializeObject(snap));
                snap.Author = CurrentAuthorForStamp();
            }
            var json = Newtonsoft.Json.JsonConvert.SerializeObject(snap, Newtonsoft.Json.Formatting.Indented);
            try
            {
                BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, newName, json);
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Duplicate '{sourceName}' -> '{newName}' failed: {ex.Message}");
                return null;
            }
            PersistSettingsCore();
            RequestAutoBackup();   // new preset file: arm auto-sync so the duplicate propagates
            SimHub.Logging.Current.Info($"[TF4ALL] Duplicated preset '{sourceName}' as '{newName}'.");
            return newName;
        }

        /// <summary>Bind a preset to auto-load for any game (not just the
        /// active one). Used by the preset manager's per-row Set
        /// default action. Returns false if the named preset isn't in the
        /// library.</summary>
        public bool SetDefaultPresetForGame(string gameName, string presetName)
        {
            if (Settings == null) return false;
            if (string.IsNullOrEmpty(gameName) || string.IsNullOrEmpty(presetName)) return false;
            if (Settings.Presets == null || !Settings.Presets.ContainsKey(presetName)) return false;

            // Per-user defaults model: first-setter establishes the
            // device-wide binding (the user-library JSON, shared across
            // all local users); every subsequent set goes to the active
            // user's slot override so other accounts on this install
            // keep their own choice.
            bool deviceWideAlreadySet =
                UserPresets.GameDefaults != null
                && UserPresets.GameDefaults.TryGetValue(gameName, out var existing)
                && !string.IsNullOrEmpty(existing);
            // DEV authoring always writes the built-in folder (the
            // factory baseline), regardless of the per-user model.
            if (DevMode)
            {
                try
                {
                    BuiltinPresetWriter.SetGameDefault(BuiltinPresets.CurrentFolder, gameName, presetName);
                    BuiltinPresets.Reload();
                    RebuildPresetCacheFromFolders();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] DEV set game default for '{gameName}' failed: {ex.Message}");
                    return false;
                }
                PersistSettingsCore();
                SimHub.Logging.Current.Info($"[TF4ALL] DEV: '{presetName}' set as built-in default for '{gameName}'.");
                return true;
            }

            if (!deviceWideAlreadySet)
            {
                // No device-wide binding yet for this game - seed it.
                // The active user implicitly inherits via the file.
                try
                {
                    BuiltinPresetWriter.SetGameDefault(UserPresets.CurrentFolder, gameName, presetName);
                    UserPresets.Reload();
                    RebuildPresetCacheFromFolders();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Set game default for '{gameName}' failed: {ex.Message}");
                    return false;
                }
            }
            else
            {
                // Device-wide is taken; route this set to the active
                // user's slot override and rebuild the effective view
                // so the in-memory dict reflects the choice immediately.
                var slot = GetActiveUserSlot();
                if (slot == null) return false;
                if (slot.OverrideGameDefaults == null)
                    slot.OverrideGameDefaults = new Dictionary<string, string>();
                slot.OverrideGameDefaults[gameName] = presetName;
                RebuildPresetCacheFromFolders();
            }
            PersistSettingsCore();
            RequestAutoBackup();   // default binding changed: arm auto-sync
            SimHub.Logging.Current.Info($"[TF4ALL] '{presetName}' set as default for '{gameName}'.");
            return true;
        }

        /// <summary>Drop the auto-load binding for a specific game.
        /// Per-user semantics: if the active user has their OWN override
        /// for this game, remove the override first (they fall back to
        /// the device-wide default). Otherwise clear the device-wide
        /// file binding. DEV authoring always touches the built-in
        /// folder regardless of slot state.</summary>
        public bool ClearDefaultPresetForGame(string gameName)
        {
            if (Settings?.GameDefaults == null || string.IsNullOrEmpty(gameName)) return false;
            if (DevMode)
            {
                try
                {
                    BuiltinPresetWriter.RemoveGameDefault(BuiltinPresets.CurrentFolder, gameName);
                    BuiltinPresets.Reload();
                    RebuildPresetCacheFromFolders();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] DEV clear game default for '{gameName}' failed: {ex.Message}");
                    return false;
                }
                PersistSettingsCore();
                SimHub.Logging.Current.Info($"[TF4ALL] DEV: cleared built-in default for '{gameName}'.");
                return true;
            }

            var slot = GetActiveUserSlot();
            if (slot?.OverrideGameDefaults != null
                && slot.OverrideGameDefaults.Remove(gameName))
            {
                RebuildPresetCacheFromFolders();
                PersistSettingsCore();
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] Cleared per-user default for '{gameName}' (device-wide kept).");
                return true;
            }
            try
            {
                BuiltinPresetWriter.RemoveGameDefault(UserPresets.CurrentFolder, gameName);
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Clear game default for '{gameName}' failed: {ex.Message}");
                return false;
            }
            PersistSettingsCore();
            SimHub.Logging.Current.Info($"[TF4ALL] Cleared default preset for '{gameName}'.");
            return true;
        }

        /// <summary>Enter offline edit mode for a named preset. Snapshots the
        /// current live settings (so Discard can restore them) then applies
        /// the preset so the user can tweak its sections in the regular UI.
        /// Returns false if the preset doesn't exist. Callers (the
        /// SettingsControl) update their banner UI on success.</summary>
        public bool EnterOfflineEdit(string presetName)
        {
            if (Settings?.Presets == null || string.IsNullOrEmpty(presetName)) return false;
            if (!Settings.Presets.TryGetValue(presetName, out var snap) || snap == null) return false;
            _preEditSnapshot = SnapshotCurrentAsPreset();
            _preEditActivePresetName = _activePresetName;
            ApplyGamePreset(snap);
            _activePresetName = presetName;
            _offlineEditPresetName = presetName;
            SimHub.Logging.Current.Info($"[TF4ALL] Offline edit mode: editing preset '{presetName}'.");
            return true;
        }

        /// <summary>Exit offline edit mode by writing the in-memory edits
        /// back into the preset being edited. Built-ins refuse in-place
        /// overwrite, caller falls back to <see cref="ExitOfflineEditSaveAs"/>
        /// for those. Returns false on the built-in case so the caller can
        /// prompt for a new name.</summary>
        public bool ExitOfflineEditSave()
        {
            if (!IsOfflineEditing) return true;
            string name = _offlineEditPresetName;
            // Non-dev: built-ins fork (caller prompts for a new name). DEV
            // authoring mode overwrites the built-in in place (SavePresetAs
            // write-through updates the folder file too).
            if (IsBuiltinPreset(name) && !DevMode)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Can't overwrite built-in preset '{name}' on edit-mode save; fork via Save as new.");
                return false;
            }
            if (!SavePresetAs(name)) return false;   // write failed (logged) -> caller shows the dialog
            RestorePreEditGameState();     // return to the previously-active preset
            SimHub.Logging.Current.Info($"[TF4ALL] Saved '{name}' and exited offline edit (restored prior preset).");
            return true;
        }

        /// <summary>Exit offline edit mode by saving the in-memory edits as
        /// a brand-new preset (forking off a built-in), then returning to the
        /// previously-active preset.</summary>
        public bool ExitOfflineEditSaveAs(string newName)
        {
            if (!IsOfflineEditing || string.IsNullOrEmpty(newName)) return false;
            if (Settings.Presets != null && Settings.Presets.ContainsKey(newName)) return false;
            if (!SavePresetAs(newName)) return false;
            RestorePreEditGameState();
            SimHub.Logging.Current.Info($"[TF4ALL] Saved as new '{newName}' and exited offline edit (restored prior preset).");
            return true;
        }

        /// <summary>Variant of <see cref="ExitOfflineEditSaveAs"/> used by the
        /// "silent fork on save of a built-in" path: persists the new preset,
        /// keeps the new preset as the active one (skipping the restore-prior
        /// step), and binds it as the default for the active game so future
        /// car loads pick it up. The user sees a no-friction "saved" outcome
        /// where the fork they just made is the live + default preset for
        /// the game they're driving.</summary>
        public bool ExitOfflineEditSaveAsAndApply(string newName)
        {
            if (!IsOfflineEditing || string.IsNullOrEmpty(newName)) return false;
            if (Settings.Presets != null && Settings.Presets.ContainsKey(newName)) return false;

            if (!SavePresetAs(newName)) return false;   // write failed (logged) -> caller shows the dialog

            // Clear offline-edit state but do NOT restore the prior live
            // state; the new preset stays the active one.
            _offlineEditPresetName    = null;
            _preEditSnapshot          = null;
            _preEditActivePresetName  = null;

            // Bind as the game default so future loads of this game pick it.
            // Through SetDefaultPresetForGame, not a raw dict write: the raw
            // write skipped the per-user slot routing and the device-wide
            // file, so the next RebuildPresetCacheFromFolders dropped it.
            if (!string.IsNullOrEmpty(_activeGame))
                SetDefaultPresetForGame(_activeGame, newName);

            SimHub.Logging.Current.Info(
                $"[TF4ALL] Silent-forked to '{newName}'"
                + (!string.IsNullOrEmpty(_activeGame)
                    ? $" + bound as default for {_activeGame}"
                    : "")
                + ".");
            return true;
        }

        /// <summary>Exit offline edit mode and restore the previously-active
        /// preset (dropping any unsaved edits). Used by the banner's Done (when
        /// nothing's unsaved) and the discard path.</summary>
        public void ExitOfflineEditDiscard()
        {
            if (!IsOfflineEditing) return;
            string was = _offlineEditPresetName;
            RestorePreEditGameState();
            SimHub.Logging.Current.Info($"[TF4ALL] Exited offline edit mode (dropped unsaved edits to '{was}').");
        }

        // Re-apply the preset that was active before editing began, by name from
        // the library. Handles both cases correctly: if you edited your active
        // preset, re-loading it picks up its now-saved values (after Save) or the
        // unchanged saved values (after a no-save exit, reverting unsaved tweaks);
        // if you edited a different preset, this returns you to the one you were
        // running. Falls back to the pre-edit live snapshot if the prior preset
        // is gone.
        private void RestorePreEditGameState()
        {
            string prior = _preEditActivePresetName;
            _offlineEditPresetName = null;
            if (!string.IsNullOrEmpty(prior) && Settings?.Presets != null
                && Settings.Presets.TryGetValue(prior, out var snap) && snap != null)
            {
                ApplyGamePreset(snap);
                _activePresetName = prior;
            }
            else if (_preEditSnapshot != null)
            {
                ApplyGamePreset(_preEditSnapshot);
                _activePresetName = prior;
            }
            _preEditSnapshot = null;
            _preEditActivePresetName = null;
        }

        // ---------- Car-preset offline edit ----------

        private string GetCarPresetGame(string carId, string presetName)
        {
            var presets = GetCarPresets(carId);
            return presets != null && presets.TryGetValue(presetName, out var e) ? e?.GameName : null;
        }

        /// <summary>Enter offline edit for one car preset. Snapshots the live
        /// state, loads that car's GAME default preset as the baseline (so the
        /// override sits on the right globals and nothing reads as spuriously
        /// dirty), then pins the car and loads its override. The car is frozen
        /// against live telemetry until exit (see DataUpdate). Returns false if
        /// the inputs are empty.</summary>
        public bool EnterOfflineEditCar(string carId, string presetName)
        {
            if (string.IsNullOrEmpty(carId) || string.IsNullOrEmpty(presetName)) return false;

            _preEditCarSnapshot         = SnapshotCurrentAsPreset();
            _preEditCarActiveId         = _activeCarId;
            _preEditCarActivePresetName = _activePresetName;
            _preEditCarActiveGame       = _activeGame;

            // Baseline: the default game preset for the car's own game, so the
            // override compares against the right globals (fixes the "wrong
            // preset -> everything dirty" case when the running game differs).
            string carGame = GetCarPresetGame(carId, presetName);
            // Pin the edited car's game as the active game for the session so
            // the header + Car-facts panel (name / engine / redline) read and
            // WRITE against the right (game, carId) key, not an empty or live-
            // game key. Without this, editing a car you're not driving left
            // the Car-facts name blank and its Save a no-op. Restored on exit.
            if (!string.IsNullOrEmpty(carGame)) _activeGame = carGame;
            if (!string.IsNullOrEmpty(carGame)
                && Settings?.GameDefaults != null
                && Settings.GameDefaults.TryGetValue(carGame, out var gp)
                && !string.IsNullOrEmpty(gp)
                && Settings.Presets != null
                && Settings.Presets.TryGetValue(gp, out var gsnap) && gsnap != null)
            {
                ApplyGamePreset(gsnap);
                _activePresetName = gp;
            }

            if (!SelectCarForEditing(carId, presetName)) return false;
            _offlineEditCarId         = carId;
            _offlineEditCarPresetName = presetName;
            SimHub.Logging.Current.Info($"[TF4ALL] Offline edit mode: editing car preset '{presetName}' for '{carId}' (baseline game '{carGame}').");
            return true;
        }

        // Restore the live state captured when car-edit began, then unfreeze so
        // telemetry re-asserts the real car. Shared by all three exits.
        private void RestorePreEditCarState()
        {
            _offlineEditCarId         = null;   // unfreeze first
            _offlineEditCarPresetName = null;
            if (_preEditCarSnapshot != null) ApplyGamePreset(_preEditCarSnapshot);
            _activePresetName = _preEditCarActivePresetName;
            _activeCarId      = _preEditCarActiveId;
            _activeGame       = _preEditCarActiveGame;
            _preEditCarSnapshot         = null;
            _preEditCarActiveId         = null;
            _preEditCarActivePresetName = null;
            _preEditCarActiveGame       = null;
        }

        // DEV authoring: write the frozen car's edited override through to the
        // built-in folder as a CarPresetFile (IsBuiltin=true), reload, and push
        // the folder built-ins back into the live car store so the edit is
        // active. Source of truth stays the folder.
        private void WriteCarBuiltinThroughDev(string carId, string presetName)
        {
            if (Settings?.CarOverrides == null
                || !Settings.CarOverrides.TryGetValue(carId, out var ov) || ov == null) return;
            WriteCarBuiltinThroughDev(carId, presetName, ov);
        }

        // DEV authoring overload: write an explicit override through to the
        // built-in folder. Used by section-scoped saves where the value being
        // persisted is patched (live override + one section replacement), not
        // the live override as-is.
        private void WriteCarBuiltinThroughDev(string carId, string presetName, CarOverride ov)
        {
            try
            {
                if (ov == null) return;
                // Factory file uses on-disk name (no display suffix).
                string diskName = ToDiskName(presetName);
                string game = GetCarPresetGame(carId, presetName) ?? _activeGame ?? "";
                var file = new CarPresetFile
                {
                    Type = CarPresetFile.FileType, Version = 2,
                    GameName = game, CarId = carId,
                    PresetName = diskName, IsBuiltin = true, Override = ov,
                };
                string json = Newtonsoft.Json.JsonConvert.SerializeObject(
                    file, Newtonsoft.Json.Formatting.Indented);
                BuiltinPresetWriter.WriteCar(BuiltinPresets.CurrentFolder, game, carId, diskName, json);
                BuiltinPresets.Reload();
                LoadAndMigrateCarPresets();   // push folder built-ins into the live store
                SimHub.Logging.Current.Info($"[TF4ALL] DEV: wrote car '{carId}' through to the built-in folder.");
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] DEV car write-through failed for '{carId}': {ex.Message}");
            }
        }

        /// <summary>Save the car-edit in place (to the frozen car's preset).
        /// Non-dev refuses a built-in (returns false so the caller forks via
        /// Save as new). DEV authoring mode writes the edit through to the
        /// built-in folder instead. On success restores the pre-edit state.</summary>
        public bool ExitOfflineEditCarSave()
        {
            if (!IsOfflineEditingCar) return true;
            // DEV editing an existing built-in car: write the edit through to
            // its folder file. A new/user car preset stays a user preset
            // (promote later via 'Set as built-in').
            if (DevMode && IsActiveCarPresetBuiltin())
            {
                WriteCarBuiltinThroughDev(_offlineEditCarId, _offlineEditCarPresetName);
                RestorePreEditCarState();
                return true;
            }
            if (IsActiveCarPresetBuiltin()) return false;   // non-dev: fork
            // Propagate a real write failure so the caller shows "couldn't save"
            // and we DON'T restore/clear (which would drop the unsaved edit).
            if (!PersistActiveCarOverride()) return false;
            RestorePreEditCarState();
            return true;
        }

        public bool ExitOfflineEditCarSaveAs(string newName)
        {
            if (!IsOfflineEditingCar || string.IsNullOrEmpty(newName)) return false;
            if (!SaveActiveCarPresetAs(newName)) return false;
            RestorePreEditCarState();
            return true;
        }

        /// <summary>Variant of <see cref="ExitOfflineEditCarSaveAs"/> for the
        /// silent fork on save flow: persists the new car preset, keeps it
        /// applied to the active car, and skips the restore-prior step.
        /// SaveActiveCarPresetAs already updates CarDefaults[_activeCarId]
        /// so the bind side is handled there; this method's job is just to
        /// tear down the offline-edit state without re-applying the prior
        /// snapshot.</summary>
        public bool ExitOfflineEditCarSaveAsAndApply(string newName)
        {
            if (!IsOfflineEditingCar || string.IsNullOrEmpty(newName)) return false;
            if (!SaveActiveCarPresetAs(newName)) return false;

            _preEditCarSnapshot         = null;
            _preEditCarActiveId         = null;
            _preEditCarActivePresetName = null;

            SimHub.Logging.Current.Info(
                $"[TF4ALL] Silent-forked car preset to '{newName}' for '{_activeCarId}'.");
            return true;
        }

        public void ExitOfflineEditCarDiscard()
        {
            if (!IsOfflineEditingCar) return;
            DiscardUnsavedCarDraft(_offlineEditCarId); // drop the unsaved override edits
            RestorePreEditCarState();
        }

        /// <summary>Copy snapshot fields into Settings and re-push to live components.</summary>
        private void ApplyGamePreset(GameSettingsSnapshot snap)
        {
            if (snap == null || Settings == null) return;

            // FFB scale is PERSONAL: a downloaded / community preset must not
            // override the user's own value. Apply it only for locally-authored
            // presets (CommunitySourceId == null); for a community preset the
            // live (personal) value is left in place. Master gain is NOT applied
            // from any preset: it is a global setting, independent of presets.
            if (string.IsNullOrEmpty(snap.CommunitySourceId))
            {
                Settings.FfbScale            = SafeMath.SafeFloat(snap.FfbScale, 0.0f, 10.0f, 0.80f);
            }
            Settings.FfbInvertSign           = snap.FfbInvertSign;
            Settings.FfbSmoothTimeConstantMs = SafeMath.SafeFloat(snap.FfbSmoothTimeConstantMs, 0.0f, 1000.0f, 0.0f);
            Settings.FfbSpikeTamingEnabled   = snap.FfbSpikeTamingEnabled;
            Settings.FfbSpikeUseSlewLimiter  = snap.FfbSpikeUseSlewLimiter;
            Settings.FfbSpikeMaxLsbPerMs     = SafeMath.SafeFloat(snap.FfbSpikeMaxLsbPerMs, 0.0f, 65535.0f, 2508.36f);
            Settings.FfbPeakSoftLimitLsb     = SafeMath.SafeFloat(snap.FfbPeakSoftLimitLsb, 0.0f, 65535.0f, 2061.90f);
            Settings.DuckingEnabled          = snap.DuckingEnabled;
            Settings.DuckDepth               = SafeMath.SafeFloat(snap.DuckDepth, 0.0f, 1.0f, 0.60f);
            Settings.DuckAttackMs            = SafeMath.SafeFloat(snap.DuckAttackMs, 0.0f, 10000.0f, 5.0f);
            Settings.DuckReleaseMs           = SafeMath.SafeFloat(snap.DuckReleaseMs, 0.0f, 10000.0f, 80.0f);
            Settings.DuckFrequencyAware      = snap.DuckFrequencyAware;
            // Stationary spring: nullable in the snapshot. Null = preset predates
            // the field, so leave the user's current value untouched (migration).
            if (snap.StationarySpringEnabled.HasValue)   Settings.StationarySpringEnabled   = snap.StationarySpringEnabled.Value;
            if (snap.StationarySpringStrength.HasValue)  Settings.StationarySpringStrength  = snap.StationarySpringStrength.Value;
            if (snap.StationarySpringCutoffKmh.HasValue) Settings.StationarySpringCutoffKmh = snap.StationarySpringCutoffKmh.Value;

            if (snap.AudioCapture != null) Settings.AudioCapture = CloneOrNull(snap.AudioCapture);
            if (snap.EnginePulse  != null) Settings.EnginePulse  = Clone(snap.EnginePulse);
            if (snap.RoadBumps    != null) Settings.RoadBumps    = Clone(snap.RoadBumps);
            if (snap.TractionLoss != null) Settings.TractionLoss = Clone(snap.TractionLoss);
            if (snap.AxleSlip     != null) Settings.AxleSlip     = Clone(snap.AxleSlip);
            if (snap.KerbThump    != null) Settings.KerbThump    = Clone(snap.KerbThump);
            if (snap.LockupJudder != null) Settings.LockupJudder = Clone(snap.LockupJudder);
            if (snap.GearShift    != null) Settings.GearShift    = Clone(snap.GearShift);
            if (snap.AbsClick     != null) Settings.AbsClick     = Clone(snap.AbsClick);
            if (snap.PitLimiter   != null) Settings.PitLimiter   = Clone(snap.PitLimiter);
            if (snap.Drs          != null) Settings.Drs          = Clone(snap.Drs);
            if (snap.Collision    != null) Settings.Collision    = Clone(snap.Collision);
            if (snap.RevLimiter   != null) Settings.RevLimiter   = Clone(snap.RevLimiter);
            // Airborne ducking travels with the preset. Null on presets saved
            // before it existed; leave the live (global default) value in that
            // case so old presets don't wipe it. ApplyActiveCarOverride below
            // pushes it to the effect via ApplyAirborneSettings.
            if (snap.Airborne     != null) Settings.Airborne     = Clone(snap.Airborne);
            // Implement thud: same null-migration as Airborne.
            if (snap.ImplementThud != null) Settings.ImplementThud = Clone(snap.ImplementThud);
            // Per-car overrides are no longer carried by game presets (Model G):
            // they live in <plugin data>/Cars/<carId>.tfcar.json files,
            // independent of the active preset. Switching presets doesn't
            // touch per-car tuning. Legacy snap.CarOverrides (from old
            // saved presets) is intentionally ignored here, migration
            // already extracted any useful data into per-car files.

            // Push live: master, FFB tap, audio, and effects (via car-override apply).
            _mixer.MasterGain = Settings.MasterGain;
            if (_device != null)
            {
                _device.FfbScale                = Settings.FfbScale;
                _device.FfbInvertSign           = Settings.FfbInvertSign;
                _device.FfbSmoothTimeConstantMs = Settings.FfbSmoothTimeConstantMs;
                _device.FfbSpikeTamingEnabled   = Settings.FfbSpikeTamingEnabled;
                _device.FfbSpikeUseSlewLimiter  = Settings.FfbSpikeUseSlewLimiter;
                _device.FfbSpikeMaxLsbPerMs     = Settings.FfbSpikeMaxLsbPerMs;
                _device.FfbPeakSoftLimitLsb     = Settings.FfbPeakSoftLimitLsb;
            }
            if (_audio != null)
            {
                _audio.Enabled          = Settings.AudioCapture.Enabled;
                _audio.Gain             = Settings.AudioCapture.Gain;
                _audio.LowpassCutoffHz  = Settings.AudioCapture.LowpassCutoffHz;
                _audio.HighpassCutoffHz = Settings.AudioCapture.HighpassCutoffHz;
            }
            ApplyActiveCarOverride();
        }

        private static AudioCaptureSettings CloneOrNull(AudioCaptureSettings s)
            => s == null ? null : new AudioCaptureSettings { Enabled = s.Enabled, Gain = s.Gain, LowpassCutoffHz = s.LowpassCutoffHz, HighpassCutoffHz = s.HighpassCutoffHz };

        // ---------- single-preset export/import (sharing) ----------

        /// <summary>Snapshot of the current top-level settings, used by
        /// both "Save preset" and "Export preset". Per-car overrides are
        /// intentionally omitted: in Model G they live in per-car files
        /// independent of game presets, so applying a preset never touches
        /// per-car tuning.</summary>
        private GameSettingsSnapshot SnapshotCurrentAsPreset()
        {
            return new GameSettingsSnapshot
            {
                FfbScale                = Settings.FfbScale,
                FfbInvertSign           = Settings.FfbInvertSign,
                FfbSmoothTimeConstantMs = Settings.FfbSmoothTimeConstantMs,
                FfbSpikeTamingEnabled   = Settings.FfbSpikeTamingEnabled,
                FfbSpikeUseSlewLimiter  = Settings.FfbSpikeUseSlewLimiter,
                FfbSpikeMaxLsbPerMs     = Settings.FfbSpikeMaxLsbPerMs,
                FfbPeakSoftLimitLsb     = Settings.FfbPeakSoftLimitLsb,
                StationarySpringEnabled   = Settings.StationarySpringEnabled,
                StationarySpringStrength  = Settings.StationarySpringStrength,
                StationarySpringCutoffKmh = Settings.StationarySpringCutoffKmh,
                DuckingEnabled          = Settings.DuckingEnabled,
                DuckDepth               = Settings.DuckDepth,
                DuckAttackMs            = Settings.DuckAttackMs,
                DuckReleaseMs           = Settings.DuckReleaseMs,
                DuckFrequencyAware      = Settings.DuckFrequencyAware,
                AudioCapture            = CloneOrNull(Settings.AudioCapture),
                EnginePulse             = Clone(Settings.EnginePulse),
                RoadBumps               = Clone(Settings.RoadBumps),
                TractionLoss            = Clone(Settings.TractionLoss),
                AxleSlip                = Clone(Settings.AxleSlip),
                KerbThump               = Clone(Settings.KerbThump),
                LockupJudder            = Clone(Settings.LockupJudder),
                GearShift               = Clone(Settings.GearShift),
                AbsClick                = Clone(Settings.AbsClick),
                PitLimiter              = Clone(Settings.PitLimiter),
                Drs                     = Clone(Settings.Drs),
                Collision               = Clone(Settings.Collision),
                RevLimiter              = Clone(Settings.RevLimiter),
                Airborne                = Clone(Settings.Airborne),
                ImplementThud           = Clone(Settings.ImplementThud),
                // Attribution: stamp the persistent author so the Preset
                // Manager's Source column attributes this row to its
                // author. Null when SharingAuthor is unset (column reads
                // "Local"). Pack identity fields (PackName/AuthorVersion/
                // Description) stay null on user-saved snapshots — those
                // are populated only by the pack-import code path so
                // shared community presets retain their lineage.
                Author                  = CurrentAuthorForStamp(),
                // CarOverrides intentionally omitted, per-car tuning is
                // managed via per-car .tfcar.json files post-Model-G.
            };
        }

        // Trim and return null on blank so JSON serialization omits empty
        // strings instead of writing them out (cleaner files, and the
        // importer's null-check logic is straightforward).
        private static string NullIfBlank(string s)
        {
            if (string.IsNullOrWhiteSpace(s)) return null;
            string t = s.Trim();
            return t.Length == 0 ? null : t;
        }

        // Merge incoming CustomEngineDefs into the user's library by Id.
        // Existing local defs ALWAYS win on collision — the Id is supposed
        // to be stable across renames, so different content under the same
        // Id is either a genuine local edit the user shouldn't lose, or
        // backend corruption we shouldn't pave over. Logs both cases.
        //
        // Returns (added, skipped). Optionally constrains to a referenced-
        // ids subset (ImportPackSelective passes it; full-pack imports
        // pass null = merge every def in the wrapper).
        private (int added, int skipped) MergeImportedCustomEngines(
            IEnumerable<CustomEngineDef> incoming,
            HashSet<string> referencedIds = null)
        {
            if (incoming == null) return (0, 0);
            if (Settings == null) return (0, 0);
            if (Settings.CustomEngines == null) Settings.CustomEngines = new List<CustomEngineDef>();
            var existing = new Dictionary<string, CustomEngineDef>(StringComparer.Ordinal);
            foreach (var def in Settings.CustomEngines)
                if (def != null && !string.IsNullOrEmpty(def.Id) && !existing.ContainsKey(def.Id))
                    existing[def.Id] = def;

            int added = 0, skipped = 0;
            foreach (var def in incoming)
            {
                if (def == null || string.IsNullOrEmpty(def.Id)) continue;
                if (referencedIds != null && !referencedIds.Contains(def.Id)) continue;
                if (existing.TryGetValue(def.Id, out var local))
                {
                    if (!string.Equals(local.Pattern, def.Pattern, StringComparison.Ordinal)
                        || local.IsElectric != def.IsElectric
                        || local.ElectricMode != def.ElectricMode)
                    {
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Custom-engine import: keeping local def '{local.Name}' (Id {def.Id}); incoming '{def.Name}' has different content.");
                    }
                    skipped++;
                    continue;
                }
                Settings.CustomEngines.Add(new CustomEngineDef
                {
                    Id           = def.Id,
                    Name         = def.Name,
                    IsElectric   = def.IsElectric,
                    ElectricMode = def.ElectricMode,
                    Pattern      = def.Pattern,
                    Author       = NullIfBlank(def.Author),
                    // Carry community lineage (same as CloneCarOverride does for
                    // CarOverride). Dropping these made a downloaded engine look
                    // locally authored, so IsRedistributable short-circuits true
                    // and the author's AllowInPacks=false is bypassed on re-bundle.
                    CommunitySourceId         = def.CommunitySourceId,
                    CommunityUploadedById     = def.CommunityUploadedById,
                    CommunityUploadedByUserId = def.CommunityUploadedByUserId,
                    CommunityUploadedBodyHash = def.CommunityUploadedBodyHash,
                    CommunityUploadedVersion  = def.CommunityUploadedVersion,
                    CommunityAllowInPacks     = def.CommunityAllowInPacks,
                });
                existing[def.Id] = def;
                added++;
            }
            return (added, skipped);
        }

        // Collect the CustomEngineDefs referenced by the given snapshots and
        // car overrides. Walks each EnginePulse.CustomEngineId, resolves
        // against Settings.CustomEngines (the user's library), and returns
        // the matching defs (deduped by Id, only the ones that are actually
        // in the library — dangling refs are silently dropped because the
        // recipient can't do anything with them either). Stamps a curator
        // Author on each resolved def when it has none and the curator's
        // SharingAuthor is set, so a recipient who imports a "MyV12" by
        // Mhytee sees the credit.
        //
        // Pass either or both collections; nulls are tolerated.
        internal List<CustomEngineDef> CollectReferencedCustomEngines(
            IEnumerable<GameSettingsSnapshot> snapshots,
            IEnumerable<CarOverride> carOverrides)
        {
            if (Settings?.CustomEngines == null || Settings.CustomEngines.Count == 0)
                return null;
            var wantedIds = new HashSet<string>(StringComparer.Ordinal);
            if (snapshots != null)
            {
                foreach (var snap in snapshots)
                {
                    if (snap == null) continue;
                    string id = NullIfBlank(snap.EnginePulse?.CustomEngineId);
                    if (id != null) wantedIds.Add(id);
                    // Legacy pre-Model-G presets carried per-car overrides
                    // inline on the snapshot. Apply still reads these
                    // (TrueforcePlugin.cs:7395-7406), so an override that
                    // references a custom engine WOULD silently dangle on
                    // the recipient if we didn't walk them here.
                    if (snap.CarOverrides != null)
                    {
                        foreach (var inlineOvr in snap.CarOverrides.Values)
                        {
                            string nestedId = NullIfBlank(inlineOvr?.EnginePulse?.CustomEngineId);
                            if (nestedId != null) wantedIds.Add(nestedId);
                        }
                    }
                }
            }
            if (carOverrides != null)
            {
                foreach (var ovr in carOverrides)
                {
                    var ep = ovr?.EnginePulse;
                    if (ep == null) continue;
                    string id = NullIfBlank(ep.CustomEngineId);
                    if (id != null) wantedIds.Add(id);
                }
            }
            if (wantedIds.Count == 0) return null;

            string curatorAuthor = NullIfBlank(Settings?.SharingAuthor);
            var result = new List<CustomEngineDef>();
            foreach (var def in Settings.CustomEngines)
            {
                if (def == null || string.IsNullOrEmpty(def.Id)) continue;
                if (!wantedIds.Contains(def.Id)) continue;
                // Shallow-copy the def so we don't mutate the in-memory
                // library when stamping the curator Author for unattributed
                // defs.
                result.Add(new CustomEngineDef
                {
                    Id           = def.Id,
                    Name         = def.Name,
                    IsElectric   = def.IsElectric,
                    ElectricMode = def.ElectricMode,
                    Pattern      = def.Pattern,
                    Author       = NullIfBlank(def.Author) ?? curatorAuthor,
                    // Provenance/permission must travel with the export so the
                    // recipient's IsRedistributable gate stays honest (e.g. an
                    // author's AllowInPacks=false is preserved peer-to-peer).
                    CommunitySourceId         = def.CommunitySourceId,
                    CommunityUploadedById     = def.CommunityUploadedById,
                    CommunityUploadedByUserId = def.CommunityUploadedByUserId,
                    CommunityUploadedBodyHash = def.CommunityUploadedBodyHash,
                    CommunityUploadedVersion  = def.CommunityUploadedVersion,
                    CommunityAllowInPacks     = def.CommunityAllowInPacks,
                });
            }
            return result.Count > 0 ? result : null;
        }

        /// <summary>Read a preset file and store it in the library under the
        /// name embedded in the file. Does NOT auto-apply or auto-bind to a
        /// game, the user explicitly chooses what to do with it next.
        /// Returns a result struct with the imported name plus any author /
        /// description / version metadata in the file (all nullable).</summary>
        public ImportPresetResult ImportPreset(string path)
        {
            if (Settings == null) return default(ImportPresetResult);
            string json = System.IO.File.ReadAllText(path);
            var file = Newtonsoft.Json.JsonConvert.DeserializeObject<PresetFile>(json, SafeJson.Settings);
            if (file == null || file.Snapshot == null || string.IsNullOrEmpty(file.PresetName))
                throw new System.IO.InvalidDataException("Not a valid TF4ALL preset file.");
            if (file.Type != PresetFile.FileType)
                throw new System.IO.InvalidDataException($"Wrong file type '{file.Type}'. Expected '{PresetFile.FileType}'.");

            // Imports always land in the USER library as user presets, even
            // if the file's name happens to collide with a built-in (the
            // BuiltinPresetWriter is name-keyed; user library writes are
            // independent of the built-in folder). Fold the wrapper's
            // attribution onto the snapshot before serialising so the
            // recipient's disk preserves the original author + pack lineage
            // (per-snapshot fields beat the wrapper to keep authored
            // attribution when both are present).
            file.Snapshot.Author        = NullIfBlank(file.Snapshot.Author)        ?? NullIfBlank(file.Author);
            file.Snapshot.Description   = NullIfBlank(file.Snapshot.Description)   ?? NullIfBlank(file.Description);
            file.Snapshot.AuthorVersion = NullIfBlank(file.Snapshot.AuthorVersion) ?? NullIfBlank(file.AuthorVersion);
            file.Snapshot.PackName      = NullIfBlank(file.Snapshot.PackName)      ?? NullIfBlank(file.PackName);

            // Merge any custom firing-pattern defs the file carried into the
            // user's library so the preset's EnginePulse.CustomEngineId
            // resolves at apply time instead of falling through to silence.
            // Local wins on Id collision.
            var customEngineMerge = MergeImportedCustomEngines(file.CustomEngines);
            // Refuse a file whose tuning is already in the library under any
            // name (owner rule 2026-07-13) instead of minting "Name (2)". The
            // thrown message is what the import UI shows.
            string contentDup = FindGamePresetNameWithSameContent(file.Snapshot);
            if (contentDup != null)
                throw new System.IO.InvalidDataException(
                    $"This preset is already in your library as '{contentDup}'.");
            string snapJson = Newtonsoft.Json.JsonConvert.SerializeObject(
                file.Snapshot, Newtonsoft.Json.Formatting.Indented);
            // Never clobber an existing user preset of the same name.
            string importName = MakeUniqueGamePresetName(file.PresetName);
            BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, importName, snapJson);
            UserPresets.Reload();
            RebuildPresetCacheFromFolders();
            PersistSettingsCore();

            SimHub.Logging.Current.Info($"[TF4ALL] Imported preset '{importName}' from {path} into the user library.");
            return new ImportPresetResult
            {
                PresetName    = importName,
                Author        = file.Author,
                Description   = file.Description,
                AuthorVersion = file.AuthorVersion,
            };
        }

        public struct ImportPresetResult
        {
            public string PresetName;
            public string Author;
            public string Description;
            public string AuthorVersion;
        }

        public struct ImportCarPresetResult
        {
            public string CarId;
            public string PresetName;
            public string Author;
            public string Description;
            public string AuthorVersion;
        }

        public struct ImportPackResult
        {
            public int PresetsImported;
            public int CarsImported;
            public string Author;
            public string Description;
            public string AuthorVersion;
        }

        /// <summary>Read a car-preset file and add it to the multi-preset
        /// library under (CarId, PresetName) with IsBuiltin forced to false.
        /// If a user preset with the same name already exists for this car,
        /// appends "(N)" to keep both. Sets CarDefaults[carId] = imported
        /// preset name so the import becomes the active preset for that
        /// car. Applied immediately if the imported CarId matches the
        /// active car.</summary>
        /// <returns>Imported carId, final preset name, and any sharing metadata.</returns>
        public ImportCarPresetResult ImportCarPreset(string path)
        {
            if (Settings == null || _carStore == null) return default(ImportCarPresetResult);
            string json = System.IO.File.ReadAllText(path);
            var file = Newtonsoft.Json.JsonConvert.DeserializeObject<CarPresetFile>(json, SafeJson.Settings);
            if (file == null || file.Override == null || string.IsNullOrEmpty(file.CarId))
                throw new System.IO.InvalidDataException("Not a valid TF4ALL car-preset file.");
            if (file.Type != CarPresetFile.FileType)
                throw new System.IO.InvalidDataException($"Wrong file type '{file.Type}'. Expected '{CarPresetFile.FileType}'.");

            // Merge any custom firing-pattern defs the file carried into the
            // user's library so the override's EnginePulse.CustomEngineId
            // resolves at apply time. Local wins on Id collision.
            var customEngineMerge = MergeImportedCustomEngines(file.CustomEngines);

            // Refuse a file whose tuning is already in this car's library
            // under any name (owner rule 2026-07-13); see ImportPreset.
            string carContentDup = FindCarPresetNameWithSameContent(file.CarId, file.Override);
            if (carContentDup != null)
                throw new System.IO.InvalidDataException(
                    $"This car preset is already in your library as '{carContentDup}'.");

            // PresetName may be missing on legacy v1 imports, fall back to
            // the carId. IsBuiltin is force-cleared regardless of source.
            string desired = string.IsNullOrEmpty(file.PresetName) ? file.CarId : file.PresetName;
            string presetName = MakeUniqueCarPresetName(file.CarId, desired);
            // Preserve the source file's attribution + pack identity on disk.
            // Without this the row would land unattributed, the manager's
            // Source column would read "Local", and the original author's
            // credit would be silently erased on first re-save.
            _carStore.Save(file.CarId, presetName, file.GameName ?? "", file.Override, isBuiltin: false,
                packName:      NullIfBlank(file.PackName),
                author:        NullIfBlank(file.Author),
                description:   NullIfBlank(file.Description),
                authorVersion: NullIfBlank(file.AuthorVersion));

            if (Settings.CarDefaults == null) Settings.CarDefaults = new Dictionary<string, string>();
            Settings.CarDefaults[file.CarId] = presetName;
            // A fresh import binding overrides any prior None: drop the
            // suppression marker so the startup rebuild doesn't strip this
            // binding back out (mirrors SwitchActiveCarPreset).
            ClearCarSuppression(file.CarId);
            // Persist through to the user library's car-defaults.json so the
            // binding survives Init's rebuild (Settings.CarDefaults is a
            // runtime cache post-V2 migration; ShouldSerializeCarDefaults
            // returns false then, so the in-memory write alone would silently
            // revert on next plugin start).
            BuiltinPresetWriter.SetCarDefault(UserPresets.CurrentFolder, file.CarId, presetName);
            PersistSettingsCore();

            if (file.CarId == _activeCarId) ReloadActiveCarOverrideFromStore();
            SimHub.Logging.Current.Info(
                $"[TF4ALL] Imported car preset '{presetName}' for '{file.CarId}' from {path}.");
            return new ImportCarPresetResult
            {
                CarId         = file.CarId,
                PresetName    = presetName,
                Author        = file.Author,
                Description   = file.Description,
                AuthorVersion = file.AuthorVersion,
            };
        }

        // Append "(2)", "(3)", … to the desired name until it's unique
        // among the existing presets for this car. Avoids accidentally
        // clobbering a user preset with the same name as the import.
        private string MakeUniqueCarPresetName(string carId, string desired)
        {
            if (_carStore == null || string.IsNullOrEmpty(desired)) return desired;
            var loaded = _carStore.LoadAll();
            loaded.TryGetValue(carId, out var perCar);
            // A user file named like a FACTORY disk name gets frozen: the
            // suffix-agnostic IsCarPresetBuiltin classifies it built-in, so
            // in-place save / rename / delete all refuse. Treat a factory
            // name as taken too, so duplicate / import / pack-install never
            // mint one (the audit's factory-disk-name family).
            bool Taken(string n) => (perCar != null && perCar.ContainsKey(n))
                                    || IsCarPresetBuiltin(carId, n);
            if (!Taken(desired)) return desired;
            for (int i = 2; i < 100; i++)
            {
                string candidate = $"{desired} ({i})";
                if (!Taken(candidate)) return candidate;
            }
            return $"{desired} ({DateTime.Now:HHmmss})";
        }

        // Append "(2)", "(3)", … to a game preset name until it's unique among
        // the user's existing presets (and any imported earlier in the same
        // batch via alsoUsed). Mirrors MakeUniqueCarPresetName: an import never
        // clobbers an existing user game preset of the same name.
        private string MakeUniqueGamePresetName(string desired, HashSet<string> alsoUsed = null)
        {
            if (string.IsNullOrEmpty(desired)) return desired;
            bool Taken(string n) => UserPresets.HasGamePreset(n) || (alsoUsed != null && alsoUsed.Contains(n));
            if (!Taken(desired)) return desired;
            for (int i = 2; i < 100; i++)
            {
                string candidate = $"{desired} ({i})";
                if (!Taken(candidate)) return candidate;
            }
            return $"{desired} ({DateTime.Now:HHmmss})";
        }

        // ---------- preset pack (multi-preset zip) ----------

        /// <summary>Returns the names of all game presets in the library, in
        /// alphabetical order. Used by the export-pack picker.</summary>
        public List<string> GetExportablePresetNames()
        {
            if (Settings?.Presets == null) return new List<string>();
            var names = new List<string>(Settings.Presets.Keys);
            names.Sort(StringComparer.OrdinalIgnoreCase);
            return names;
        }

        /// <summary>Returns every (carId, presetName, gameName) tuple
        /// currently on disk, sorted by carId then preset name. Used by the
        /// export-pack picker.</summary>
        public List<CarPresetEntry> GetExportableCarPresets()
        {
            var result = new List<CarPresetEntry>();
            if (_carStore == null) return result;
            var loaded = _carStore.LoadAll();
            foreach (var carKv in loaded)
            {
                foreach (var pKv in carKv.Value)
                    result.Add(pKv.Value);
            }
            result.Sort((a, b) =>
            {
                int c = string.Compare(a.CarId, b.CarId, StringComparison.OrdinalIgnoreCase);
                return c != 0 ? c : string.Compare(a.PresetName, b.PresetName, StringComparison.OrdinalIgnoreCase);
            });
            return result;
        }

        /// <summary>Bundle the selected game presets and car presets into a
        /// .tfpack zip. Pass null for either collection to mean "include all
        /// of that kind". Layout: manifest.json, presets/Name.tfpreset,
        /// cars/CarId~PresetName.tfcar.json. Built-in car presets are exported
        /// with IsBuiltin forced false (only the bundled factory files are
        /// genuine built-ins).</summary>
        public (int presetsExported, int carsExported) ExportPack(
            string path,
            IEnumerable<string> presetNames,
            IEnumerable<(string CarId, string PresetName)> carPresets,
            string author = null, string description = null, string authorVersion = null,
            string packName = null, bool? allowInPacks = null)
        {
            if (Settings == null) return (0, 0);

            // Materialize selection: null = all available.
            var pickedPresets = presetNames != null
                ? new HashSet<string>(presetNames, StringComparer.Ordinal)
                : null;
            var pickedCars = carPresets != null
                ? new HashSet<(string, string)>(carPresets)
                : null;

            string normAuthor = NullIfBlank(author);
            string normDesc   = NullIfBlank(description);
            string normVer    = NullIfBlank(authorVersion);
            string normPack   = NullIfBlank(packName);
            var manifest = new PresetPackManifest
            {
                ExportedAt    = DateTime.UtcNow.ToString("o"),
                PackName      = normPack,
                Author        = normAuthor,
                Description   = normDesc,
                AuthorVersion = normVer,
            };

            int presetsCount = 0, carsCount = 0;
            // Track every included snapshot + override so we can collect the
            // CustomEngineDefs they reference once at the manifest write,
            // deduped across the whole pack (a custom engine used by 3
            // presets ships once, not three times).
            var includedSnapshots = new List<GameSettingsSnapshot>();
            var includedOverrides = new List<CarOverride>();
            using (var fs = new System.IO.FileStream(path, System.IO.FileMode.Create, System.IO.FileAccess.Write))
            using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Create))
            {
                // ---- game presets ----
                if (Settings.Presets != null)
                {
                    foreach (var kv in Settings.Presets)
                    {
                        if (pickedPresets != null && !pickedPresets.Contains(kv.Key)) continue;
                        if (kv.Value == null) continue;
                        // Clone + stamp the per-entry snapshot so the
                        // live library copy stays unrestricted while the
                        // file (and any downstream importer) carries the
                        // pack curator's "ok to re-bundle" choice.
                        var snapForExport = StampSnapshotForExport(CloneSnapshot(kv.Value), allowInPacks);
                        includedSnapshots.Add(snapForExport);

                        string entryName = "presets/" + SanitizeForZip(kv.Key) + ".tfpreset";
                        // PackName at the per-preset level = the pack-level
                        // PackName (tags every entry as belonging to this
                        // pack so a later "delete pack" knows which entries
                        // it owns). But Author/Description/AuthorVersion
                        // PRESERVE the source preset's own metadata when
                        // present — a curator can't strip an original
                        // contributor's credit by adding their work to a pack.
                        // Only when the source has no Author do we fall back
                        // to the curator's pack-level Author.
                        var file = new PresetFile
                        {
                            PresetName    = kv.Key,
                            Snapshot      = snapForExport,
                            PackName      = normPack,
                            Author        = NullIfBlank(snapForExport.Author)        ?? normAuthor,
                            Description   = NullIfBlank(snapForExport.Description)   ?? normDesc,
                            AuthorVersion = NullIfBlank(snapForExport.AuthorVersion) ?? normVer,
                        };
                        WriteJsonZipEntry(zip, entryName, file);
                        manifest.Presets.Add(entryName);
                        presetsCount++;
                    }
                }

                // ---- car presets ----
                if (_carStore != null)
                {
                    var loaded = _carStore.LoadAll();
                    foreach (var carKv in loaded)
                    {
                        foreach (var pKv in carKv.Value)
                        {
                            var entry = pKv.Value;
                            var key = (entry.CarId, entry.PresetName);
                            if (pickedCars != null && !pickedCars.Contains(key)) continue;
                            // Same clone+stamp pattern as game-preset path
                            // above: live override unrestricted, file copy
                            // stamped with the curator's permission.
                            var ovrForExport = entry.Override != null
                                ? StampCarOverrideForExport(CloneCarOverride(entry.Override), allowInPacks)
                                : null;
                            if (ovrForExport != null) includedOverrides.Add(ovrForExport);

                            string entryName = "cars/" + SanitizeForZip(entry.CarId) + "~"
                                + SanitizeForZip(entry.PresetName) + ".tfcar.json";
                            // Per-row attribution preserves the source car
                            // preset's own metadata (so a curator can't strip
                            // credit by adding someone else's preset to their
                            // pack). PackName at the per-row level = the
                            // pack-level tag so "delete pack" knows which
                            // entries it owns.
                            var file = new CarPresetFile
                            {
                                GameName      = entry.GameName ?? "",
                                CarId         = entry.CarId,
                                PresetName    = entry.PresetName,
                                IsBuiltin     = false,
                                PackName      = normPack,
                                Author        = NullIfBlank(entry.Author)        ?? normAuthor,
                                Description   = NullIfBlank(entry.Description)   ?? normDesc,
                                AuthorVersion = NullIfBlank(entry.AuthorVersion) ?? normVer,
                                Override      = ovrForExport,
                            };
                            WriteJsonZipEntry(zip, entryName, file);
                            manifest.Cars.Add(new PackedCarPreset
                            {
                                CarId      = entry.CarId,
                                PresetName = entry.PresetName,
                                GameName   = entry.GameName ?? "",
                                FileName   = entryName,
                            });
                            carsCount++;
                        }
                    }
                }

                // Attach the deduped CustomEngineDefs referenced by any of
                // the packed snapshots/overrides so a recipient gets the
                // pattern data, not just dangling CustomEngineIds. Each
                // def is cloned + stamped with the curator's permission
                // so the engine carries the same re-bundle intent as the
                // presets that reference it.
                manifest.CustomEngines = StampCustomEnginesForExport(
                    CollectReferencedCustomEngines(includedSnapshots, includedOverrides),
                    allowInPacks);

                WriteJsonZipEntry(zip, "manifest.json", manifest);

                // README inside the archive so a recipient who extracts the
                // zip first (instead of using Import directly) sees how to
                // install it without leaving the folder.
                var readmeEntry = zip.CreateEntry("README.txt");
                using (var ws = readmeEntry.Open())
                using (var sw = new System.IO.StreamWriter(ws, new System.Text.UTF8Encoding(false)))
                {
                    sw.Write(BuildPackReadme(normPack, normAuthor, normVer, presetsCount, carsCount));
                }
            }

            SimHub.Logging.Current.Info(
                $"[TF4ALL] Exported pack to {path}: {presetsCount} game preset(s), {carsCount} car preset(s).");
            return (presetsCount, carsCount);
        }

        // README written into pack zips. Helps a recipient who extracts the
        // archive instead of importing it directly. Mentions the pack
        // identity (name + author + version) and the step-by-step Import
        // flow inside SimHub.
        private static string BuildPackReadme(string packName, string author, string version,
            int presetsCount, int carsCount)
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("Trueforce For All - preset pack");
            sb.AppendLine();
            if (!string.IsNullOrEmpty(packName))   sb.AppendLine($"Pack:    {packName}");
            if (!string.IsNullOrEmpty(author))     sb.AppendLine($"Author:  {author}");
            if (!string.IsNullOrEmpty(version))    sb.AppendLine($"Version: {version}");
            if (presetsCount > 0 || carsCount > 0)
            {
                var parts = new List<string>();
                if (presetsCount > 0) parts.Add($"{presetsCount} game preset(s)");
                if (carsCount    > 0) parts.Add($"{carsCount} car preset(s)");
                sb.AppendLine($"Contents: " + string.Join(", ", parts));
            }
            sb.AppendLine();
            sb.AppendLine("To install:");
            sb.AppendLine("  1. Open SimHub.");
            sb.AppendLine("  2. Left sidebar -> Trueforce For All plugin.");
            sb.AppendLine("  3. Click the Presets tab.");
            sb.AppendLine("  4. Click Import (top right of the preset list).");
            sb.AppendLine("  5. Pick this .tfpack file (or this extracted folder).");
            sb.AppendLine();
            sb.AppendLine("All presets in the pack share the (Author, Version, Pack Name) identity,");
            sb.AppendLine("so the manager can later show them grouped and let you remove or set");
            sb.AppendLine("them as defaults as a unit.");
            return sb.ToString();
        }

        // ExportLoose + BuildLooseExportReadme used to live here. They wrote
        // a folder of .tfpreset.json / .tfcar.json plus a README explaining
        // how to import them. Retired by the count-based export rule (single
        // picked = single loose file; multi picked = always a pack), which
        // gives the same affordance with simpler attribution preservation.
        // The originals had stricter author preservation than ExportPack and
        // would have been a foot-gun if some future code path called them
        // again, so they were deleted rather than left as dead code. If
        // "bulk loose export" comes back, build it on the same source-Author-
        // preserves pattern as ExportSinglePreset.

        /// <summary>Write a single game preset to a .tfpreset.json file at
        /// the user-chosen path. Author / Description / AuthorVersion come
        /// from the export-metadata dialog (the curator); per-preset author
        /// already stamped on the snapshot is preserved when present so the
        /// original contributor keeps credit.</summary>
        public void ExportSinglePreset(string path, string presetName,
            string author = null, string description = null, string authorVersion = null,
            bool? allowInPacks = null)
        {
            if (string.IsNullOrEmpty(path)) throw new ArgumentException("Output path is empty.", nameof(path));
            if (string.IsNullOrEmpty(presetName)) throw new ArgumentException("Preset name is empty.", nameof(presetName));
            if (Settings?.Presets == null || !Settings.Presets.TryGetValue(presetName, out var liveSnap) || liveSnap == null)
                throw new InvalidOperationException($"Preset '{presetName}' no longer exists in the library.");

            // Clone the snapshot before stamping so the LIVE in-library copy
            // doesn't pick up the export's CommunitySourceId / AllowInPacks -
            // the author should keep an unrestricted local copy they can
            // re-export with a different permission later.
            var snap = StampSnapshotForExport(CloneSnapshot(liveSnap), allowInPacks);

            // Per-preset author: keep the snapshot's own when present; only
            // fall back to the curator's author for unattributed presets.
            string finalAuthor  = NullIfBlank(snap.Author)        ?? NullIfBlank(author);
            string finalDesc    = NullIfBlank(snap.Description)   ?? NullIfBlank(description);
            string finalVer     = NullIfBlank(snap.AuthorVersion) ?? NullIfBlank(authorVersion);

            var file = new PresetFile
            {
                PresetName    = presetName,
                Snapshot      = snap,
                Author        = finalAuthor,
                Description   = finalDesc,
                AuthorVersion = finalVer,
                CustomEngines = StampCustomEnginesForExport(
                    CollectReferencedCustomEngines(new[] { snap }, carOverrides: null),
                    allowInPacks),
            };
            System.IO.File.WriteAllText(path,
                Newtonsoft.Json.JsonConvert.SerializeObject(file, Newtonsoft.Json.Formatting.Indented));
            SimHub.Logging.Current.Info($"[TF4ALL] Exported single preset '{presetName}' to {path}.");
        }

        // Clone-and-stamp a list of CustomEngineDefs for export. Mirrors
        // StampSnapshotForExport / StampCarOverrideForExport so single-
        // preset exports carry the same permission stamp on referenced
        // engines as the pack-export path does.
        private static List<CustomEngineDef> StampCustomEnginesForExport(
            List<CustomEngineDef> engines, bool? allowInPacks)
        {
            if (engines == null) return null;
            var stamped = new List<CustomEngineDef>(engines.Count);
            foreach (var def in engines)
            {
                if (def == null) continue;
                var clone = Newtonsoft.Json.JsonConvert.DeserializeObject<CustomEngineDef>(
                    Newtonsoft.Json.JsonConvert.SerializeObject(def));
                stamped.Add(StampCustomEngineForExport(clone, allowInPacks));
            }
            return stamped;
        }

        // Set the AllowInPacks toggle the user picked at export and mint
        // a peer provenance id when the snapshot doesn't already carry a
        // CommunitySourceId. The "p2p-" prefix makes peer-source rows
        // obviously distinguishable from real community uuids in logs
        // and update checks; existing CommunitySourceId values
        // (community downloads being forwarded) are preserved so the
        // original author's permission travels intact.
        private static GameSettingsSnapshot StampSnapshotForExport(GameSettingsSnapshot snap, bool? allowInPacks)
        {
            if (snap == null) return null;
            if (allowInPacks.HasValue) snap.CommunityAllowInPacks = allowInPacks;
            if (string.IsNullOrEmpty(snap.CommunitySourceId))
                snap.CommunitySourceId = "p2p-" + Guid.NewGuid().ToString("N");
            return snap;
        }

        private static CarOverride StampCarOverrideForExport(CarOverride ovr, bool? allowInPacks)
        {
            if (ovr == null) return null;
            if (allowInPacks.HasValue) ovr.CommunityAllowInPacks = allowInPacks;
            if (string.IsNullOrEmpty(ovr.CommunitySourceId))
                ovr.CommunitySourceId = "p2p-" + Guid.NewGuid().ToString("N");
            return ovr;
        }

        private static CustomEngineDef StampCustomEngineForExport(CustomEngineDef def, bool? allowInPacks)
        {
            if (def == null) return null;
            if (allowInPacks.HasValue) def.CommunityAllowInPacks = allowInPacks;
            if (string.IsNullOrEmpty(def.CommunitySourceId))
                def.CommunitySourceId = "p2p-" + Guid.NewGuid().ToString("N");
            return def;
        }

        /// <summary>Write a single car preset to a .tfcar.json file at the
        /// user-chosen path. Preserves the source car preset's PackName /
        /// Author / Description / AuthorVersion when present (so a curator
        /// can't redistribute someone else's preset stripped of credit),
        /// falling back to the export-metadata dialog values only when the
        /// source itself was unattributed.</summary>
        public void ExportSingleCarPreset(string path, string carId, string presetName,
            string author = null, string description = null, string authorVersion = null,
            bool? allowInPacks = null)
        {
            if (_carStore == null) throw new InvalidOperationException("Car preset store is not initialised.");
            if (string.IsNullOrEmpty(path))       throw new ArgumentException("Output path is empty.", nameof(path));
            if (string.IsNullOrEmpty(carId))      throw new ArgumentException("CarId is empty.", nameof(carId));
            if (string.IsNullOrEmpty(presetName)) throw new ArgumentException("Preset name is empty.", nameof(presetName));

            var loaded = _carStore.LoadAll();
            if (!loaded.TryGetValue(carId, out var perCar)
                || !perCar.TryGetValue(presetName, out var entry)
                || entry == null || entry.Override == null)
                throw new InvalidOperationException($"Car preset '{carId}/{presetName}' no longer exists in the library.");

            // Clone before stamping (parity with ExportSinglePreset): the
            // author's local override stays unstamped so they keep an
            // unrestricted copy for self-rebundling.
            var ovr = StampCarOverrideForExport(CloneCarOverride(entry.Override), allowInPacks);

            string finalAuthor = NullIfBlank(entry.Author)        ?? NullIfBlank(author);
            string finalDesc   = NullIfBlank(entry.Description)   ?? NullIfBlank(description);
            string finalVer    = NullIfBlank(entry.AuthorVersion) ?? NullIfBlank(authorVersion);
            string finalPack   = NullIfBlank(entry.PackName);   // preserve source pack tag; no curator override

            var file = new CarPresetFile
            {
                GameName      = entry.GameName ?? "",
                CarId         = entry.CarId,
                PresetName    = ToDiskName(entry.PresetName),
                IsBuiltin     = false,
                PackName      = finalPack,
                Author        = finalAuthor,
                Description   = finalDesc,
                AuthorVersion = finalVer,
                Override      = ovr,
                CustomEngines = StampCustomEnginesForExport(
                    CollectReferencedCustomEngines(snapshots: null, carOverrides: new[] { ovr }),
                    allowInPacks),
            };
            System.IO.File.WriteAllText(path,
                Newtonsoft.Json.JsonConvert.SerializeObject(file, Newtonsoft.Json.Formatting.Indented));
            SimHub.Logging.Current.Info($"[TF4ALL] Exported single car preset '{carId}/{presetName}' to {path}.");
        }

        /// <summary>Read every preset and car-preset file in the pack zip.
        /// Game presets land in Settings.Presets (overwriting any with the
        /// same name); car presets go through MakeUniqueCarPresetName so a
        /// name collision keeps both. Returns a (presets, cars) count.</summary>
        /// <summary>Open a .tfpack / .zip read-only and return its manifest +
        /// the list of contained items WITHOUT writing anything to disk. Used
        /// by the import preview to show pack metadata + a checklist before
        /// the user commits. Returns null when the file isn't a zip or has
        /// no manifest.json (caller treats those as "loose multi-file bundle"
        /// rather than a structured pack).</summary>
        public PresetPackManifest PeekPackManifest(string path)
        {
            if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return null;
            try
            {
                using (var fs = new System.IO.FileStream(path, System.IO.FileMode.Open, System.IO.FileAccess.Read))
                using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Read))
                {
                    var manifestEntry = zip.GetEntry("manifest.json");
                    if (manifestEntry == null) return null;
                    var manifest = ReadJsonZipEntry<PresetPackManifest>(manifestEntry);
                    if (manifest == null) return null;
                    if (!string.IsNullOrEmpty(manifest.Type) && manifest.Type != PresetPackManifest.FileType) return null;
                    return manifest;
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] PeekPackManifest({path}) failed: {ex.Message}");
                return null;
            }
        }

        public ImportPackResult ImportPack(string path)
        {
            if (Settings == null) return default(ImportPackResult);

            string packAuthor = null, packDesc = null, packVer = null, packName = null;
            int presetsImported = 0, carsImported = 0;
            // Identity entries this import actually wrote (actual unique names),
            // recorded into the installed-packs sidecar at the end so a later
            // "delete pack / filter by pack" feature and the Source column can
            // attribute these rows to their pack.
            var packEntries = new List<InstalledPackEntry>();
            using (var fs = new System.IO.FileStream(path, System.IO.FileMode.Open, System.IO.FileAccess.Read))
            using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Read))
            {
                // Validate manifest if present (we don't strictly need it to
                // import, but Type-mismatch is a useful early failure for the
                // "user picked the wrong zip" case).
                var manifestEntry = zip.GetEntry("manifest.json");
                if (manifestEntry != null)
                {
                    var manifest = ReadJsonZipEntry<PresetPackManifest>(manifestEntry);
                    if (manifest != null)
                    {
                        if (!string.IsNullOrEmpty(manifest.Type)
                            && manifest.Type != PresetPackManifest.FileType)
                        {
                            throw new System.IO.InvalidDataException(
                                $"Wrong pack type '{manifest.Type}'. Expected '{PresetPackManifest.FileType}'.");
                        }
                        packAuthor = manifest.Author;
                        packDesc   = manifest.Description;
                        packVer    = manifest.AuthorVersion;
                        packName   = manifest.PackName;
                        // Full-pack import: merge every CustomEngineDef the
                        // manifest carried so any contained preset's
                        // EnginePulse.CustomEngineId resolves on apply, and record
                        // each as a pack entry (reference-counted on removal).
                        MergeImportedCustomEngines(manifest.CustomEngines);
                        AddEnginePackEntries(packEntries, manifest.CustomEngines);
                    }
                }

                if (Settings.Presets == null)
                    Settings.Presets = new Dictionary<string, GameSettingsSnapshot>();

                // Track game-preset names chosen in this pack so two entries
                // with the same name (or a clash with an existing user preset)
                // don't clobber each other. Mirrors the car unique-name guard.
                var importedGameNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                foreach (var entry in zip.Entries)
                {
                    if (entry.FullName.StartsWith("presets/", StringComparison.OrdinalIgnoreCase)
                        && entry.FullName.EndsWith(".tfpreset", StringComparison.OrdinalIgnoreCase))
                    {
                        // ZIP Slip guard: reject any entry name that would
                        // escape the user library via absolute path or '..'.
                        if (!SafePath.IsSafeArchivePath(UserPresets.CurrentFolder, entry.FullName, out _)) continue;

                        var pf = ReadJsonZipEntry<PresetFile>(entry);
                        if (pf == null || pf.Snapshot == null || string.IsNullOrEmpty(pf.PresetName)) continue;
                        if (pf.Type != PresetFile.FileType) continue;
                        // Write to the user library folder (imported pack
                        // entries are user presets, not factory built-ins).
                        try
                        {
                            // Fold wrapper attribution onto the snapshot so
                            // each preset's on-disk file carries its own
                            // author + pack lineage. Per-snapshot fields
                            // beat the wrapper (preserve original credit
                            // when the curator stamped over a community
                            // contributor's work).
                            pf.Snapshot.Author        = NullIfBlank(pf.Snapshot.Author)        ?? NullIfBlank(pf.Author)        ?? packAuthor;
                            pf.Snapshot.Description   = NullIfBlank(pf.Snapshot.Description)   ?? NullIfBlank(pf.Description)   ?? packDesc;
                            pf.Snapshot.AuthorVersion = NullIfBlank(pf.Snapshot.AuthorVersion) ?? NullIfBlank(pf.AuthorVersion) ?? packVer;
                            pf.Snapshot.PackName      = NullIfBlank(pf.Snapshot.PackName)      ?? NullIfBlank(pf.PackName)      ?? packName;
                            string snapJson = Newtonsoft.Json.JsonConvert.SerializeObject(
                                pf.Snapshot, Newtonsoft.Json.Formatting.Indented);
                            string gName = MakeUniqueGamePresetName(pf.PresetName, importedGameNames);
                            importedGameNames.Add(gName);
                            BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, gName, snapJson);
                            // Record the ACTUAL name written (post-uniquing) so
                            // the sidecar identity matches what's on disk.
                            // BaselineHash stamps the JSON we just wrote so the
                            // Pack Manager can detect user edits before destructive
                            // remove (hash mismatch → user touched it → keep).
                            packEntries.Add(new InstalledPackEntry
                            {
                                Kind         = InstalledPackEntry.KindGame,
                                Name         = gName,
                                BaselineHash = InstalledPacksStore.ComputeContentHash(snapJson),
                            });
                            presetsImported++;
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] Pack import of preset '{pf.PresetName}' failed: {ex.Message}");
                        }
                    }
                    else if (entry.FullName.StartsWith("cars/", StringComparison.OrdinalIgnoreCase)
                        && entry.FullName.EndsWith(".tfcar.json", StringComparison.OrdinalIgnoreCase))
                    {
                        // ZIP Slip guard for the car library destination.
                        if (!SafePath.IsSafeArchivePath(_carStore?.FolderPath ?? "", entry.FullName, out _)) continue;

                        var cf = ReadJsonZipEntry<CarPresetFile>(entry);
                        if (cf == null || cf.Override == null || string.IsNullOrEmpty(cf.CarId)) continue;
                        if (cf.Type != CarPresetFile.FileType) continue;

                        string desired = string.IsNullOrEmpty(cf.PresetName) ? cf.CarId : cf.PresetName;
                        string presetName = MakeUniqueCarPresetName(cf.CarId, desired);
                        // Persist the pack identity onto the car file so it
                        // survives on disk. Prefer the file's own metadata
                        // (per-preset), fall back to the pack-level fields.
                        _carStore?.Save(cf.CarId, presetName, cf.GameName ?? "", cf.Override, isBuiltin: false,
                            packName:      cf.PackName      ?? packName,
                            author:        cf.Author        ?? packAuthor,
                            description:   cf.Description    ?? packDesc,
                            authorVersion: cf.AuthorVersion ?? packVer);
                        // Record the ACTUAL carId + name written (post-uniquing).
                        // GameName lets the Pack Manager locate the file without
                        // walking the cars/ tree; BaselineHash is read from the
                        // just-saved file (CarPresetStore.Save folds in existing
                        // attribution so we can't hash the input directly).
                        packEntries.Add(new InstalledPackEntry
                        {
                            Kind         = InstalledPackEntry.KindCar,
                            CarId        = cf.CarId,
                            PresetName   = presetName,
                            GameName     = cf.GameName ?? "",
                            BaselineHash = TryHashCarPresetFile(cf.CarId, presetName),
                        });
                        carsImported++;
                    }
                }
            }

            // Record the pack identity in the sidecar so future "delete pack /
            // filter by pack / set pack as default" and the Source column can
            // attribute these rows. One record per ImportPack call. Fall back
            // to a sensible label when no PackName was supplied (the author, or
            // a generic "Imported pack").
            if (packEntries.Count > 0)
            {
                string label = NullIfBlank(packName) ?? NullIfBlank(packAuthor) ?? "Imported pack";
                _installedPacks?.AddPack(new InstalledPack
                {
                    PackName      = label,
                    Author        = packAuthor,
                    AuthorVersion = packVer,
                    Description    = packDesc,
                    ImportedAt    = DateTime.Now,
                    Entries       = packEntries,
                });
            }

            // Game presets just landed in the user library folder; reload +
            // rebuild the cache so they show up in the library immediately.
            if (presetsImported > 0)
            {
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            PersistSettingsCore();
            if (!string.IsNullOrEmpty(_activeCarId)) ReloadActiveCarOverrideFromStore();

            SimHub.Logging.Current.Info(
                $"[TF4ALL] Imported pack from {path}: {presetsImported} game preset(s), {carsImported} car preset(s).");
            return new ImportPackResult
            {
                PresetsImported = presetsImported,
                CarsImported    = carsImported,
                Author          = packAuthor,
                Description     = packDesc,
                AuthorVersion   = packVer,
            };
        }

        /// <summary>Import only the selected entries from a .tfpack / .zip,
        /// and optionally bind a per-row entry as the game-default or
        /// car-default in the same pass. Behaves like ImportPack for entries
        /// the user kept; entries not in the include sets are skipped with no
        /// disk write. Mirrors ImportPack's installed-packs sidecar registration
        /// + unique-naming so a partial pack still attributes its rows.
        ///
        /// <paramref name="includedGamePresets"/> = pack-side preset names to
        /// import. <paramref name="includedCarPresets"/> = (CarId, PresetName)
        /// tuples to import (tuple as written in the pack, NOT post-uniquing).
        /// <paramref name="setGameDefaultFor"/> = subset of pack-side game
        /// preset names that should be bound as the default for the
        /// PresetFile.Snapshot.GameName inside the pack entry. <paramref
        /// name="setCarDefaultFor"/> = subset of (CarId, PresetName) tuples
        /// that should be bound as CarDefaults[CarId]=postUniquingName.</summary>
        public ImportPackResult ImportPackSelective(string path,
            HashSet<string> includedGamePresets,
            HashSet<(string CarId, string PresetName)> includedCarPresets,
            HashSet<string> setGameDefaultFor,
            HashSet<(string CarId, string PresetName)> setCarDefaultFor)
        {
            if (Settings == null) return default(ImportPackResult);
            if (includedGamePresets == null) includedGamePresets = new HashSet<string>(StringComparer.Ordinal);
            if (includedCarPresets  == null) includedCarPresets  = new HashSet<(string, string)>();
            if (setGameDefaultFor   == null) setGameDefaultFor   = new HashSet<string>(StringComparer.Ordinal);
            if (setCarDefaultFor    == null) setCarDefaultFor    = new HashSet<(string, string)>();
            // No-op short-circuit: if a future caller passes both include sets
            // empty (CLI script, automated reseed) we'd otherwise open the zip,
            // walk it, write nothing, and still register a phantom empty
            // InstalledPack. Cheap to skip.
            if (includedGamePresets.Count == 0 && includedCarPresets.Count == 0)
                return default(ImportPackResult);

            string packAuthor = null, packDesc = null, packVer = null, packName = null;
            int presetsImported = 0, carsImported = 0;
            int carDefaultsSet = 0;
            var packEntries = new List<InstalledPackEntry>();
            // Defer the CustomEngines merge until after the iteration so we
            // can constrain to only the defs actually referenced by the
            // user-selected items (selective imports shouldn't pollute the
            // recipient's library with defs from rows the user deselected).
            List<CustomEngineDef> manifestCustomEngines = null;
            var referencedCustomEngineIds = new HashSet<string>(StringComparer.Ordinal);

            using (var fs = new System.IO.FileStream(path, System.IO.FileMode.Open, System.IO.FileAccess.Read))
            using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Read))
            {
                var manifestEntry = zip.GetEntry("manifest.json");
                if (manifestEntry != null)
                {
                    var manifest = ReadJsonZipEntry<PresetPackManifest>(manifestEntry);
                    if (manifest != null)
                    {
                        if (!string.IsNullOrEmpty(manifest.Type) && manifest.Type != PresetPackManifest.FileType)
                            throw new System.IO.InvalidDataException(
                                $"Wrong pack type '{manifest.Type}'. Expected '{PresetPackManifest.FileType}'.");
                        packAuthor = manifest.Author;
                        packDesc   = manifest.Description;
                        packVer    = manifest.AuthorVersion;
                        packName   = manifest.PackName;
                        manifestCustomEngines = manifest.CustomEngines;
                    }
                }

                if (Settings.Presets == null)
                    Settings.Presets = new Dictionary<string, GameSettingsSnapshot>();
                if (Settings.GameDefaults == null)
                    Settings.GameDefaults = new Dictionary<string, string>();
                if (Settings.CarDefaults  == null)
                    Settings.CarDefaults  = new Dictionary<string, string>();

                var importedGameNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                foreach (var entry in zip.Entries)
                {
                    if (entry.FullName.StartsWith("presets/", StringComparison.OrdinalIgnoreCase)
                        && entry.FullName.EndsWith(".tfpreset", StringComparison.OrdinalIgnoreCase))
                    {
                        // ZIP Slip guard for selective import.
                        if (!SafePath.IsSafeArchivePath(UserPresets.CurrentFolder, entry.FullName, out _)) continue;

                        var pf = ReadJsonZipEntry<PresetFile>(entry);
                        if (pf == null || pf.Snapshot == null || string.IsNullOrEmpty(pf.PresetName)) continue;
                        if (pf.Type != PresetFile.FileType) continue;
                        if (!includedGamePresets.Contains(pf.PresetName)) continue;
                        try
                        {
                            // Fold wrapper attribution onto the snapshot
                            // (same rule as full ImportPack).
                            pf.Snapshot.Author        = NullIfBlank(pf.Snapshot.Author)        ?? NullIfBlank(pf.Author)        ?? packAuthor;
                            pf.Snapshot.Description   = NullIfBlank(pf.Snapshot.Description)   ?? NullIfBlank(pf.Description)   ?? packDesc;
                            pf.Snapshot.AuthorVersion = NullIfBlank(pf.Snapshot.AuthorVersion) ?? NullIfBlank(pf.AuthorVersion) ?? packVer;
                            pf.Snapshot.PackName      = NullIfBlank(pf.Snapshot.PackName)      ?? NullIfBlank(pf.PackName)      ?? packName;
                            string snapJson = Newtonsoft.Json.JsonConvert.SerializeObject(
                                pf.Snapshot, Newtonsoft.Json.Formatting.Indented);
                            string gName = MakeUniqueGamePresetName(pf.PresetName, importedGameNames);
                            importedGameNames.Add(gName);
                            BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, gName, snapJson);
                            packEntries.Add(new InstalledPackEntry
                            {
                                Kind         = InstalledPackEntry.KindGame,
                                Name         = gName,
                                BaselineHash = InstalledPacksStore.ComputeContentHash(snapJson),
                            });
                            presetsImported++;
                            // Track the custom engine the imported preset references
                            // (if any) so the post-loop merge brings its def along.
                            string epCustomId = NullIfBlank(pf.Snapshot.EnginePulse?.CustomEngineId);
                            if (epCustomId != null) referencedCustomEngineIds.Add(epCustomId);
                            // Legacy snap.CarOverrides path: nested per-car
                            // overrides on a pre-Model-G snapshot also need
                            // their CustomEngineId pulled into the merge set
                            // or the dangling-pointer hole reopens for that
                            // case.
                            if (pf.Snapshot.CarOverrides != null)
                            {
                                foreach (var inlineOvr in pf.Snapshot.CarOverrides.Values)
                                {
                                    string nestedId = NullIfBlank(inlineOvr?.EnginePulse?.CustomEngineId);
                                    if (nestedId != null) referencedCustomEngineIds.Add(nestedId);
                                }
                            }

                            // Set-as-default for game presets requires a
                            // (preset -> game) mapping that the bare
                            // PresetFile + GameSettingsSnapshot doesn't carry.
                            // The preview modal disables the toggle for game
                            // rows accordingly; this branch stays for the day
                            // we add a Defaults hint to PresetPackManifest.
                            if (setGameDefaultFor.Contains(pf.PresetName))
                            {
                                SimHub.Logging.Current.Info(
                                    $"[TF4ALL] Selective pack import: set-as-default for game preset '{gName}' requested but not yet supported (data model doesn't carry preset->game mapping).");
                            }
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] Selective pack import of preset '{pf.PresetName}' failed: {ex.Message}");
                        }
                    }
                    else if (entry.FullName.StartsWith("cars/", StringComparison.OrdinalIgnoreCase)
                        && entry.FullName.EndsWith(".tfcar.json", StringComparison.OrdinalIgnoreCase))
                    {
                        // ZIP Slip guard for selective car import.
                        if (!SafePath.IsSafeArchivePath(_carStore?.FolderPath ?? "", entry.FullName, out _)) continue;

                        var cf = ReadJsonZipEntry<CarPresetFile>(entry);
                        if (cf == null || cf.Override == null || string.IsNullOrEmpty(cf.CarId)) continue;
                        if (cf.Type != CarPresetFile.FileType) continue;

                        string desired = string.IsNullOrEmpty(cf.PresetName) ? cf.CarId : cf.PresetName;
                        var packKey = (cf.CarId, desired);
                        if (!includedCarPresets.Contains(packKey)) continue;

                        string presetName = MakeUniqueCarPresetName(cf.CarId, desired);
                        _carStore?.Save(cf.CarId, presetName, cf.GameName ?? "", cf.Override, isBuiltin: false,
                            packName:      cf.PackName      ?? packName,
                            author:        cf.Author        ?? packAuthor,
                            description:   cf.Description    ?? packDesc,
                            authorVersion: cf.AuthorVersion ?? packVer);
                        packEntries.Add(new InstalledPackEntry
                        {
                            Kind         = InstalledPackEntry.KindCar,
                            CarId        = cf.CarId,
                            PresetName   = presetName,
                            GameName     = cf.GameName ?? "",
                            BaselineHash = TryHashCarPresetFile(cf.CarId, presetName),
                        });
                        carsImported++;
                        string carCustomId = NullIfBlank(cf.Override.EnginePulse?.CustomEngineId);
                        if (carCustomId != null) referencedCustomEngineIds.Add(carCustomId);

                        // Set-as-default for this car. Settings.CarDefaults
                        // is a runtime cache (ShouldSerializeCarDefaults is
                        // false post-V2 migration), so the in-memory write
                        // alone would silently revert on next Init. Persist
                        // through to the user library's car-defaults.json
                        // (BuiltinPresetWriter.SetCarDefault) so the binding
                        // survives restarts.
                        if (setCarDefaultFor.Contains(packKey))
                        {
                            Settings.CarDefaults[cf.CarId] = presetName;
                            ClearCarSuppression(cf.CarId);
                            BuiltinPresetWriter.SetCarDefault(UserPresets.CurrentFolder, cf.CarId, presetName);
                            carDefaultsSet++;
                        }
                    }
                }
            }

            // Merge only the CustomEngineDefs actually referenced by the
            // items the user kept. Skipping unselected rows' defs keeps the
            // recipient's library clean of patterns they didn't ask for.
            if (manifestCustomEngines != null && referencedCustomEngineIds.Count > 0)
            {
                MergeImportedCustomEngines(manifestCustomEngines, referencedCustomEngineIds);
                // Record the referenced engines as pack entries (the only ones
                // this selective import merged), reference-counted on removal.
                AddEnginePackEntries(packEntries, manifestCustomEngines,
                    onlyIds: referencedCustomEngineIds);
            }

            if (packEntries.Count > 0)
            {
                string label = NullIfBlank(packName) ?? NullIfBlank(packAuthor) ?? "Imported pack";
                _installedPacks?.AddPack(new InstalledPack
                {
                    PackName      = label,
                    Author        = packAuthor,
                    AuthorVersion = packVer,
                    Description   = packDesc,
                    ImportedAt    = DateTime.Now,
                    Entries       = packEntries,
                });
            }

            if (presetsImported > 0)
            {
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }
            PersistSettingsCore();
            if (!string.IsNullOrEmpty(_activeCarId)) ReloadActiveCarOverrideFromStore();

            SimHub.Logging.Current.Info(
                $"[TF4ALL] Selective pack import from {path}: {presetsImported}/{includedGamePresets.Count} game preset(s), {carsImported}/{includedCarPresets.Count} car preset(s), {carDefaultsSet} car default(s) set.");
            return new ImportPackResult
            {
                PresetsImported = presetsImported,
                CarsImported    = carsImported,
                Author          = packAuthor,
                Description     = packDesc,
                AuthorVersion   = packVer,
            };
        }

        /// <summary>Read-only count of how many of a pack's default bindings are
        /// fresh (no existing default) vs conflicts (would replace one). No mutation;
        /// used to warn before "Set pack as defaults" clobbers existing bindings.</summary>
        public SetDefaultsPreview PreviewPackDefaults(InstalledPack pack)
        {
            var preview = new SetDefaultsPreview();
            if (pack?.Entries == null) return preview;
            var carDefaults  = Settings?.CarDefaults;
            var gameDefaults = Settings?.GameDefaults;
            foreach (var e in pack.Entries)
            {
                if (e == null) continue;
                if (e.Kind == InstalledPackEntry.KindCar)
                {
                    if (string.IsNullOrEmpty(e.CarId) || string.IsNullOrEmpty(e.PresetName)) continue;
                    if (carDefaults != null && carDefaults.ContainsKey(e.CarId)) preview.ConflictCount++;
                    else preview.FreshCount++;
                }
                else if (e.Kind == InstalledPackEntry.KindGame)
                {
                    if (e.DefaultForGames == null || e.DefaultForGames.Count == 0 || string.IsNullOrEmpty(e.Name)) continue;
                    foreach (var gameKey in e.DefaultForGames)
                    {
                        if (string.IsNullOrEmpty(gameKey)) continue;
                        if (gameDefaults != null && gameDefaults.ContainsKey(gameKey)) preview.ConflictCount++;
                        else preview.FreshCount++;
                    }
                }
            }
            return preview;
        }

        /// <summary>Walk an installed pack's entries and bind each one as the
        /// active default (game preset for its game key(s), car preset for its
        /// carId). Game entries without a DefaultForGames hint are counted as
        /// skipped. With OverwriteAll, existing defaults are replaced and tallied;
        /// with SkipConflicts, an entry whose game/car already has a default is
        /// kept and counted in the *SkippedConflict tallies.</summary>
        public SetDefaultsSummary SetPackAsDefaults(InstalledPack pack, SetDefaultsConflictPolicy policy = SetDefaultsConflictPolicy.OverwriteAll)
        {
            var summary = new SetDefaultsSummary();
            if (pack?.Entries == null) return summary;

            if (Settings.GameDefaults == null) Settings.GameDefaults = new Dictionary<string, string>();
            if (Settings.CarDefaults  == null) Settings.CarDefaults  = new Dictionary<string, string>();

            string folder = UserPresets.CurrentFolder;
            bool activeCarBindingChanged = false;

            foreach (var e in pack.Entries)
            {
                if (e == null) continue;
                if (e.Kind == InstalledPackEntry.KindCar)
                {
                    if (string.IsNullOrEmpty(e.CarId) || string.IsNullOrEmpty(e.PresetName)) continue;
                    bool carExists = Settings.CarDefaults.TryGetValue(e.CarId, out string prev);
                    if (policy == SetDefaultsConflictPolicy.SkipConflicts && carExists)
                    {
                        summary.CarDefaultsSkippedConflict++;
                        continue;
                    }
                    if (carExists && !string.Equals(prev, e.PresetName, StringComparison.Ordinal))
                        summary.CarDefaultsOverwritten++;
                    Settings.CarDefaults[e.CarId] = e.PresetName;
                    ClearCarSuppression(e.CarId);
                    BuiltinPresetWriter.SetCarDefault(folder, e.CarId, e.PresetName);
                    summary.CarDefaultsSet++;
                    if (string.Equals(_activeCarId, e.CarId, StringComparison.Ordinal))
                        activeCarBindingChanged = true;
                }
                else if (e.Kind == InstalledPackEntry.KindGame)
                {
                    // Game preset → game-default binding needs to know which
                    // game(s) the pack intends this preset to be the default
                    // for. That hint lives on DefaultForGames (populated from
                    // the pack manifest when present). When missing we skip
                    // rather than guessing from the user's current
                    // GameDefaultBindings, which would silently overwrite the
                    // pack author's intent.
                    if (e.DefaultForGames == null || e.DefaultForGames.Count == 0 || string.IsNullOrEmpty(e.Name))
                    {
                        summary.GamePresetsSkipped++;
                        continue;
                    }
                    foreach (var gameKey in e.DefaultForGames)
                    {
                        if (string.IsNullOrEmpty(gameKey)) continue;
                        bool gameExists = Settings.GameDefaults.TryGetValue(gameKey, out string prev);
                        if (policy == SetDefaultsConflictPolicy.SkipConflicts && gameExists)
                        {
                            summary.GameDefaultsSkippedConflict++;
                            continue;
                        }
                        if (gameExists && !string.Equals(prev, e.Name, StringComparison.Ordinal))
                            summary.GameDefaultsOverwritten++;
                        Settings.GameDefaults[gameKey] = e.Name;
                        BuiltinPresetWriter.SetGameDefault(folder, gameKey, e.Name);
                        summary.GameDefaultsSet++;
                    }
                }
            }

            PersistSettingsCore();
            if (activeCarBindingChanged) ReloadActiveCarOverrideFromStore();
            return summary;
        }

        // ---- Custom-engine reference analysis + auto-fallback healing -------

        // True iff this EnginePulse actively uses the given custom engine id
        // (Layout == Custom AND CustomEngineId matches). A stale id under a
        // non-Custom layout doesn't count as a live reference.
        private static bool EnginePulseRefsEngine(EnginePulseSettings ep, string engineId)
            => ep != null
            && ep.Layout == Effects.EngineLayout.Custom
            && !string.IsNullOrEmpty(ep.CustomEngineId)
            && string.Equals(ep.CustomEngineId, engineId, StringComparison.Ordinal);

        private CustomEngineDef FindCustomEngineById(string id)
        {
            if (string.IsNullOrEmpty(id) || Settings?.CustomEngines == null) return null;
            foreach (var c in Settings.CustomEngines)
                if (c != null && string.Equals(c.Id, id, StringComparison.Ordinal)) return c;
            return null;
        }

        // Record an engine pack entry for each manifest engine this pack bundles
        // that resolved into the library. Recorded for EVERY bundling pack (not
        // just the one that first added it) so "N other packs contain this
        // engine" is meaningful on removal. BaselineHash is taken from the
        // library def so removal can detect later edits. When onlyIds is non-null,
        // restrict to that set (selective import). Safe to list a shared engine:
        // removal only deletes an engine that nothing else references.
        private void AddEnginePackEntries(List<InstalledPackEntry> packEntries,
            IEnumerable<CustomEngineDef> manifestEngines, HashSet<string> onlyIds = null)
        {
            if (packEntries == null || manifestEngines == null) return;
            var seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (var eng in manifestEngines)
            {
                if (eng == null || string.IsNullOrEmpty(eng.Id)) continue;
                if (onlyIds != null && !onlyIds.Contains(eng.Id)) continue;
                if (!seen.Add(eng.Id)) continue;
                var libDef = FindCustomEngineById(eng.Id);
                if (libDef == null) continue;
                packEntries.Add(new InstalledPackEntry
                {
                    Kind         = InstalledPackEntry.KindEngine,
                    EngineId     = eng.Id,
                    Name         = libDef.Name,
                    BaselineHash = PresetBodyHasher.ComputeCustomEngineHash(libDef),
                });
            }
        }

        /// <summary>Count where a custom engine is referenced: the global
        /// default, every game preset (incl. inline car overrides), every car
        /// preset, the active config, and (since the 2026-07 centralization the
        /// LIVE reference class) every Car facts variant pinned to it. Optional
        /// exclusions skip a pack's own presets so pack-removal math counts only
        /// references that would survive the removal. Public for the Customs-tab
        /// delete warning.</summary>
        public EngineUsage GetEngineUsage(string engineId) => AnalyzeEngineUsage(engineId, null, null);

        private EngineUsage AnalyzeEngineUsage(string engineId,
            ISet<string> excludeGameNames, ISet<(string carId, string presetName)> excludeCarKeys)
        {
            var u = new EngineUsage();
            if (string.IsNullOrEmpty(engineId) || Settings == null) return u;

            if (EnginePulseRefsEngine(Settings.EnginePulse, engineId)) u.GlobalDefault = true;

            if (Settings.Presets != null)
            {
                foreach (var kv in Settings.Presets)
                {
                    if (excludeGameNames != null && excludeGameNames.Contains(kv.Key)) continue;
                    var snap = kv.Value;
                    if (snap == null) continue;
                    bool hit = EnginePulseRefsEngine(snap.EnginePulse, engineId);
                    if (!hit && snap.CarOverrides != null)
                        foreach (var inl in snap.CarOverrides.Values)
                            if (EnginePulseRefsEngine(inl?.EnginePulse, engineId)) { hit = true; break; }
                    if (hit) u.GamePresetCount++;
                }
            }

            foreach (var carKv in GetAllCarPresets())
            {
                foreach (var pKv in carKv.Value)
                {
                    var entry = pKv.Value;
                    if (entry?.Override == null) continue;
                    if (excludeCarKeys != null
                        && excludeCarKeys.Contains((carKv.Key, pKv.Key))) continue;
                    if (EnginePulseRefsEngine(entry.Override.EnginePulse, engineId)) u.CarPresetCount++;
                }
            }

            var activeEp = GetActiveCarOverride()?.EnginePulse ?? Settings.EnginePulse;
            if (EnginePulseRefsEngine(activeEp, engineId)) u.ActiveConfig = true;

            // Car facts variant pins: the live way an engine is referenced since
            // the 2026-07 centralization (the preset fields above are legacy).
            // No exclusions apply - pins are car truth, not pack entries, so
            // they always survive a pack removal.
            lock (_carFactsLock)
            {
                if (Settings.CarFacts != null)
                    foreach (var fb in Settings.CarFacts.Values)
                    {
                        if (fb?.EngineVariants == null) continue;
                        foreach (var v in fb.EngineVariants)
                            if (v != null && v.UserEngineLayout == Effects.EngineLayout.Custom
                                && string.Equals(v.UserCustomEngineId, engineId, StringComparison.Ordinal))
                                u.VariantPinCount++;
                    }
            }

            return u;
        }

        // Game-preset names + car (carId, presetName) keys this pack installed,
        // so usage analysis can exclude them (they're being removed alongside).
        private (HashSet<string> games, HashSet<(string carId, string presetName)> cars) PackEntryExclusions(InstalledPack pack)
        {
            var games = new HashSet<string>(StringComparer.Ordinal);
            var cars  = new HashSet<(string carId, string presetName)>();
            if (pack?.Entries != null)
                foreach (var e in pack.Entries)
                {
                    if (e == null) continue;
                    if (e.Kind == InstalledPackEntry.KindGame && !string.IsNullOrEmpty(e.Name))
                        games.Add(e.Name);
                    else if (e.Kind == InstalledPackEntry.KindCar
                        && !string.IsNullOrEmpty(e.CarId) && !string.IsNullOrEmpty(e.PresetName))
                        cars.Add((e.CarId, e.PresetName));
                }
            return (games, cars);
        }

        // Other installed packs (not `exclude`) that also list this engine id.
        private int CountOtherPacksWithEngine(string engineId, InstalledPack exclude)
        {
            if (string.IsNullOrEmpty(engineId) || _installedPacks == null) return 0;
            int n = 0;
            foreach (var p in _installedPacks.Load().Packs)
            {
                if (p == null || ReferenceEquals(p, exclude) || p.Entries == null) continue;
                foreach (var e in p.Entries)
                    if (e != null && e.Kind == InstalledPackEntry.KindEngine
                        && string.Equals(e.EngineId, engineId, StringComparison.Ordinal))
                    { n++; break; }
            }
            return n;
        }

        // True iff the engine is referenced by anything OUTSIDE this pack: another
        // installed pack, or a preset/override that isn't one of this pack's own
        // entries (which are being removed with it).
        private bool IsEngineReferencedOutsidePack(string engineId, InstalledPack pack)
        {
            if (CountOtherPacksWithEngine(engineId, pack) > 0) return true;
            var (xg, xc) = PackEntryExclusions(pack);
            return AnalyzeEngineUsage(engineId, xg, xc).TotalRefs > 0;
        }

        // An engine pack entry counts as "edited" only when its install-time
        // BaselineHash is recorded AND the current library def's content differs.
        private bool EngineEntryEdited(InstalledPackEntry e)
        {
            if (e == null || string.IsNullOrEmpty(e.BaselineHash) || string.IsNullOrEmpty(e.EngineId))
                return false;
            var def = FindCustomEngineById(e.EngineId);
            if (def == null) return false; // already gone; nothing to protect
            return !string.Equals(PresetBodyHasher.ComputeCustomEngineHash(def), e.BaselineHash,
                                  StringComparison.Ordinal);
        }

        /// <summary>What removing this pack would touch, computed before any
        /// deletion so the UI can prompt: how many entries the user edited, and
        /// which bundled engines are still used outside the pack.</summary>
        public PackRemovalImpact AnalyzePackRemoval(InstalledPack pack)
        {
            var impact = new PackRemovalImpact();
            if (pack?.Entries == null) return impact;
            foreach (var e in pack.Entries)
            {
                if (e == null) continue;
                if (e.Kind == InstalledPackEntry.KindGame)
                {
                    if (!string.IsNullOrEmpty(e.Name)
                        && !IsEntrySafeToDelete(e, gameName: e.Name, isCar: false))
                        impact.EditedEntryCount++;
                }
                else if (e.Kind == InstalledPackEntry.KindCar)
                {
                    if (!string.IsNullOrEmpty(e.CarId) && !string.IsNullOrEmpty(e.PresetName)
                        && !IsEntrySafeToDelete(e, gameName: null, isCar: true))
                        impact.EditedEntryCount++;
                }
                else if (e.Kind == InstalledPackEntry.KindEngine)
                {
                    if (string.IsNullOrEmpty(e.EngineId)) continue;
                    if (FindCustomEngineById(e.EngineId) == null) continue; // already gone
                    if (EngineEntryEdited(e)) impact.EditedEntryCount++;
                    int otherPacks  = CountOtherPacksWithEngine(e.EngineId, pack);
                    var (xg, xc)    = PackEntryExclusions(pack);
                    int outsideRefs = AnalyzeEngineUsage(e.EngineId, xg, xc).TotalRefs;
                    if (otherPacks > 0 || outsideRefs > 0)
                        impact.SharedEngines.Add(new SharedEngineRef
                        {
                            EngineId          = e.EngineId,
                            EngineName        = FindCustomEngineById(e.EngineId)?.Name ?? "(custom engine)",
                            OtherPackCount    = otherPacks,
                            OutsidePresetRefs = outsideRefs,
                        });
                }
            }
            return impact;
        }

        // Rewrite every stored preset / car preset / global default / in-memory
        // override whose EnginePulse points Layout=Custom at one of `deletedIds`
        // back to Layout=Auto (clearing CustomEngineId), so a deleted engine
        // leaves an Auto-resolved feel instead of a dangling Custom ref. Built-in
        // (factory) presets are skipped. Returns the number of items rewritten.
        // Callers persist + re-apply afterward.
        private int RewriteEnginePulseToAuto(ISet<string> deletedIds)
        {
            if (deletedIds == null || deletedIds.Count == 0) return 0;
            int rewritten = 0;

            bool ClearIfDeleted(EnginePulseSettings ep)
            {
                if (ep != null && ep.Layout == Effects.EngineLayout.Custom
                    && !string.IsNullOrEmpty(ep.CustomEngineId)
                    && deletedIds.Contains(ep.CustomEngineId))
                {
                    ep.Layout = Effects.EngineLayout.Auto;
                    ep.CustomEngineId = "";
                    return true;
                }
                return false;
            }

            // Global default + in-memory active per-car overrides.
            if (ClearIfDeleted(Settings?.EnginePulse)) rewritten++;
            if (Settings?.CarOverrides != null)
                foreach (var ovr in Settings.CarOverrides.Values)
                    if (ClearIfDeleted(ovr?.EnginePulse)) rewritten++;

            // Stored user game presets (factory files are not user-writable).
            try
            {
                foreach (var kv in new List<KeyValuePair<string, string>>(UserPresets.PresetJsons))
                {
                    try
                    {
                        var snap = Newtonsoft.Json.JsonConvert.DeserializeObject<GameSettingsSnapshot>(kv.Value, SafeJson.Settings);
                        if (snap == null) continue;
                        bool changed = ClearIfDeleted(snap.EnginePulse);
                        if (snap.CarOverrides != null)
                            foreach (var inl in snap.CarOverrides.Values)
                                if (ClearIfDeleted(inl?.EnginePulse)) changed = true;
                        if (changed)
                        {
                            string json = Newtonsoft.Json.JsonConvert.SerializeObject(snap, Newtonsoft.Json.Formatting.Indented);
                            BuiltinPresetWriter.WriteGame(UserPresets.CurrentFolder, kv.Key, json);
                            rewritten++;
                        }
                    }
                    catch (Exception ex)
                    { SimHub.Logging.Current.Warn($"[TF4ALL] Engine auto-fallback rewrite of game preset '{kv.Key}' failed: {ex.Message}"); }
                }
            }
            catch (Exception ex)
            { SimHub.Logging.Current.Warn($"[TF4ALL] Engine auto-fallback game-preset sweep failed: {ex.Message}"); }

            // Stored user car presets (skip built-ins).
            try
            {
                foreach (var carKv in GetAllCarPresets())
                    foreach (var pKv in carKv.Value)
                    {
                        var entry = pKv.Value;
                        if (entry == null || entry.IsBuiltin || entry.Override == null) continue;
                        if (ClearIfDeleted(entry.Override.EnginePulse))
                        {
                            try { _carStore?.Save(entry.CarId, entry.PresetName, entry.GameName, entry.Override); rewritten++; }
                            catch (Exception ex)
                            { SimHub.Logging.Current.Warn($"[TF4ALL] Engine auto-fallback rewrite of car preset '{entry.CarId}/{entry.PresetName}' failed: {ex.Message}"); }
                        }
                    }
            }
            catch (Exception ex)
            { SimHub.Logging.Current.Warn($"[TF4ALL] Engine auto-fallback car-preset sweep failed: {ex.Message}"); }

            // Car facts variant pins (2026-07 centralization): clear any
            // UserEngineLayout pin that referenced a deleted custom so the
            // variant falls back to the auto cascade instead of dangling.
            lock (_carFactsLock)
            {
                if (Settings?.CarFacts != null)
                    foreach (var fb in Settings.CarFacts.Values)
                    {
                        if (fb?.EngineVariants == null) continue;
                        foreach (var variant in fb.EngineVariants)
                        {
                            if (variant == null) continue;
                            if (variant.UserEngineLayout == Effects.EngineLayout.Custom
                                && !string.IsNullOrEmpty(variant.UserCustomEngineId)
                                && deletedIds.Contains(variant.UserCustomEngineId))
                            {
                                variant.UserEngineLayout   = null;
                                variant.UserCustomEngineId = "";
                                rewritten++;
                            }
                        }
                    }
            }

            return rewritten;
        }

        /// <summary>Delete custom engines by id, then heal: any preset / override
        /// / global default / active config that referenced one falls back to
        /// Auto (eager rewrite + live re-apply). Returns how many engines were
        /// removed. Used by the Customs-tab delete.</summary>
        public int DeleteCustomEngines(IEnumerable<string> ids)
        {
            if (ids == null || Settings?.CustomEngines == null) return 0;
            var idSet = new HashSet<string>(StringComparer.Ordinal);
            foreach (var s in ids) if (!string.IsNullOrEmpty(s)) idSet.Add(s);
            if (idSet.Count == 0) return 0;
            int removed = Settings.CustomEngines.RemoveAll(c => c != null && c.Id != null && idSet.Contains(c.Id));
            if (removed == 0) return 0;
            RewriteEnginePulseToAuto(idSet);
            UserPresets.Reload();
            RebuildPresetCacheFromFolders();
            PersistSettings();
            if (!string.IsNullOrEmpty(_activeCarId)) ReloadActiveCarOverrideFromStore();
            ApplyActiveCarOverride();
            // The pin heal above edits Settings.CarFacts, and since the 2026-07
            // centralization ApplyEngineSettings applies FEEL only: without a
            // re-resolve the live effect keeps playing the deleted engine's
            // pattern until the next car change.
            ReresolveActiveCarFacts();
            return removed;
        }

        /// <summary>Destructively remove an installed pack. Game/car/engine
        /// entries are deleted unless the user edited them (kept unless
        /// <see cref="RemovePackOptions.RemoveEditedEntries"/>); a bundled engine
        /// still used outside the pack is kept unless
        /// <see cref="RemovePackOptions.DeleteSharedEngines"/>. Any preset left
        /// pointing at a deleted engine is healed to Auto. The pack record is
        /// dropped either way.</summary>
        public RemovePackSummary RemovePack(InstalledPack pack)
            => RemovePack(pack, new RemovePackOptions());

        public RemovePackSummary RemovePack(InstalledPack pack, RemovePackOptions options)
        {
            var summary = new RemovePackSummary();
            if (pack == null) return summary;
            options = options ?? new RemovePackOptions();

            string folder = UserPresets.CurrentFolder;
            bool gameTouched = false, carTouched = false;
            var deletedEngineIds = new HashSet<string>(StringComparer.Ordinal);

            if (pack.Entries != null)
            {
                foreach (var e in pack.Entries)
                {
                    if (e == null) continue;
                    if (e.Kind == InstalledPackEntry.KindGame)
                    {
                        if (string.IsNullOrEmpty(e.Name)) continue;
                        bool edited = !IsEntrySafeToDelete(e, gameName: e.Name, isCar: false);
                        if (!edited || options.RemoveEditedEntries)
                        {
                            try { BuiltinPresetWriter.DeleteGame(folder, e.Name); summary.EntriesDeleted++; gameTouched = true; }
                            catch (Exception ex)
                            {
                                SimHub.Logging.Current.Warn($"[TF4ALL] Pack remove: delete of game preset '{e.Name}' failed: {ex.Message}");
                                summary.EntriesKept++;
                            }
                        }
                        else summary.EntriesKept++;
                    }
                    else if (e.Kind == InstalledPackEntry.KindCar)
                    {
                        if (string.IsNullOrEmpty(e.CarId) || string.IsNullOrEmpty(e.PresetName)) continue;
                        bool edited = !IsEntrySafeToDelete(e, gameName: null, isCar: true);
                        if (!edited || options.RemoveEditedEntries)
                        {
                            try { _carStore?.Delete(e.CarId, e.PresetName); summary.EntriesDeleted++; carTouched = true; }
                            catch (Exception ex)
                            {
                                SimHub.Logging.Current.Warn($"[TF4ALL] Pack remove: delete of car preset '{e.CarId}/{e.PresetName}' failed: {ex.Message}");
                                summary.EntriesKept++;
                            }
                        }
                        else summary.EntriesKept++;
                    }
                    else if (e.Kind == InstalledPackEntry.KindEngine)
                    {
                        if (string.IsNullOrEmpty(e.EngineId)) continue;
                        var def = FindCustomEngineById(e.EngineId);
                        if (def == null) continue; // already gone (another pack removed it)
                        bool shared = IsEngineReferencedOutsidePack(e.EngineId, pack);
                        bool delete = shared
                            ? options.DeleteSharedEngines
                            : (!EngineEntryEdited(e) || options.RemoveEditedEntries);
                        if (delete)
                        {
                            Settings.CustomEngines.Remove(def);
                            deletedEngineIds.Add(e.EngineId);
                            summary.EntriesDeleted++;
                        }
                        else summary.EntriesKept++;
                    }
                }
            }

            _installedPacks?.RemovePack(pack);

            // Refresh the game-preset cache BEFORE healing: the rewrite reads the
            // in-memory cache, and a preset deleted above is still cached until we
            // reload. Skipping this would let the rewrite recreate (resurrect) a
            // just-deleted preset that happened to reference a deleted engine.
            if (gameTouched)
            {
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
            }

            // Heal presets/overrides still pointing at a deleted engine: -> Auto.
            if (deletedEngineIds.Count > 0)
            {
                int healed = RewriteEnginePulseToAuto(deletedEngineIds);
                if (healed > 0)
                {
                    UserPresets.Reload();
                    RebuildPresetCacheFromFolders();
                }
                PersistSettings();
                carTouched = true;
            }

            if (carTouched && !string.IsNullOrEmpty(_activeCarId)) ReloadActiveCarOverrideFromStore();
            if (deletedEngineIds.Count > 0)
            {
                ApplyActiveCarOverride();
                // Same as DeleteCustomEngines: the pin heal edits CarFacts and
                // ApplyEngineSettings is feel-only now, so re-resolve or the
                // deleted engine keeps playing until the next car change.
                ReresolveActiveCarFacts();
            }

            return summary;
        }

        // True iff RemovePack should delete this entry. Safe = we cannot prove
        // the user edited it. Unsafe = we CAN prove it (hash recorded AND
        // current file hash differs). Pre-this-work entries with no recorded
        // BaselineHash are treated as safe because the user explicitly invoked
        // destructive remove; refusing to delete them would silently leave the
        // pack's contents behind on the every-pack-installed-before-this-build
        // case, which is what we hit when the feature first shipped. The
        // hash-protected safety net still works for any pack imported AFTER
        // the BaselineHash code went live, which is the only window where we
        // can detect a user edit at all.
        private bool IsEntrySafeToDelete(InstalledPackEntry e, string gameName, bool isCar)
        {
            if (e == null) return false;
            if (string.IsNullOrEmpty(e.BaselineHash)) return true;
            try
            {
                string path;
                if (isCar)
                {
                    path = _carStore?.FindCarFile(e.CarId, e.PresetName);
                }
                else
                {
                    path = BuiltinPresetWriter.GetGamePresetPath(UserPresets.CurrentFolder, gameName);
                }
                if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return true;
                string current = InstalledPacksStore.ComputeContentHash(System.IO.File.ReadAllText(path));
                return string.Equals(current, e.BaselineHash, StringComparison.Ordinal);
            }
            catch
            {
                // If we can't even read the file, fall back to "safe to delete"
                // so the destructive button keeps doing what it advertises.
                // BuiltinPresetWriter.DeleteGame / CarPresetStore.Delete are
                // both no-op-safe on missing files.
                return true;
            }
        }

        /// <summary>Reload the installed-packs registry from disk. Wired into
        /// PackManagerWindow so it always sees current state without holding
        /// onto a stale cached file across reopens.</summary>
        public InstalledPacksFile LoadInstalledPacks() => _installedPacks?.Load() ?? new InstalledPacksFile();

        /// <summary>Register a pack downloaded from the Community browser into the
        /// installed-packs sidecar so it shows in the Library → Packs grid (and is
        /// later removable / set-as-default like a disk-imported pack). Merges by
        /// CommunitySourceId so a repeat or partial download folds into one row.
        /// The caller builds the entry list (with per-entry BaselineHash via the
        /// HashInstalled* helpers) as it imports.</summary>
        public void RegisterCommunityPack(InstalledPack pack) => _installedPacks?.AddOrMergePack(pack);

        /// <summary>Baseline hash of a just-written game preset, read back from
        /// disk so it matches what RemovePack's edit-detection recomputes. Public
        /// wrapper over <see cref="TryHashGamePresetFile"/> for the community
        /// download path.</summary>
        public string HashInstalledGamePresetFile(string presetName) => TryHashGamePresetFile(presetName);

        /// <summary>Baseline hash of a just-written car preset, read back from
        /// disk (CarPresetStore.Save folds in attribution, so the input can't be
        /// hashed directly). Public wrapper over the private helper.</summary>
        public string HashInstalledCarPresetFile(string carId, string presetName)
            => TryHashCarPresetFile(carId, presetName);

        /// <summary>Baseline hash of a custom engine now in the library, by id.
        /// Used to stamp an engine pack entry so removal can tell whether the
        /// user edited it since install.</summary>
        public string HashInstalledEngine(string engineId)
        {
            var def = FindCustomEngineById(engineId);
            return def != null ? PresetBodyHasher.ComputeCustomEngineHash(def) : null;
        }

        // Game-preset analogue of TryHashCarPresetFile: read the file back from
        // the same path RemovePack/IsEntrySafeToDelete will read, so a clean
        // (unedited) entry hashes identically and stays safe to delete.
        private string TryHashGamePresetFile(string presetName)
        {
            try
            {
                string path = BuiltinPresetWriter.GetGamePresetPath(UserPresets.CurrentFolder, presetName);
                if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return null;
                return InstalledPacksStore.ComputeContentHash(System.IO.File.ReadAllText(path));
            }
            catch { return null; }
        }

        // Stamp the baseline hash on a freshly-saved car preset. CarPresetStore.Save
        // folds existing on-disk attribution into the serialized output, so the
        // input override JSON wouldn't match what landed on disk; reading the
        // file back is the only way to capture an accurate baseline.
        private string TryHashCarPresetFile(string carId, string presetName)
        {
            try
            {
                string path = _carStore?.FindCarFile(carId, presetName);
                if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return null;
                return InstalledPacksStore.ComputeContentHash(System.IO.File.ReadAllText(path));
            }
            catch { return null; }
        }

        // Replace anything not-safe-in-a-zip-entry-name with '_'. Defers to the
        // shared SafePath sanitizer (also blocks reserved DOS device names and
        // trailing dots/spaces).
        private static string SanitizeForZip(string s)
        {
            return SafePath.SanitizeForFilename(s);
        }

        private static void WriteJsonZipEntry(System.IO.Compression.ZipArchive zip, string entryName, object obj)
        {
            var entry = zip.CreateEntry(entryName, System.IO.Compression.CompressionLevel.Optimal);
            using (var s = entry.Open())
            using (var w = new System.IO.StreamWriter(s))
            {
                w.Write(Newtonsoft.Json.JsonConvert.SerializeObject(obj, Newtonsoft.Json.Formatting.Indented));
            }
        }

        private static T ReadJsonZipEntry<T>(System.IO.Compression.ZipArchiveEntry entry) where T : class
        {
            try
            {
                using (var s = entry.Open())
                using (var r = new System.IO.StreamReader(s))
                {
                    return Newtonsoft.Json.JsonConvert.DeserializeObject<T>(r.ReadToEnd());
                }
            }
            catch
            {
                return null;
            }
        }

        // ---------- export / import ----------

        /// <summary>Bundle ALL user-owned Trueforce data into one zip archive
        /// for moving to another machine. Contents:
        ///   GeneralSettings.json (the plugin's settings JSON)
        ///   user/                 (every preset, default, and metadata file
        ///                          the user owns; factory/ is intentionally
        ///                          excluded because the plugin ships with it).
        /// No customization, no per-preset metadata dialog. Conceptually
        /// different from ExportPack / ExportSinglePreset: backup is a
        /// snapshot of state, not a curated share.</summary>
        public (int fileCount, long totalBytes) BackupAllToZip(string zipPath)
        {
            if (string.IsNullOrEmpty(zipPath)) return (0, 0);
            int fileCount = 0;
            long totalBytes = 0;

            using (var fs = new System.IO.FileStream(zipPath, System.IO.FileMode.Create, System.IO.FileAccess.Write))
            using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Create))
            {
                // 1) Plugin settings JSON. Re-serialize live Settings so the
                // backup matches the running state, not whatever's on disk
                // (which lags an unflushed in-memory change).
                if (Settings != null)
                {
                    string settingsJson = Newtonsoft.Json.JsonConvert.SerializeObject(Settings, Newtonsoft.Json.Formatting.Indented);
                    var entry = zip.CreateEntry("GeneralSettings.json", System.IO.Compression.CompressionLevel.Optimal);
                    using (var ws = entry.Open())
                    using (var sw = new System.IO.StreamWriter(ws, new System.Text.UTF8Encoding(false)))
                        sw.Write(settingsJson);
                    fileCount++;
                    totalBytes += settingsJson.Length;
                }

                // 2) Everything under user/ — preset files, defaults files,
                // installed-packs sidecar, README. Skip .cleanup-<timestamp>/
                // backup directories produced by the legacy-builtin migration.
                string userRoot = UserPresets.CurrentFolder;
                if (!string.IsNullOrEmpty(userRoot) && System.IO.Directory.Exists(userRoot))
                {
                    foreach (var path in System.IO.Directory.GetFiles(userRoot, "*", System.IO.SearchOption.AllDirectories))
                    {
                        if (path.IndexOf($"{System.IO.Path.DirectorySeparatorChar}.cleanup-", StringComparison.Ordinal) >= 0)
                            continue;
                        string rel = "user/" + path.Substring(userRoot.Length).TrimStart('\\', '/').Replace('\\', '/');
                        try
                        {
                            var bytes = System.IO.File.ReadAllBytes(path);
                            var entry = zip.CreateEntry(rel, System.IO.Compression.CompressionLevel.Optimal);
                            using (var ws = entry.Open())
                                ws.Write(bytes, 0, bytes.Length);
                            fileCount++;
                            totalBytes += bytes.LongLength;
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] Backup: couldn't add '{path}': {ex.Message}");
                        }
                    }
                }
            }
            SimHub.Logging.Current.Info($"[TF4ALL] Backup wrote {fileCount} entries ({totalBytes} bytes) to {zipPath}.");
            return (fileCount, totalBytes);
        }

        /// <summary>Replace ALL user-owned Trueforce data with the contents of
        /// a backup zip produced by BackupAllToZip. Wipes the user/ folder
        /// (after backing it up to a sibling .pre-restore-<timestamp>/ folder
        /// for safety), extracts the archive in its place, restores
        /// GeneralSettings.json into Settings, and reloads everything from
        /// disk. Returns the number of files restored.
        ///
        /// Destructive: the caller must have confirmed with the user.</summary>
        public int RestoreAllFromZip(string zipPath, bool applySettings = true)
        {
            if (string.IsNullOrEmpty(zipPath) || !System.IO.File.Exists(zipPath)) return 0;

            string userRoot = UserPresets.CurrentFolder;
            if (string.IsNullOrEmpty(userRoot)) throw new InvalidOperationException("User library folder is not set.");
            // Trim any trailing path separator so the .pre-restore-<stamp>
            // sibling computation produces a sibling rather than a child path
            // (e.g. "C:\path\user\.pre-restore-..." instead of the intended
            // "C:\path\user.pre-restore-...").
            userRoot = userRoot.TrimEnd(System.IO.Path.DirectorySeparatorChar, System.IO.Path.AltDirectorySeparatorChar);

            // Snapshot live Settings + the previous-user-folder path BEFORE
            // mutating disk, so we can roll back to byte-identical pre-state
            // if extraction or ImportSettings fails. The confirmation dialog
            // promised a safety net; this is the implementation.
            TrueforceSettings preState = null;
            try
            {
                preState = Newtonsoft.Json.JsonConvert.DeserializeObject<TrueforceSettings>(
                    Newtonsoft.Json.JsonConvert.SerializeObject(Settings));
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] Restore: couldn't snapshot live Settings (will continue without rollback safety net): {ex.Message}");
            }

            string stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
            string safeDir = userRoot + ".pre-restore-" + stamp;
            bool movedAside = false;
            if (System.IO.Directory.Exists(userRoot))
            {
                try
                {
                    System.IO.Directory.Move(userRoot, safeDir);
                    movedAside = true;
                }
                catch (Exception ex)
                {
                    // Abort: continuing with extract would overwrite live
                    // data without a safety net, breaking the confirmation
                    // dialog's promise.
                    throw new InvalidOperationException(
                        $"Could not move the existing user library out of the way ({ex.Message}). Close any open file handles in the folder and try again. No changes were made.", ex);
                }
            }
            System.IO.Directory.CreateDirectory(userRoot);

            int restored = 0;
            string settingsJson = null;
            try
            {
                using (var fs = new System.IO.FileStream(zipPath, System.IO.FileMode.Open, System.IO.FileAccess.Read))
                using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Read))
                {
                    foreach (var entry in zip.Entries)
                    {
                        if (string.IsNullOrEmpty(entry.Name)) continue;   // directory entry
                        string name = entry.FullName.Replace('\\', '/');
                        if (name == "GeneralSettings.json")
                        {
                            using (var es = entry.Open())
                            using (var sr = new System.IO.StreamReader(es))
                                settingsJson = sr.ReadToEnd();
                            continue;
                        }
                        if (name.StartsWith("user/", StringComparison.Ordinal))
                        {
                            string rel = name.Substring("user/".Length);
                            // ZIP Slip guard: reject any backup entry that
                            // would escape the user library (absolute path,
                            // '..' segment, or canonicalized destination
                            // outside userRoot).
                            if (!SafePath.IsSafeArchivePath(userRoot, rel, out string dest)) continue;

                            System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(dest));
                            using (var es = entry.Open())
                            using (var ws = System.IO.File.Create(dest))
                                es.CopyTo(ws);
                            restored++;
                        }
                    }
                }

                // Apply settings JSON via the existing ImportSettings path so
                // all the live-effect plumbing + re-cache + active-car reload
                // runs. Any failure here will be caught + rolled back below.
                // Skipped when the caller chose "keep my settings" (applySettings
                // false): the extracted library is still loaded via the else branch.
                if (applySettings && !string.IsNullOrEmpty(settingsJson))
                {
                    string tmp = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"tf4all-restore-{stamp}.json");
                    System.IO.File.WriteAllText(tmp, settingsJson);
                    try { ImportSettings(tmp); }
                    finally { try { System.IO.File.Delete(tmp); } catch { } }

                    // The extracted user/ is already in post-V3 shape (every
                    // user/games file is a wrapped or bare snapshot, every
                    // car file is a CarPresetFile, every defaults file is in
                    // the new location). Force-flag the migrations as done so
                    // a backup from an older plugin version doesn't trigger
                    // the cleanup-migrations again on next Init and silently
                    // archive presets the user considers theirs.
                    if (Settings != null)
                    {
                        Settings.PresetsMigratedV2      = true;
                        Settings.CarsMigratedV2         = true;
                        Settings.LegacyBuiltinsCleanedV1 = true;
                        Settings.FoldersRestructuredV3  = true;
                        Settings.CarPresetOrdinalNamesMigratedV1 = true;
                        Settings.CarPresetOrdinalNamesMigratedV2 = true;
                        Settings.ForzaCarIdsNormalizedV1         = true;
                    }
                }
                else
                {
                    UserPresets.Reload();
                    RebuildPresetCacheFromFolders();
                    LoadAndMigrateCarPresets();
                }
            }
            catch (Exception ex)
            {
                // Roll back: delete the partial extract, move the original
                // user folder back, restore the live Settings snapshot.
                try
                {
                    if (System.IO.Directory.Exists(userRoot)) System.IO.Directory.Delete(userRoot, recursive: true);
                }
                catch (Exception delEx)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Restore rollback: couldn't delete partial extract: {delEx.Message}");
                }
                if (movedAside && System.IO.Directory.Exists(safeDir))
                {
                    try { System.IO.Directory.Move(safeDir, userRoot); }
                    catch (Exception mvEx)
                    {
                        SimHub.Logging.Current.Warn($"[TF4ALL] Restore rollback: couldn't move original user library back: {mvEx.Message}. Original is preserved at {safeDir}.");
                    }
                }
                if (preState != null)
                {
                    Settings = preState;
                    // ImportSettings may already have reconciled the device to
                    // the zip's PluginEnabled before the failure; the rollback
                    // restores the old flag, so reconcile again or the device
                    // keeps the zip's pause state (streaming while "disabled",
                    // or paused while "enabled").
                    SyncDeviceToPluginEnabled("Restore rollback");
                    // ImportSettings pushes the zip's feel to the LIVE model
                    // (master gain, FFB scalars, the Mode B recipe, audio)
                    // before this failure; restoring the settings object alone
                    // would leave the wheel rendering the failed zip's tuning
                    // while the panel shows the pre-restore values. Re-apply
                    // the same live surfaces the import touched.
                    try
                    {
                        _mixer.MasterGain = Settings.MasterGain;
                        ApplyGlobalFfbToLive();
                        ApplyModeBFromSettings();
                        ApplyModeBFeel();
                        if (_audio != null)
                        {
                            _audio.Enabled          = Settings.AudioCapture.Enabled;
                            _audio.Gain             = Settings.AudioCapture.Gain;
                            _audio.LowpassCutoffHz  = Settings.AudioCapture.LowpassCutoffHz;
                            _audio.HighpassCutoffHz = Settings.AudioCapture.HighpassCutoffHz;
                        }
                    }
                    catch (Exception reEx)
                    {
                        SimHub.Logging.Current.Warn(
                            "[TF4ALL] Restore rollback: live re-apply failed: " + reEx.Message);
                    }
                    try
                    {
                        UserPresets.Reload();
                        RebuildPresetCacheFromFolders();
                        LoadAndMigrateCarPresets();
                    }
                    catch { /* swallow; the user is being shown an error already */ }
                }
                throw new InvalidOperationException($"Restore failed and was rolled back: {ex.Message}", ex);
            }

            SimHub.Logging.Current.Info($"[TF4ALL] Restore extracted {restored} user file(s) from {zipPath} (previous library archived at {safeDir}).");
            return restored;
        }

        /// <summary>A backup preset that collides with one already in the user's
        /// library (same path, different content) when MERGING. Surfaced in the
        /// conflict resolver so the user picks which copy to keep.</summary>
        public sealed class BackupConflict
        {
            public string RelPath { get; set; }      // path under user/, e.g. "games/My Preset.json"
            public string DisplayName { get; set; }  // human label for the dialog
            public string Kind { get; set; }         // "game preset" / "car tuning"
        }

        // Only games/*.json and cars/**/*.json merge: they are the shareable
        // presets. Defaults files, the installed-packs sidecar, and the README
        // stay the user's own on a merge (merging presets must not repoint your
        // per-game/per-car default choices).
        private static bool IsMergeablePresetRel(string rel) =>
            rel != null
            && (rel.StartsWith("games/", StringComparison.Ordinal) || rel.StartsWith("cars/", StringComparison.Ordinal))
            && rel.EndsWith(".json", StringComparison.OrdinalIgnoreCase);

        private static string MergeDisplayName(string rel, out string kind)
        {
            string preset = System.IO.Path.GetFileNameWithoutExtension(rel);
            if (rel.StartsWith("games/", StringComparison.Ordinal)) { kind = "game preset"; return preset; }
            kind = "car tuning";
            var parts = rel.Split('/');   // cars/<game>/<carId>/<preset>.json
            return parts.Length >= 4 ? $"{preset} (car {parts[2]}, {parts[1]})" : preset;
        }

        private static bool ZipEntryMatchesFile(System.IO.Compression.ZipArchiveEntry entry, string filePath)
        {
            try
            {
                var fileBytes = System.IO.File.ReadAllBytes(filePath);
                using (var es = entry.Open())
                using (var ms = new System.IO.MemoryStream())
                {
                    es.CopyTo(ms);
                    var entryBytes = ms.ToArray();
                    if (entryBytes.Length != fileBytes.Length) return false;
                    for (int i = 0; i < entryBytes.Length; i++)
                        if (entryBytes[i] != fileBytes[i]) return false;
                    return true;
                }
            }
            catch { return false; }
        }

        /// <summary>Scan a backup zip against the current user library for a MERGE:
        /// returns the preset conflicts (same path, different content) to resolve
        /// plus the count of presets that would merge cleanly (not present today).
        /// Byte-for-byte identical presets are omitted from both (nothing to do).</summary>
        public (System.Collections.Generic.List<BackupConflict> conflicts, int newPresets, int newEngines, int newPacks) ScanBackupZipForMerge(string zipPath)
        {
            var conflicts = new System.Collections.Generic.List<BackupConflict>();
            int newPresets = 0;
            string userRoot = UserPresets.CurrentFolder;
            if (string.IsNullOrEmpty(userRoot) || string.IsNullOrEmpty(zipPath) || !System.IO.File.Exists(zipPath))
                return (conflicts, 0, 0, 0);
            userRoot = userRoot.TrimEnd(System.IO.Path.DirectorySeparatorChar, System.IO.Path.AltDirectorySeparatorChar);
            string settingsJson = null, packsJson = null;
            using (var fs = new System.IO.FileStream(zipPath, System.IO.FileMode.Open, System.IO.FileAccess.Read))
            using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Read))
            {
                foreach (var entry in zip.Entries)
                {
                    if (string.IsNullOrEmpty(entry.Name)) continue;
                    string name = entry.FullName.Replace('\\', '/');
                    if (name == "GeneralSettings.json") { settingsJson = ReadZipEntryText(entry); continue; }
                    if (!name.StartsWith("user/", StringComparison.Ordinal)) continue;
                    string rel = name.Substring("user/".Length);
                    if (rel == InstalledPacksStore.FileName) { packsJson = ReadZipEntryText(entry); continue; }
                    if (!IsMergeablePresetRel(rel)) continue;
                    if (!SafePath.IsSafeArchivePath(userRoot, rel, out string dest)) continue;
                    if (!System.IO.File.Exists(dest)) { newPresets++; continue; }
                    if (ZipEntryMatchesFile(entry, dest)) continue;   // identical -> skip silently
                    string display = MergeDisplayName(rel, out string kind);
                    conflicts.Add(new BackupConflict { RelPath = rel, DisplayName = display, Kind = kind });
                }
            }
            var eng = ScanBackupEngines(settingsJson);
            conflicts.AddRange(eng.conflicts);
            return (conflicts, newPresets, eng.newEngines, CountNewBackupPacks(packsJson));
        }

        private static string ReadZipEntryText(System.IO.Compression.ZipArchiveEntry entry)
        {
            using (var es = entry.Open())
            using (var sr = new System.IO.StreamReader(es))
                return sr.ReadToEnd();
        }

        // Custom engines live in Settings.CustomEngines (not files); packs live in
        // installed-packs.json. These count how many of the backup's would be NEW
        // for the merge summary (identity: engine Id, pack CommunitySourceId/name).
        private enum EngineMergeStatus { AlreadyHave, New, Conflict }

        // Classify a backup custom engine against this PC's engines. Same Id (or
        // same name + same content) = already have; same NAME with different content
        // = a conflict the user resolves; otherwise new. Content = the firing Pattern,
        // matching the existing MergeImportedCustomEngines dedup signal.
        private static EngineMergeStatus ClassifyBackupEngine(CustomEngineDef eb, List<CustomEngineDef> current, out CustomEngineDef conflicting)
        {
            conflicting = null;
            if (eb == null || string.IsNullOrEmpty(eb.Name)) return EngineMergeStatus.AlreadyHave;
            current = current ?? new List<CustomEngineDef>();
            if (!string.IsNullOrEmpty(eb.Id) && current.Any(c => !string.IsNullOrEmpty(c?.Id) && c.Id == eb.Id))
                return EngineMergeStatus.AlreadyHave;
            var byName = current.FirstOrDefault(c => string.Equals(c?.Name, eb.Name, StringComparison.Ordinal));
            if (byName == null) return EngineMergeStatus.New;
            if (string.Equals(byName.Pattern, eb.Pattern, StringComparison.Ordinal)) return EngineMergeStatus.AlreadyHave;
            conflicting = byName;
            return EngineMergeStatus.Conflict;
        }

        // Backup custom engines for the merge summary + conflict resolver: how many
        // are new, and which clash by name with different content.
        private (int newEngines, List<BackupConflict> conflicts) ScanBackupEngines(string settingsJson)
        {
            var conflicts = new List<BackupConflict>();
            if (string.IsNullOrEmpty(settingsJson)) return (0, conflicts);
            List<CustomEngineDef> backupEngines;
            try { backupEngines = Newtonsoft.Json.JsonConvert.DeserializeObject<TrueforceSettings>(settingsJson)?.CustomEngines; }
            catch { return (0, conflicts); }
            if (backupEngines == null) return (0, conflicts);
            var current = Settings?.CustomEngines ?? new List<CustomEngineDef>();
            int newEngines = 0;
            foreach (var eb in backupEngines)
            {
                var status = ClassifyBackupEngine(eb, current, out _);
                if (status == EngineMergeStatus.New) newEngines++;
                else if (status == EngineMergeStatus.Conflict)
                    conflicts.Add(new BackupConflict { RelPath = "engine:" + eb.Name, DisplayName = eb.Name, Kind = "custom engine" });
            }
            return (newEngines, conflicts);
        }

        private int CountNewBackupPacks(string packsJson)
        {
            if (string.IsNullOrEmpty(packsJson)) return 0;
            try
            {
                var backupPacks = Newtonsoft.Json.JsonConvert.DeserializeObject<InstalledPacksFile>(packsJson, SafeJson.Settings)?.Packs;
                if (backupPacks == null || backupPacks.Count == 0) return 0;
                var cur = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
                foreach (var p in LoadInstalledPacks().Packs ?? new List<InstalledPack>())
                { string k = p?.CommunitySourceId ?? p?.PackName; if (!string.IsNullOrEmpty(k)) cur.Add(k); }
                int n = 0;
                foreach (var p in backupPacks)
                { string k = p?.CommunitySourceId ?? p?.PackName; if (!string.IsNullOrEmpty(k) && !cur.Contains(k)) n++; }
                return n;
            }
            catch { return 0; }
        }

        /// <summary>Merge a backup zip's presets into the current user library
        /// WITHOUT wiping it. New presets are added; a colliding preset is written
        /// only if its rel-path is in <paramref name="overwriteRelPaths"/> (the
        /// user chose the backup's copy), otherwise the user's copy is kept.
        /// Byte-identical presets are skipped. Optionally applies the backup's
        /// settings (same import + cross-wheel gate as a restore). Returns the
        /// number of preset files written.</summary>
        public int MergeBackupFromZip(string zipPath, System.Collections.Generic.ISet<string> overwriteRelPaths, bool applySettings)
        {
            if (string.IsNullOrEmpty(zipPath) || !System.IO.File.Exists(zipPath)) return 0;
            overwriteRelPaths = overwriteRelPaths ?? new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
            string userRoot = UserPresets.CurrentFolder;
            if (string.IsNullOrEmpty(userRoot)) throw new InvalidOperationException("User library folder is not set.");
            userRoot = userRoot.TrimEnd(System.IO.Path.DirectorySeparatorChar, System.IO.Path.AltDirectorySeparatorChar);

            var currentEngines = new List<CustomEngineDef>(Settings?.CustomEngines ?? new List<CustomEngineDef>());
            int merged = 0;
            string settingsJson = null, packsJson = null;
            using (var fs = new System.IO.FileStream(zipPath, System.IO.FileMode.Open, System.IO.FileAccess.Read))
            using (var zip = new System.IO.Compression.ZipArchive(fs, System.IO.Compression.ZipArchiveMode.Read))
            {
                foreach (var entry in zip.Entries)
                {
                    if (string.IsNullOrEmpty(entry.Name)) continue;
                    string name = entry.FullName.Replace('\\', '/');
                    if (name == "GeneralSettings.json") { settingsJson = ReadZipEntryText(entry); continue; }
                    if (!name.StartsWith("user/", StringComparison.Ordinal)) continue;
                    string rel = name.Substring("user/".Length);
                    if (rel == InstalledPacksStore.FileName) { packsJson = ReadZipEntryText(entry); continue; }
                    if (!IsMergeablePresetRel(rel)) continue;
                    if (!SafePath.IsSafeArchivePath(userRoot, rel, out string dest)) continue;
                    if (System.IO.File.Exists(dest))
                    {
                        if (ZipEntryMatchesFile(entry, dest)) continue;      // identical -> skip
                        if (!overwriteRelPaths.Contains(rel)) continue;      // conflict, keep mine
                    }
                    System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(dest));
                    using (var es = entry.Open())
                    using (var ws = System.IO.File.Create(dest))
                        es.CopyTo(ws);
                    merged++;
                }
            }

            // Custom engines (Settings.CustomEngines, not files) merge as a
            // content-aware UNION regardless of the settings choice. If we applied
            // the backup's settings, Settings.CustomEngines is now the backup's, so
            // union this PC's back in; otherwise union the backup's into this PC's.
            var backupEngines = TryReadBackupEngines(settingsJson);
            if (applySettings && !string.IsNullOrEmpty(settingsJson))
            {
                string tmp = System.IO.Path.Combine(System.IO.Path.GetTempPath(),
                    $"tf4all-merge-{DateTime.Now:yyyyMMdd-HHmmss}.json");
                System.IO.File.WriteAllText(tmp, settingsJson);
                try { ImportSettings(tmp); }   // sets Settings.CustomEngines = backup's; rebuilds cache
                finally { try { System.IO.File.Delete(tmp); } catch { } }
            }
            else
            {
                UserPresets.Reload();
                RebuildPresetCacheFromFolders();
                LoadAndMigrateCarPresets();
                ApplyActiveCarOverride();
            }
            // Custom engines: union THIS PC's with the backup's, honoring the same
            // conflict decisions as presets. Reset the base to this PC's engines
            // (ImportSettings above may have replaced them with the backup's), then
            // import the backup engines the user is taking: every new one, plus any
            // same-name clash the user resolved as "use the backup's" (its old copy
            // removed first). Keep-mine clashes and identical engines are left out.
            Settings.CustomEngines = new List<CustomEngineDef>(currentEngines);
            var enginesToImport = new List<CustomEngineDef>();
            if (backupEngines != null)
            {
                foreach (var eb in backupEngines)
                {
                    var status = ClassifyBackupEngine(eb, currentEngines, out var conflicting);
                    if (status == EngineMergeStatus.New)
                        enginesToImport.Add(eb);
                    else if (status == EngineMergeStatus.Conflict && overwriteRelPaths.Contains("engine:" + eb.Name))
                    {
                        if (conflicting != null) Settings.CustomEngines.Remove(conflicting);
                        enginesToImport.Add(eb);
                    }
                }
            }
            if (enginesToImport.Count > 0) ImportCommunityCustomEngines(enginesToImport);   // dedups + persists
            else PersistSettingsCore();

            // Packs: union the backup's installed-pack records (their presets
            // already merged as game/car files above). AddOrMergePack dedups by id.
            int packsMerged = 0;
            if (!string.IsNullOrEmpty(packsJson))
            {
                try
                {
                    var backupPacks = Newtonsoft.Json.JsonConvert.DeserializeObject<InstalledPacksFile>(packsJson, SafeJson.Settings)?.Packs;
                    if (backupPacks != null)
                        foreach (var p in backupPacks)
                            if (p != null) { RegisterCommunityPack(p); packsMerged++; }
                }
                catch (Exception ex) { SimHub.Logging.Current.Warn($"[TF4ALL] Merge: couldn't union installed packs: {ex.Message}"); }
            }
            SimHub.Logging.Current.Info($"[TF4ALL] Merge added {merged} preset file(s), unioned {(backupEngines?.Count ?? 0)} custom engine(s) + {packsMerged} pack record(s) from {zipPath} (applySettings={applySettings}).");
            return merged;
        }

        private static List<CustomEngineDef> TryReadBackupEngines(string settingsJson)
        {
            if (string.IsNullOrEmpty(settingsJson)) return null;
            try { return Newtonsoft.Json.JsonConvert.DeserializeObject<TrueforceSettings>(settingsJson)?.CustomEngines; }
            catch { return null; }
        }

        // Copy the BackupProjection.MachineLocal-classified properties from one settings object onto
        // another. Used by the local settings/zip restore so a backup file (possibly from another PC
        // or account) can't overwrite THIS install's identity + machine-bound config: the auth
        // session, the per-account slots, machine paths, FFB-tap pins, the per-PC sync bookkeeping,
        // and the baked backend config. Same boundary the cloud restore respects.
        private static void PreserveMachineLocalSettings(TrueforceSettings from, TrueforceSettings to)
        {
            if (from == null || to == null) return;
            var t = typeof(TrueforceSettings);
            foreach (var name in BackupProjection.MachineLocal)
            {
                var p = t.GetProperty(name, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
                if (p == null || !p.CanRead || !p.CanWrite) continue;
                try { p.SetValue(to, p.GetValue(from)); } catch { /* best-effort per field */ }
            }
        }

        /// <summary>Replace settings from a JSON file; live effects are re-derived from the new settings.</summary>
        public void ImportSettings(string path)
        {
            string json = System.IO.File.ReadAllText(path);
            var imported = Newtonsoft.Json.JsonConvert.DeserializeObject<TrueforceSettings>(json);
            if (imported == null) throw new System.IO.InvalidDataException("File did not contain valid TrueforceSettings JSON.");
            // Preserve install identity + machine-bound fields (signed-in account, per-account slots,
            // machine paths, FFB-tap pins, per-PC sync bookkeeping, baked backend config) so a backup
            // file can't change who's signed in, import a foreign slots dict, or desync the active-
            // account library folder. Mirrors the cloud restore, which keeps machine-local fields.
            var preservedMachineLocal = Settings;
            Settings = imported;
            PreserveMachineLocalSettings(preservedMachineLocal, Settings);
            // The cross-wheel FFB policy and any pending prompt are per-PC (Excluded
            // from backup); a wholesale import would otherwise replace this PC's choice
            // with the file's. Restore them so the gate below reads this PC's policy.
            Settings.CrossWheelFfbMode          = preservedMachineLocal.CrossWheelFfbMode;
            Settings.PendingCrossWheelFfb       = preservedMachineLocal.PendingCrossWheelFfb;
            Settings.PendingCrossWheelFfbSource = preservedMachineLocal.PendingCrossWheelFfbSource;
            // The imported file replaced Settings wholesale, so PluginEnabled can flip without a
            // SetPluginEnabled transition. Reconcile the device NOW, before the throw-capable
            // remainder (cross-wheel gating, slot remount, preset migration): PluginEnabled is
            // final at this point (it is Portable, so the machine-local restore never touches
            // it), and a later throw must not strand the device on the pre-import pause state.
            SyncDeviceToPluginEnabled("Settings import");
            // Cross-wheel FFB gate, same as the cloud restore: a file made on a
            // different wheel model does not silently apply its force-feedback tuning.
            // Restore this PC's FFB and, on the Ask policy, surface the apply-anyway
            // prompt. preservedMachineLocal holds this PC's real FFB + wheel.
            StashCrossWheelFfbIfGated(
                BackupProjection.GateImportedCrossWheelFfb(imported, preservedMachineLocal, Settings));
            // Re-establish active-account slot consistency (re-point its library folder + stash the
            // restored profile into the slot), exactly as the cloud restore remounts the slot.
            try { MountUserSlot(Settings.ActiveSlotKey ?? ""); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Settings import: slot remount failed: " + ex.GetType().Name); }
            _mixer.MasterGain = Settings.MasterGain;
            ApplyGlobalFfbToLive();   // push restored FFB scalars (scale/invert/spike) to the live device, not just master gain
            if (_audio != null)
            {
                _audio.Enabled          = Settings.AudioCapture.Enabled;
                _audio.Gain             = Settings.AudioCapture.Gain;
                _audio.LowpassCutoffHz  = Settings.AudioCapture.LowpassCutoffHz;
                _audio.HighpassCutoffHz = Settings.AudioCapture.HighpassCutoffHz;
            }
            // A legacy backup may include the old dict-based Presets / GameDefaults.
            // Force the one-time migration to run again so they move into files.
            if (!Settings.PresetsMigratedV2
                && ((Settings.Presets?.Count ?? 0) > 0 || (Settings.GameDefaults?.Count ?? 0) > 0))
            {
                MigrateLegacyUserPresetsToFolder();
                Settings.PresetsMigratedV2 = true;
            }
            // Rebuild the runtime cache from the (potentially updated) folders.
            RebuildPresetCacheFromFolders();
            ApplyActiveCarOverride();
            // Imported settings carry the Mode B recipe too; push it live so
            // the wheel matches what the panel now shows.
            try { ApplyModeBFromSettings(); ApplyModeBFeel(); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Settings import: Mode B re-apply failed: " + ex.Message); }
            // Imported settings carry the dash tab layout; rebuild the slot
            // map so the phone follows it without a restart.
            RefreshDashTabSlots();
            SimHub.Logging.Current.Info($"[TF4ALL] Settings imported from {path}.");
        }

        // ===================== Phase 2 Discord link (M5) =====================
        // Standalone Discord OAuth link so contribution achievements grant community-server
        // roles. One-shot: capture the Discord user id and record it server-side; no Discord
        // tokens are kept. Transport = DiscordLinkClient; the browser/loopback = DiscordOAuthFlow.
        private DiscordLinkClient _discordLinkClient;
        // Single-flight: the loopback OAuth dance binds a fixed local port, so two concurrent
        // link attempts would collide on the bind. Mirrors the backup _backupOp guard.
        private readonly System.Threading.SemaphoreSlim _discordLinkOp = new System.Threading.SemaphoreSlim(1, 1);
        // Patreon OAuth link (proves supporter status in-plugin; unlocks badge + cloud backup
        // without Discord). Transport = PatreonLinkClient; browser/loopback = PatreonOAuthFlow.
        private PatreonLinkClient _patreonLinkClient;
        private readonly System.Threading.SemaphoreSlim _patreonLinkOp = new System.Threading.SemaphoreSlim(1, 1);
        // Read-only supporter entitlement (for the in-plugin supporter badge).
        private EntitlementClient _entitlementClient;
        // Read-only Patreon supporters roster (for the Account tab's Supporters wall).
        private SupportersClient _supportersClient;
        // Achievement tracker (progress) + immediate self-scoped role sync.
        private AchievementClient _achievementClient;
        // Account session list + per-session revoke (Account tab "Active sessions").
        private SessionClient _sessionClient;
        private ModerationClient _moderationClient;

        internal struct DiscordLinkResult
        {
            public bool   Ok;
            public string Message;
            public string Username;
        }

        /// <summary>Run the full link flow: fetch OAuth config, do the browser consent +
        /// loopback capture, then exchange the code server-side for this signed-in user.</summary>
        internal async Task<DiscordLinkResult> LinkDiscordAsync(System.Threading.CancellationToken ct)
        {
            if (_discordLinkClient == null) return new DiscordLinkResult { Ok = false, Message = "Discord linking isn't available." };
            if (_auth == null || !_auth.IsSignedIn) return new DiscordLinkResult { Ok = false, Message = "Sign in to TF4ALL first." };
            if (!await _discordLinkOp.WaitAsync(0).ConfigureAwait(false))
                return new DiscordLinkResult { Ok = false, Message = "A Discord link is already in progress." };
            try
            {
                var (cfg, cfgErr) = await _discordLinkClient.GetConfigAsync(ct).ConfigureAwait(false);
                if (cfg == null || string.IsNullOrEmpty(cfg.ClientId))
                    return new DiscordLinkResult { Ok = false, Message = cfgErr ?? "Discord linking isn't set up yet." };

                DiscordOAuthFlow.Result auth;
                try
                {
                    auth = await DiscordOAuthFlow.AuthorizeAsync(cfg.ClientId, cfg.RedirectUris, cfg.Scope,
                        msg => SimHub.Logging.Current.Info(msg), ct).ConfigureAwait(false);
                }
                catch (OperationCanceledException) { return new DiscordLinkResult { Ok = false, Message = "Linking cancelled." }; }
                catch (DiscordOAuthException ex)   { return new DiscordLinkResult { Ok = false, Message = ex.Message }; }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Info("[TF4ALL] Discord authorize error: " + ex.Message);
                    return new DiscordLinkResult { Ok = false, Message = "Couldn't start Discord linking." };
                }

                var (ok, message, username) = await _discordLinkClient.ExchangeAsync(auth.Code, auth.RedirectUri, ct).ConfigureAwait(false);
                if (ok) InvalidateAccountStatusCache();   // link can change supporter-via-role + the link row
                return new DiscordLinkResult { Ok = ok, Message = message, Username = username };
            }
            finally { _discordLinkOp.Release(); }
        }

        /// <summary>Remove this user's Discord link.</summary>
        internal async Task<DiscordLinkResult> UnlinkDiscordAsync(System.Threading.CancellationToken ct)
        {
            if (_discordLinkClient == null) return new DiscordLinkResult { Ok = false, Message = "Discord linking isn't available." };
            if (_auth == null || !_auth.IsSignedIn) return new DiscordLinkResult { Ok = false, Message = "Sign in first." };
            bool ok = await _discordLinkClient.UnlinkAsync(ct).ConfigureAwait(false);
            if (ok) InvalidateAccountStatusCache();   // unlink can drop supporter-via-role + clears the link row
            return new DiscordLinkResult { Ok = ok, Message = ok ? "Discord unlinked." : "Couldn't unlink. Try again." };
        }

        /// <summary>Last-known Discord-link status, cached from GetDiscordStatusAsync so
        /// the MOTD strip can read it synchronously (mirrors LastKnownSupporter). False
        /// when signed out / unresolved.</summary>
        internal bool LastKnownDiscordLinked { get; private set; }

        // ---- Account-status cache (entitlement + Discord link): event-driven, not clock-polled ----
        // These change rarely and on discrete events (sign-in, link/unlink, a Patreon pledge lapsing
        // server-side on its monthly date). The client copy is DISPLAY-ONLY (uploads are gated by
        // server-side RLS), so a long backstop is safe. The cache is refreshed on the events that can
        // change it (InvalidateAccountStatusCache below) plus a forced read when the Account/Backup tab
        // opens; the weekly TTL only catches a server-side lapse on a plugin left running for days.
        // Single-flight (`_entInFlight` / `_discordInFlight`) coalesces the badge + cloud-gating reads
        // that used to fire the entitlement RPC twice per account refresh.
        private static readonly TimeSpan AccountStatusTtl = TimeSpan.FromDays(7);
        private readonly object _entCacheLock = new object();
        private (bool isSupporter, string tier, DateTime? retainUntil)? _entCache;
        private DateTime _entCacheAtUtc;
        private Task<(bool, string, DateTime?)> _entInFlight;
        private readonly object _discordCacheLock = new object();
        private (bool linked, string username)? _discordCache;
        private DateTime _discordCacheAtUtc;
        private Task<(bool, string)> _discordInFlight;
        // Identity generation for the two caches above (same idea as _autoPullGen).
        // Bumped by InvalidateAccountStatusCache; a fetch captures it at start and
        // refuses to write its result if the generation moved while the network
        // call was in flight, so an account switch mid-fetch can't seed the NEW
        // account's cache with the OLD account's supporter/Discord status.
        private int _accountStatusGen;

        /// <summary>Drop the cached supporter + Discord-link state so the next read refetches. Called on
        /// sign-in/out, link/unlink, and any action that can change entitlement.</summary>
        internal void InvalidateAccountStatusCache()
        {
            // Bump FIRST so an in-flight fetch that completes after this point sees
            // itself as stale. Also drop the in-flight tasks: without that, a reader
            // under the new identity would JOIN the old identity's pending fetch and
            // receive (and previously cache) the old account's status.
            System.Threading.Interlocked.Increment(ref _accountStatusGen);
            lock (_entCacheLock) { _entCache = null; _entInFlight = null; }
            lock (_discordCacheLock) { _discordCache = null; _discordInFlight = null; }
        }

        /// <summary>Current Discord link state for the settings UI (linked + display name). Cached;
        /// pass forceRefresh on explicit user intent (opening the Account tab, manual refresh).</summary>
        internal Task<(bool linked, string username)> GetDiscordStatusAsync(System.Threading.CancellationToken ct)
            => GetDiscordStatusAsync(ct, forceRefresh: false);

        internal async Task<(bool linked, string username)> GetDiscordStatusAsync(
            System.Threading.CancellationToken ct, bool forceRefresh)
        {
            if (_discordLinkClient == null || _auth == null || !_auth.IsSignedIn)
            {
                LastKnownDiscordLinked = false;
                lock (_discordCacheLock) { _discordCache = null; }
                return (false, null);
            }
            Task<(bool, string)> task;
            lock (_discordCacheLock)
            {
                if (!forceRefresh && _discordCache.HasValue
                    && (DateTime.UtcNow - _discordCacheAtUtc) < AccountStatusTtl)
                {
                    var c = _discordCache.Value;
                    LastKnownDiscordLinked = c.linked;
                    return c;
                }
                if (_discordInFlight == null) _discordInFlight = FetchDiscordStatusAsync();
                task = _discordInFlight;
            }
            var result = await task.ConfigureAwait(false);
            LastKnownDiscordLinked = result.Item1;
            return result;
        }

        private async Task<(bool, string)> FetchDiscordStatusAsync()
        {
            // Bound to the identity generation this fetch started under: if the
            // account switches / signs out during the await, the stale completion
            // must not write the cache or clobber a fresh in-flight fetch the new
            // identity already started. Stale results report signed-out defaults.
            int gen = System.Threading.Volatile.Read(ref _accountStatusGen);
            try
            {
                var result = await _discordLinkClient
                    .GetMyDiscordAsync(System.Threading.CancellationToken.None).ConfigureAwait(false);
                lock (_discordCacheLock)
                {
                    if (gen != System.Threading.Volatile.Read(ref _accountStatusGen))
                        return (false, null);   // identity moved mid-fetch: don't cache
                    _discordCache = result;
                    _discordCacheAtUtc = DateTime.UtcNow;
                    _discordInFlight = null;
                }
                return result;
            }
            catch
            {
                lock (_discordCacheLock)
                {
                    if (gen != System.Threading.Volatile.Read(ref _accountStatusGen))
                        return (false, null);
                    _discordInFlight = null;
                    if (_discordCache.HasValue) return _discordCache.Value;   // keep last good on a transient failure
                }
                return (false, null);
            }
        }

        // ===================== Phase 2 Patreon link =====================
        // Direct Patreon OAuth link: proves an active pledge in-plugin so the supporter badge +
        // cloud backup unlock WITHOUT Discord, and opportunistically fills the Discord link from
        // Patreon. Transport = PatreonLinkClient; the browser/loopback = PatreonOAuthFlow.
        internal struct PatreonLinkResult
        {
            public bool   Ok;
            public string Message;
            public string Name;
        }

        /// <summary>Run the full Patreon link flow: fetch OAuth config, browser consent + loopback
        /// capture, then exchange the code server-side for this signed-in user.</summary>
        internal async Task<PatreonLinkResult> LinkPatreonAsync(System.Threading.CancellationToken ct)
        {
            if (_patreonLinkClient == null) return new PatreonLinkResult { Ok = false, Message = "Patreon linking isn't available." };
            if (_auth == null || !_auth.IsSignedIn) return new PatreonLinkResult { Ok = false, Message = "Sign in to TF4ALL first." };
            if (!await _patreonLinkOp.WaitAsync(0).ConfigureAwait(false))
                return new PatreonLinkResult { Ok = false, Message = "A Patreon link is already in progress." };
            try
            {
                var (cfg, cfgErr) = await _patreonLinkClient.GetConfigAsync(ct).ConfigureAwait(false);
                if (cfg == null || string.IsNullOrEmpty(cfg.ClientId))
                    return new PatreonLinkResult { Ok = false, Message = cfgErr ?? "Patreon linking isn't set up yet." };

                PatreonOAuthFlow.Result auth;
                try
                {
                    auth = await PatreonOAuthFlow.AuthorizeAsync(cfg.ClientId, cfg.RedirectUris, cfg.Scope,
                        msg => SimHub.Logging.Current.Info(msg), ct).ConfigureAwait(false);
                }
                catch (OperationCanceledException) { return new PatreonLinkResult { Ok = false, Message = "Linking cancelled." }; }
                catch (PatreonOAuthException ex)   { return new PatreonLinkResult { Ok = false, Message = ex.Message }; }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Info("[TF4ALL] Patreon authorize error: " + ex.Message);
                    return new PatreonLinkResult { Ok = false, Message = "Couldn't start Patreon linking." };
                }

                var (ok, message, name) = await _patreonLinkClient.ExchangeAsync(auth.Code, auth.RedirectUri, ct).ConfigureAwait(false);
                if (ok) InvalidateAccountStatusCache();   // a Patreon link proves an active pledge: refresh entitlement
                return new PatreonLinkResult { Ok = ok, Message = message, Name = name };
            }
            finally { _patreonLinkOp.Release(); }
        }

        /// <summary>Remove this user's Patreon link.</summary>
        internal async Task<PatreonLinkResult> UnlinkPatreonAsync(System.Threading.CancellationToken ct)
        {
            if (_patreonLinkClient == null) return new PatreonLinkResult { Ok = false, Message = "Patreon linking isn't available." };
            if (_auth == null || !_auth.IsSignedIn) return new PatreonLinkResult { Ok = false, Message = "Sign in first." };
            bool ok = await _patreonLinkClient.UnlinkAsync(ct).ConfigureAwait(false);
            if (ok) InvalidateAccountStatusCache();   // unlink can drop the entitlement: refresh it
            return new PatreonLinkResult { Ok = ok, Message = ok ? "Patreon unlinked." : "Couldn't unlink. Try again." };
        }

        /// <summary>Current Patreon link state for the settings UI (linked + display name).</summary>
        internal async Task<(bool linked, string name)> GetPatreonStatusAsync(System.Threading.CancellationToken ct)
        {
            if (_patreonLinkClient == null || _auth == null || !_auth.IsSignedIn) return (false, null);
            return await _patreonLinkClient.GetMyPatreonAsync(ct).ConfigureAwait(false);
        }

        /// <summary>Read the signed-in user's supporter entitlement for the in-plugin badge.
        /// Advisory/display only; the real backup gate is enforced server-side.</summary>
        /// <summary>Last-known supporter status, cached from GetSupporterTierAsync so
        /// UI (e.g. the MOTD strip) can read it synchronously. Defaults false.</summary>
        internal bool LastKnownSupporter { get; private set; }

        /// <summary>Signed-in user's supporter entitlement for the badge / cloud-gating. Cached
        /// (display-only; real gate is server-side). Pass forceRefresh on explicit user intent.</summary>
        internal Task<(bool isSupporter, string tier, DateTime? retainUntil)> GetSupporterTierAsync(System.Threading.CancellationToken ct)
            => GetSupporterTierAsync(ct, forceRefresh: false);

        internal async Task<(bool isSupporter, string tier, DateTime? retainUntil)> GetSupporterTierAsync(
            System.Threading.CancellationToken ct, bool forceRefresh)
        {
            if (_entitlementClient == null || _auth == null || !_auth.IsSignedIn)
            {
                LastKnownSupporter = false;
                lock (_entCacheLock) { _entCache = null; }
                return (false, null, null);
            }
            Task<(bool, string, DateTime?)> task;
            lock (_entCacheLock)
            {
                if (!forceRefresh && _entCache.HasValue
                    && (DateTime.UtcNow - _entCacheAtUtc) < AccountStatusTtl)
                {
                    var c = _entCache.Value;
                    LastKnownSupporter = c.isSupporter;
                    return c;
                }
                if (_entInFlight == null) _entInFlight = FetchEntitlementAsync();
                task = _entInFlight;
            }
            var result = await task.ConfigureAwait(false);
            LastKnownSupporter = result.Item1;
            return result;
        }

        private async Task<(bool, string, DateTime?)> FetchEntitlementAsync()
        {
            // Same identity-generation binding as FetchDiscordStatusAsync: a stale
            // completion after an account switch must not seed the new account's
            // cache with the old account's entitlement (supporter badge / cloud
            // gating would show the wrong account's status until the TTL expired).
            int gen = System.Threading.Volatile.Read(ref _accountStatusGen);
            try
            {
                var r = await _entitlementClient
                    .GetMyEntitlementAsync(System.Threading.CancellationToken.None).ConfigureAwait(false);
                var result = (r.isSupporter, r.tier, r.retainUntil);
                lock (_entCacheLock)
                {
                    if (gen != System.Threading.Volatile.Read(ref _accountStatusGen))
                        return (false, null, null);   // identity moved mid-fetch: don't cache
                    // supporter_since is stamped once and never cleared, so either
                    // signal means this account has backed the project at some point.
                    // Latched locally so it survives going offline / signing out.
                    if (r.isSupporter || r.supporterSince.HasValue) NoteEverSupported();
                    _entResolvedThisSession = true;
                    _entCache = result;
                    _entCacheAtUtc = DateTime.UtcNow;
                    _entInFlight = null;
                }
                return result;
            }
            catch
            {
                lock (_entCacheLock)
                {
                    if (gen != System.Threading.Volatile.Read(ref _accountStatusGen))
                        return (false, null, null);
                    _entInFlight = null;
                    if (_entCache.HasValue) return _entCache.Value;   // keep last good on a transient failure
                }
                return (false, null, null);
            }
        }

        /// <summary>Community contributions the MOTD strip tracks recency for, so the
        /// matching nudge stays hidden while the user is an active contributor and
        /// returns once they've gone quiet (TrueforceSettings.MotdContributionRecency).</summary>
        internal enum MotdContribution { Share, Vote, CarFact }

        /// <summary>Stamp "the user just contributed" (UTC) so the matching MOTD
        /// community nudge stays suppressed for the recency window. Best-effort persist.</summary>
        internal void NoteMotdContribution(MotdContribution kind)
        {
            if (Settings == null) return;
            var now = DateTime.UtcNow;
            switch (kind)
            {
                case MotdContribution.Share:   Settings.LastSharedPresetOn  = now; break;
                case MotdContribution.Vote:    Settings.LastVotedOn         = now; break;
                case MotdContribution.CarFact: Settings.LastSubmittedFactOn = now; break;
            }
            try { SaveMotdState(); } catch { }
        }

        /// <summary>Read the public supporters roster for the Account tab's wall. Sourced from
        /// Patreon server-side; no sign-in required (the read RPC is public recognition).</summary>
        internal async Task<System.Collections.Generic.List<SupportersClient.SupporterRow>> GetSupportersAsync(System.Threading.CancellationToken ct)
        {
            if (_supportersClient == null) return null;   // not configured -> "couldn't load", not an empty roster
            return await _supportersClient.GetSupportersAsync(ct).ConfigureAwait(false);
        }

        /// <summary>The signed-in user's achievement progress (earned + unearned), account-
        /// based and independent of Discord linking.</summary>
        internal async Task<System.Collections.Generic.List<AchievementClient.AchievementRow>> GetAchievementsAsync(System.Threading.CancellationToken ct)
        {
            if (_achievementClient == null || _auth == null || !_auth.IsSignedIn) return null;
            bool showAll = Settings?.DevShowAllAchievements == true;   // SHOWALL access code
            return await _achievementClient.GetMyAchievementsAsync(ct, showAll).ConfigureAwait(false);
        }

        /// <summary>Immediately reconcile the signed-in user's Discord roles (claim what they
        /// earned). No-op without a Discord link; the Edge Function scopes to this user.</summary>
        internal async Task<(bool ok, int applied)> SyncMyRolesAsync(System.Threading.CancellationToken ct)
        {
            if (_achievementClient == null || _auth == null || !_auth.IsSignedIn) return (false, 0);
            return await _achievementClient.SyncMyRolesAsync(ct).ConfigureAwait(false);
        }

        /// <summary>Dev preview: email a backup-deletion warning stage to the signed-in user.</summary>
        internal async Task<(bool ok, string message)> SendWarnEmailPreviewAsync(int stage, System.Threading.CancellationToken ct)
        {
            if (_achievementClient == null || _auth == null || !_auth.IsSignedIn) return (false, "Sign in first.");
            return await _achievementClient.SendWarnPreviewAsync(stage, ct).ConfigureAwait(false);
        }

        /// <summary>The signed-in user's active auth sessions across devices (this
        /// device flagged IsCurrent). Null when not signed in / unreachable.</summary>
        internal async Task<System.Collections.Generic.List<SessionClient.SessionRow>> AuthGetSessionsAsync(System.Threading.CancellationToken ct)
        {
            if (_sessionClient == null || _auth == null || !_auth.IsSignedIn) return null;
            return await _sessionClient.GetMySessionsAsync(ct).ConfigureAwait(false);
        }

        /// <summary>Revoke one of the signed-in user's other sessions by id. The RPC
        /// refuses to revoke the current device's own session. True when removed.</summary>
        internal async Task<bool> AuthRevokeSessionAsync(string sessionId, System.Threading.CancellationToken ct)
        {
            if (_sessionClient == null || _auth == null || !_auth.IsSignedIn) return false;
            return await _sessionClient.RevokeSessionAsync(sessionId, ct).ConfigureAwait(false);
        }

        /// <summary>Sign out every OTHER device (scope=others), leaving this one signed in.</summary>
        internal async Task<bool> AuthSignOutOtherSessionsAsync()
        {
            if (_auth == null || !_auth.IsSignedIn) return false;
            return await _auth.SignOutOtherSessionsAsync().ConfigureAwait(false);
        }

        // ===================== Phase 2 cloud backup / sync =====================
        // Manual "Back up now" / "Restore from cloud" + debounced auto-sync. Transport
        // is BackupClient; envelope build/merge is BackupService; the apply path mirrors
        // the ImportSettings remount+rebuild plumbing but MERGES settings (preserving
        // this PC's machine-local fields) rather than wholesale-replacing.

        private BackupClient _backupClient;
        // Single-flight: serializes every backup network op (manual + auto) so two
        // upload/apply/stamp cycles never overlap (no concurrent Settings mutation, no
        // stale-revision stamping).
        private readonly System.Threading.SemaphoreSlim _backupOp = new System.Threading.SemaphoreSlim(1, 1);
        // Debounced auto-sync.
        private System.Threading.Timer _autoSyncTimer;
        // Auto-pull poll: applies changes made on another device. _autoPullGen no-ops a tick
        // scheduled under stale state (after sign-out / disable).
        private System.Threading.Timer _autoPullTimer;
        private volatile int _autoPullGen;
        // Revoke heartbeat: polls is_my_session_active so a device whose session was revoked
        // from elsewhere signs ITSELF out within minutes (not after the ~1h JWT exp). Separate
        // from _autoPullTimer because that one is supporter/AutoSync-gated; this runs for ANY
        // signed-in user. _sessionHeartbeatGen no-ops a tick scheduled under stale state;
        // _sessionHeartbeatBusy single-flights overlapping ticks on a slow network.
        private System.Threading.Timer _sessionHeartbeatTimer;
        private volatile int _sessionHeartbeatGen;
        private int _sessionHeartbeatBusy;
        // Bumped on every local change (RequestAutoBackup). A push/merge captures it before its
        // build+upload and clears _backupDirty only if it hasn't moved, so an edit made during the
        // upload window stays pending instead of being silently dropped.
        private volatile int _backupChangeGen;
        // Cheap library-metadata fingerprint from the last backstop check; lets the poll skip the
        // full content re-hash when nothing changed (keeps the check O(metadata), not O(content)).
        private string _lastLibFingerprint;
        private volatile bool _backupDirty;

        // ---- Activity + presence gating (cost control: only touch the backend when it can matter) ----
        // The cloud pull and the revoke heartbeat used to run on flat timers for any signed-in user,
        // which meant a SOLO IDLE user generated ~1800 metadata calls/hour for nothing. Both are now
        // gated so they cost essentially zero unless there's a real reason to talk to the server:
        //   * pull runs only while the user is ACTIVELY using the plugin AND another of this account's
        //     sessions is online (nobody else online => nothing could have changed to pull);
        //   * the revoke heartbeat runs only while 2+ sessions exist (a lone session can't be revoked
        //     by anyone, and revocation is still enforced server-side + caught lazily on the next call).
        // "Active" = a UI interaction within this window (panel load counts). Idle past it => dormant.
        private static readonly TimeSpan ActivityIdleWindow = TimeSpan.FromMinutes(4);
        private long _lastActivityUtcTicks;   // DateTime.UtcNow.Ticks of the last interaction; 0 = never
        // Presence (is another session online?) is refreshed ONLY on wake / Account-tab load, never on a
        // timer, so a one-device user makes at most a handful of get_my_sessions probes a day. A short
        // cache coalesces rapid wakes; a peer counts as online only if its heartbeat is recent (a
        // signed-in-but-closed device stops heartbeating, so its last_seen goes stale and it drops out).
        private static readonly TimeSpan PresenceCacheTtl = TimeSpan.FromMinutes(3);
        private static readonly TimeSpan PeerOnlineWindow = TimeSpan.FromMinutes(5);
        private volatile bool _hasActivePeer;
        private long _presenceCheckedUtcTicks;
        private int _presenceBusy;   // single-flight the get_my_sessions presence probe
        // Adaptive pull cadence: start at 60s while active + a peer is online, but each consecutive
        // "no change" poll stretches the interval (60s -> 5min -> 10min). A peer left running but idle
        // produces nothing but unchanged polls, so the active device winds down to a 10min trickle
        // instead of hammering at 60s forever. Any detected change (or a wake) snaps back to 60s.
        private const int AutoPullBaseMs  = 60000;    // snappy cadence right after a change / wake
        private const int AutoPullMidMs   = 300000;   // 5min once changes have stopped flowing
        private const int AutoPullMaxMs   = 600000;   // 10min steady-state trickle for an idle peer
        private const int AutoPullFloorMs = 10000;    // hard floor: nothing may poll faster than this
        private const int PullMidAfter    = 5;        // no-change polls before stepping to 5min
        private const int PullMaxAfter    = 8;        // no-change polls before stepping to 10min
        private volatile int _pullNoChangeStreak;     // consecutive unchanged polls; drives the backoff

        /// <summary>Fired after a cloud restore/merge re-applies the library to live state, so an
        /// open preset browser redraws without the user hitting Refresh library. Fires on the UI
        /// thread (ApplyRestoredEnvelopeCore is dispatched there).</summary>
        public event Action LibraryReloaded;

        private string UserLibraryFolderForBackup()
            => UserPresets.CurrentFolder ?? UserPresets.DefaultFolder;

        private bool BackupReady => _backupClient != null && _auth != null && _auth.IsSignedIn;

        /// <summary>Manual "Back up now". Fast-forwards (uploads) when the cloud hasn't
        /// changed since this PC last synced; otherwise returns Diverged so the caller
        /// shows the conflict dialog and then calls ResolveBackupConflictAsync.</summary>
        internal async Task<BackupOutcome> BackupNowAsync()
        {
            if (_backupClient == null) return Fail(BackupStatus.NotConfigured, "Backup is not available.");
            if (_auth == null || !_auth.IsSignedIn) return Fail(BackupStatus.NotSignedIn, "Sign in to back up.");
            if (!await _backupOp.WaitAsync(0).ConfigureAwait(false))
                return Fail(BackupStatus.Failed, "A backup is already in progress.");
            try
            {
                var (revResult, cloudRev) = await _backupClient.GetRevisionAsync().ConfigureAwait(false);
                if (revResult == BackupTransfer.NotSignedIn) return Fail(BackupStatus.NotSignedIn, "Sign-in expired; sign in again.");
                if (revResult == BackupTransfer.NotConfigured) return Fail(BackupStatus.NotConfigured, "Backup is not configured.");
                if (revResult != BackupTransfer.Success && revResult != BackupTransfer.NotFound)
                    return FromTransfer(revResult, "Couldn't reach the backup server");

                if (IsDiverged(revResult, cloudRev))
                {
                    // Pull the cloud envelope so the dialog can name its source + time.
                    var (dlResult, json) = await _backupClient.DownloadAsync().ConfigureAwait(false);
                    BackupEnvelope cloudEnv = dlResult == BackupTransfer.Success ? SafeParse(json) : null;
                    return new BackupOutcome
                    {
                        Status = BackupStatus.Diverged,
                        Message = "The cloud backup changed since this PC last synced.",
                        CloudDeviceLabel = cloudEnv?.DeviceLabel,
                        CloudWhenUtc = cloudEnv?.CreatedUtc,
                    };
                }
                return await UploadCurrentAsync().ConfigureAwait(false);
            }
            finally { _backupOp.Release(); }
        }

        // True when the cloud changed since this PC last synced (incl. a never-synced
        // PC that finds an existing cloud backup). NotFound / transient => not diverged.
        private bool IsDiverged(BackupTransfer revResult, string cloudRev)
        {
            if (revResult != BackupTransfer.Success) return false;
            string last = Settings?.BackupLastSyncedRevision ?? "";
            if (string.IsNullOrEmpty(last)) return true;
            return !string.Equals(cloudRev ?? "", last, StringComparison.Ordinal);
        }

        // Build + upload the current setup, then stamp the new revision.
        private async Task<BackupOutcome> UploadCurrentAsync()
        {
            string json;
            try
            {
                json = await Task.Run(() => BackupService.Serialize(
                    BuildEnvelopeLocked())).ConfigureAwait(false);
            }
            catch (BackupTooLargeException ex) { return Fail(BackupStatus.TooLarge, ex.Message); }   // permanent: caller won't retry-spin
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Build backup failed: " + ex.Message); return Fail(BackupStatus.Failed, "Couldn't back up. Check the folder and your connection, then try again."); }

            var up = await _backupClient.UploadAsync(json).ConfigureAwait(false);
            if (up != BackupTransfer.Success) return FromTransfer(up, "Backup upload failed");
            await StampSyncedRevisionAsync().ConfigureAwait(false);
            return new BackupOutcome { Status = BackupStatus.Success, Message = "Backed up to the cloud." };
        }

        // After a successful upload, read back the new object revision + persist it as
        // this PC's last-synced point so the next backup fast-forwards.
        private async Task StampSyncedRevisionAsync()
        {
            try
            {
                var (res, rev) = await _backupClient.GetRevisionAsync().ConfigureAwait(false);
                if (res == BackupTransfer.Success && !string.IsNullOrEmpty(rev) && Settings != null)
                {
                    Settings.BackupLastSyncedRevision = rev;
                    // Capture the now-synced portable settings as the field-merge baseline (local
                    // state == cloud at this point) for the next 3-way auto-pull merge.
                    try
                    {
                        var baseEnv = BackupProjection.Build(Settings, "", DateTime.UtcNow);
                        var libObj = new Newtonsoft.Json.Linq.JObject();
                        foreach (var kv in BackupLibrary.Manifest(UserLibraryFolderForBackup()))
                            libObj[kv.Key] = kv.Value;
                        Settings.BackupLastSyncedEnvelopeJson = new Newtonsoft.Json.Linq.JObject
                        {
                            ["Settings"] = baseEnv.Settings,
                            ["Forza"]    = baseEnv.Forza,
                            ["Lib"]      = libObj,   // path -> content hash, for the 3-way merge + delete-propagation
                        }.ToString(Newtonsoft.Json.Formatting.None);
                    }
                    catch { Settings.BackupLastSyncedEnvelopeJson = ""; }
                    PersistSettingsCore();   // not PersistSettings: must not re-arm auto-sync
                }
                else
                {
                    SimHub.Logging.Current.Info("[TF4ALL] Backup: revision stamp skipped (status=" + res
                        + "); a false 'cloud changed' prompt may appear next time.");
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info("[TF4ALL] Backup: revision stamp failed: " + ex.Message);
            }
        }

        /// <summary>Resolve a detected divergence per the user's choice from the dialog.</summary>
        internal async Task<BackupOutcome> ResolveBackupConflictAsync(BackupConflictChoice choice, bool keepCloudSettings)
        {
            if (choice == BackupConflictChoice.Cancel) return Fail(BackupStatus.Failed, "Cancelled.");
            if (!BackupReady) return Fail(BackupStatus.NotSignedIn, "Sign in to back up.");
            if (!await _backupOp.WaitAsync(0).ConfigureAwait(false))
                return Fail(BackupStatus.Failed, "A backup is already in progress.");
            try
            {
                if (choice == BackupConflictChoice.UseThisPc)
                    return await UploadCurrentAsync().ConfigureAwait(false);   // overwrite cloud with local

                // UseCloud / SmartMerge: re-download the CURRENT cloud before applying, so
                // we never apply a stale envelope (the cloud may have changed again while
                // the dialog was open) and the revision we stamp matches what we applied.
                var (dl, json) = await _backupClient.DownloadAsync().ConfigureAwait(false);
                if (dl == BackupTransfer.NotFound) return await UploadCurrentAsync().ConfigureAwait(false);
                if (dl != BackupTransfer.Success) return FromTransfer(dl, "Couldn't fetch the cloud backup");
                var cloudEnv = SafeParse(json);
                if (cloudEnv == null) return Fail(BackupStatus.Failed, "The cloud backup was unreadable.");

                if (choice == BackupConflictChoice.UseCloud)
                {
                    ApplyRestoredEnvelope(cloudEnv);
                    await StampSyncedRevisionAsync().ConfigureAwait(false);
                    return new BackupOutcome { Status = BackupStatus.Success, Message = "Restored from the cloud and applied." };
                }

                // SmartMerge: union libraries (newest-wins), pick a settings side, then
                // UPLOAD FIRST (the cloud is the shared source of truth) and only mutate
                // this PC once the upload is confirmed (atomic: a failed upload leaves
                // local state untouched and ready to retry).
                var localEnv = await Task.Run(() => BuildEnvelopeLocked()).ConfigureAwait(false);
                var merged = BackupService.Merge(localEnv, cloudEnv, keepCloudSettings, Environment.MachineName, DateTime.UtcNow);
                var up = await _backupClient.UploadAsync(BackupService.Serialize(merged)).ConfigureAwait(false);
                if (up != BackupTransfer.Success) return FromTransfer(up, "Merged backup upload failed");
                ApplyRestoredEnvelope(merged);
                await StampSyncedRevisionAsync().ConfigureAwait(false);
                return new BackupOutcome { Status = BackupStatus.Success, Message = "Merged and backed up." };
            }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Backup conflict resolution failed: " + ex.Message); return Fail(BackupStatus.Failed, "Couldn't resolve the backup conflict. See the SimHub log, then try again."); }
            finally { _backupOp.Release(); }
        }

        /// <summary>Explicit "Restore from cloud" (e.g. a freshly set-up second PC).
        /// Additive: local-only presets survive. Recommends a restart.</summary>
        internal async Task<BackupOutcome> RestoreFromCloudAsync()
        {
            if (_backupClient == null) return Fail(BackupStatus.NotConfigured, "Backup is not available.");
            if (_auth == null || !_auth.IsSignedIn) return Fail(BackupStatus.NotSignedIn, "Sign in to restore.");
            if (!await _backupOp.WaitAsync(0).ConfigureAwait(false))
                return Fail(BackupStatus.Failed, "A backup is already in progress.");
            try
            {
                var (dl, json) = await _backupClient.DownloadAsync().ConfigureAwait(false);
                if (dl == BackupTransfer.NotFound) return new BackupOutcome { Status = BackupStatus.NothingToRestore, Message = "No cloud backup found for this account yet." };
                if (dl != BackupTransfer.Success) return FromTransfer(dl, "Couldn't fetch the cloud backup");
                var env = SafeParse(json);
                if (env == null) return Fail(BackupStatus.Failed, "The cloud backup was unreadable.");
                ApplyRestoredEnvelope(env);
                await StampSyncedRevisionAsync().ConfigureAwait(false);
                return new BackupOutcome { Status = BackupStatus.Success, Message = "Restored from the cloud and applied." };
            }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Restore failed: " + ex.Message); return Fail(BackupStatus.Failed, "Couldn't restore. Check your connection, then try again."); }
            finally { _backupOp.Release(); }
        }

        // ---- Cross-wheel FFB gate (issue: FFB tuning is wheel-specific) ----
        // A restore/sync from a device running a different wheel model withholds
        // the Mode B / grip tuning (BackupProjection's gate). We stash the
        // withheld keys so the settings UI can offer "apply anyway", and expose
        // apply/dismiss for those buttons. PendingCrossWheelFfb non-empty is the
        // signal the UI shows the notice on.

        // Persist the withheld FFB tuning from a cross-wheel-gated restore so the
        // UI can offer "apply anyway" (it is otherwise gone once the envelope is
        // applied). A newer gated restore replaces any older pending FFB.
        private void StashCrossWheelFfbIfGated(BackupApplyResult result)
        {
            if (result == null || !result.FfbGated || Settings == null) return;
            // Never = the user already chose to keep FFB local: withhold silently,
            // no stash, no notice. Only the Ask policy surfaces the prompt.
            // (Always never reaches here: ApplySettings would not have withheld.)
            if (Settings.CrossWheelFfbMode != CrossWheelFfbMode.Ask)
            {
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] FFB tuning from '{result.SourceWheel}' withheld silently (policy Never).");
                return;
            }
            try
            {
                Settings.PendingCrossWheelFfb =
                    result.SkippedFfb?.ToString(Newtonsoft.Json.Formatting.None) ?? "";
                Settings.PendingCrossWheelFfbSource = result.SourceWheel ?? "";
                SimHub.Logging.Current.Info(
                    $"[TF4ALL] FFB tuning from '{result.SourceWheel}' held back on restore "
                    + $"(this PC uses '{Settings.LastUsedWheel}'); offering apply-anyway.");
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info("[TF4ALL] Cross-wheel FFB stash failed: " + ex.GetType().Name);
            }
        }

        /// <summary>True when a cross-wheel-gated restore is holding FFB tuning
        /// the user could still choose to apply. Drives the settings-UI notice.</summary>
        public bool HasPendingCrossWheelFfb =>
            Settings != null && !string.IsNullOrEmpty(Settings.PendingCrossWheelFfb);

        /// <summary>The wheel model the pending FFB tuning was built on (for the
        /// notice text), or null when nothing is pending.</summary>
        public string PendingCrossWheelFfbSource =>
            HasPendingCrossWheelFfb ? Settings.PendingCrossWheelFfbSource : null;

        /// <summary>"Apply anyway": write the FFB tuning a cross-wheel-gated
        /// restore held back onto live settings, push it to the wheel, and clear
        /// the pending state. Only keys still classified FFB-wheel-specific AND
        /// Portable are written, so a stale stash can't smuggle a since-
        /// reclassified field onto live. No-op (returns false) when nothing is
        /// pending or the stash is unreadable. When <paramref name="remember"/>
        /// is set, the policy flips to Always so future cross-wheel FFB applies
        /// without prompting.</summary>
        public bool ApplyPendingCrossWheelFfb(bool remember = false)
        {
            if (Settings == null || string.IsNullOrEmpty(Settings.PendingCrossWheelFfb)) return false;
            try
            {
                var obj = Newtonsoft.Json.Linq.JObject.Parse(Settings.PendingCrossWheelFfb);
                var filtered = new Newtonsoft.Json.Linq.JObject();
                foreach (var prop in obj.Properties())
                    if (BackupProjection.FfbWheelSpecific.Contains(prop.Name)
                        && BackupProjection.Portable.Contains(prop.Name))
                        filtered[prop.Name] = prop.Value;
                using (var reader = filtered.CreateReader())
                    new Newtonsoft.Json.JsonSerializer
                    {
                        ObjectCreationHandling = Newtonsoft.Json.ObjectCreationHandling.Replace,
                    }.Populate(reader, Settings);
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn("[TF4ALL] Apply-anyway FFB failed: " + ex.Message);
                return false;
            }
            Settings.PendingCrossWheelFfb = "";
            Settings.PendingCrossWheelFfbSource = "";
            if (remember) Settings.CrossWheelFfbMode = CrossWheelFfbMode.Always;
            // Push the freshly-written Mode B core tuning AND feel toggles to the
            // live model, then persist (the second call's save also writes the
            // cleared pending fields + any policy change). CarGripCalibration is
            // consumed on the next variant load; no live-push method for it.
            ApplyModeBFromSettings(save: false);
            ApplyModeBFeel(save: true);
            return true;
        }

        /// <summary>"Dismiss": discard the FFB tuning a cross-wheel-gated restore
        /// held back, keeping this PC's own FFB settings. When
        /// <paramref name="remember"/> is set, the policy flips to Never so
        /// future cross-wheel FFB is withheld silently without prompting.</summary>
        public void DismissPendingCrossWheelFfb(bool remember = false)
        {
            if (Settings == null) return;
            Settings.PendingCrossWheelFfb = "";
            Settings.PendingCrossWheelFfbSource = "";
            if (remember) Settings.CrossWheelFfbMode = CrossWheelFfbMode.Never;
            PersistSettings();
        }

        // Apply a restored / merged envelope to live state. Marshalled to the UI thread
        // (matching the existing ImportSettings execution model) so the preset-cache
        // rebuild does not run on a threadpool continuation.
        private void ApplyRestoredEnvelope(BackupEnvelope env, bool propagateDeletes = false)
        {
            if (env == null || Settings == null) return;
            var disp = System.Windows.Application.Current?.Dispatcher;
            if (disp != null && !disp.CheckAccess())
                disp.Invoke(() => ApplyRestoredEnvelopeCore(env, propagateDeletes));
            else
                ApplyRestoredEnvelopeCore(env, propagateDeletes);
        }

        // MERGE portable settings (machine-local fields preserved), re-mount the active
        // user slot, write the preset files, rebuild the runtime library cache, persist,
        // and apply-live what we can. Global FFB/IO + Forza/perf fully take on the
        // recommended restart.
        private void ApplyRestoredEnvelopeCore(BackupEnvelope env, bool propagateDeletes)
        {
            var ffbGate = BackupProjection.ApplySettings(env, Settings);
            StashCrossWheelFfbIfGated(ffbGate);

            // PluginEnabled is Portable and just landed without a SetPluginEnabled
            // transition. Reconcile the device FIRST: everything below does file
            // IO that can throw, and every caller (manual restore, conflict
            // resolution, background auto-sync pull) swallows the exception,
            // which would strand the device on the pre-restore pause state
            // (streaming while "disabled" is the issue #37 doubled haptics;
            // paused while "enabled" is a silently dead wheel).
            SyncDeviceToPluginEnabled("Backup restore");

            // The bundled preset files are always in current (post-migration) format, so
            // flag the one-time migrations done. Mirrors RestoreAllFromZip and prevents a
            // re-run migration from archiving the restored presets.
            Settings.PresetsMigratedV2       = true;
            Settings.CarsMigratedV2          = true;
            Settings.LegacyBuiltinsCleanedV1 = true;
            Settings.FoldersRestructuredV3   = true;
            Settings.CarPresetOrdinalNamesMigratedV1 = true;
            Settings.CarPresetOrdinalNamesMigratedV2 = true;
            Settings.ForzaCarIdsNormalizedV1         = true;

            // ApplySettings replaced the DownloadedCommunityPresets reference; re-link the
            // active slot so the per-user slot system stays consistent.
            try { MountUserSlot(Settings.ActiveSlotKey); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Backup restore: slot remount failed: " + ex.Message); }

            // Auto-sync deletes: remove files that were in the LAST-SYNCED baseline but are absent
            // from this authoritative bundle (deleted on the other PC). Read the OLD baseline now,
            // before StampSyncedRevisionAsync advances it. Manual restore passes propagateDeletes=
            // false (stays additive) so it never wipes a synced file the user might want back.
            System.Collections.Generic.List<string> deleteIfAbsent = null;
            if (propagateDeletes)
            {
                try
                {
                    string bj = Settings?.BackupLastSyncedEnvelopeJson;
                    if (!string.IsNullOrEmpty(bj)
                        && Newtonsoft.Json.Linq.JObject.Parse(bj)["Lib"] is Newtonsoft.Json.Linq.JObject lib)
                        deleteIfAbsent = lib.Properties().Select(p => p.Name).ToList();
                }
                catch { deleteIfAbsent = null; }
            }
            int skipped = BackupLibrary.Restore(UserLibraryFolderForBackup(), env.Library, deleteIfAbsent);
            if (skipped > 0)
                SimHub.Logging.Current.Warn("[TF4ALL] Backup restore: " + skipped + " preset file(s) could not be written.");
            UserPresets.Reload();
            RebuildPresetCacheFromFolders();
            LoadAndMigrateCarPresets();

            PersistSettingsCore();   // restore is a sync point, not a user change: don't re-arm auto-sync
            // Soft "reload": re-apply everything live via the same paths the settings UI uses, so a
            // restore takes full effect without a SimHub restart. ApplyActiveCarOverride covers all
            // effects; ApplyForzaSettings rebuilds the telemetry source in place (port/bind). A full
            // pipeline re-init isn't safe (InitPipeline is once-only: helper process + threads + mixer).
            try { ApplyActiveCarOverride(); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Backup restore: effect re-apply failed: " + ex.Message); }
            try { ApplyForzaSettings(onlyIfChanged: true); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Backup restore: telemetry re-apply failed: " + ex.Message); }
            // Tell any open preset browser to redraw from the rebuilt caches (no manual Refresh).
            try { LibraryReloaded?.Invoke(); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Backup restore: library-reloaded notify failed: " + ex.Message); }
            // A restore rewrites the whole Mode B recipe; push it to the live
            // model or the wheel keeps the pre-restore feel until the user
            // touches a Mode B control (ApplyActiveCarOverride covers the
            // effect sections only).
            try { ApplyModeBFromSettings(); ApplyModeBFeel(); }
            catch (Exception ex) { SimHub.Logging.Current.Warn("[TF4ALL] Backup restore: Mode B re-apply failed: " + ex.Message); }
            // The restored envelope carries DashTabOrder/DashTabsDisabled
            // (Portable); rebuild the dash's slot map so the phone follows
            // the restored layout without a restart.
            RefreshDashTabSlots();
        }

        // ---- Auto-sync (debounced, fast-forward only) ----

        /// <summary>Arm a debounced auto-backup. Called from PersistSettings. No-op
        /// unless the user enabled auto-sync and is signed in. Marks state dirty so a
        /// no-op timer fire (e.g. from the post-upload revision stamp) doesn't upload.</summary>
        public void RequestAutoBackup()
        {
            if (_shuttingDown) return;
            if (Settings == null || !Settings.AutoSyncBackupEnabled) return;
            if (_backupClient == null || _auth == null || !_auth.IsSignedIn) return;
            _backupDirty = true;
            _autoSyncFails = 0;   // a fresh user edit: reset the backoff ladder so it pushes promptly
            unchecked { _backupChangeGen++; }   // marks "a local edit happened" for the in-flight upload guard
            try
            {
                if (_autoSyncTimer == null)
                    _autoSyncTimer = new System.Threading.Timer(_ => RunAutoBackup(), null,
                        System.Threading.Timeout.Infinite, System.Threading.Timeout.Infinite);
                _autoSyncTimer.Change(2000, System.Threading.Timeout.Infinite);   // 2s debounce: still coalesces a slider drag (edits reset the window faster than it expires) but pushes promptly
            }
            catch { /* timer disposed during shutdown */ }
        }

        private void RunAutoBackup()
        {
            Task.Run(async () =>
            {
                if (_shuttingDown || !_backupDirty || Settings == null || !Settings.AutoSyncBackupEnabled) return;
                if (_backupClient == null || _auth == null || !_auth.IsSignedIn) return;
                // Capture the account we started under; bail if the user switches/sign-out across an
                // await so we never upload one account's data to another's cloud.
                string idAtStart = _auth.SignedInUserId ?? "";
                bool StillValid() => !_shuttingDown && _auth != null && _auth.IsSignedIn
                    && Settings != null && Settings.AutoSyncBackupEnabled
                    && string.Equals(_auth.SignedInUserId ?? "", idAtStart, StringComparison.Ordinal);
                if (!await _backupOp.WaitAsync(0).ConfigureAwait(false))
                {
                    // Another backup op (a catch-up pull or a concurrent push) holds the slot.
                    // Re-arm a short retry instead of waiting for the next user edit: a settings-only
                    // change isn't covered by the library drift backstop, so without this it could
                    // sit dirty indefinitely. (This was the "occasionally doesn't sync" race.)
                    ArmAutoSyncRetry(750);
                    return;
                }
                try
                {
                    int changeGen = _backupChangeGen;   // detect a local edit during the build+upload window
                    var (rev, cloudRev) = await _backupClient.GetRevisionAsync().ConfigureAwait(false);
                    if (rev != BackupTransfer.Success && rev != BackupTransfer.NotFound)
                    {
                        ArmAutoSyncBackoff();   // transient revision-read failure: capped exponential backoff
                        return;
                    }
                    if (IsDiverged(rev, cloudRev))
                    {
                        // The OTHER PC moved the cloud. Leave dirty so the next auto-pull tick
                        // reconciles via the merge branch (not a clobbering fast-forward). Re-arm a
                        // backstop retry slightly longer than the pull period so the merge lands
                        // first; if it already cleared dirty, the retry tick is a no-op.
                        SimHub.Logging.Current.Info("[TF4ALL] Auto-sync: cloud changed on another device; the next pull will reconcile.");
                        ArmAutoSyncRetry(2500);
                        return;
                    }
                    if (!StillValid()) return;
                    var outcome = await UploadCurrentAsync().ConfigureAwait(false);
                    // Clear dirty only on success, only if the account is unchanged, and only if no
                    // local edit landed during the upload (else that edit would be silently dropped).
                    if (outcome.Status == BackupStatus.Success && StillValid() && changeGen == _backupChangeGen)
                    {
                        _backupDirty = false;
                        _autoSyncFails = 0;   // clean push: reset the backoff ladder
                    }
                    else if (outcome.Status == BackupStatus.Failed && StillValid())
                        ArmAutoSyncBackoff();   // transient upload failure: capped exponential backoff
                    else if (outcome.Status == BackupStatus.TooLarge)
                        SimHub.Logging.Current.Warn("[TF4ALL] Auto-sync paused: the backup is too large to upload. " + outcome.Message);
                    // Forbidden / NotSignedIn / TooLarge are PERMANENT: leave dirty set but do NOT
                    // re-arm (no spin). The next user edit re-primes a fresh prompt attempt.
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Info("[TF4ALL] Auto-sync error: " + ex.Message);
                    ArmAutoSyncBackoff();   // unexpected error mid-push: capped exponential backoff, don't wait for the next edit
                }
                finally { _backupOp.Release(); }
            });
        }

        /// <summary>Re-arm the debounced auto-backup to retry after a bail (slot contention, a
        /// transient network error, an unexpected exception, or a divergence the pull reconciles
        /// first). Without this, a push that can't complete sits dirty until the next user edit;
        /// a settings-only change (no library file touched) isn't covered by the drift backstop, so
        /// it would never sync on its own. No-op once clean or shutting down.</summary>
        private void ArmAutoSyncRetry(int dueMs)
        {
            if (_shuttingDown || !_backupDirty) return;
            try { _autoSyncTimer?.Change(dueMs, System.Threading.Timeout.Infinite); }
            catch { /* timer disposed during shutdown */ }
        }

        // Consecutive transient push failures, for capped exponential backoff so a sustained
        // outage doesn't re-arm at a flat interval forever. Reset on a clean push and on a new user
        // edit (RequestAutoBackup), so a real edit always gets a prompt 2s attempt.
        private int _autoSyncFails;

        /// <summary>Re-arm a TRANSIENT-failure retry with capped exponential backoff
        /// (4s, 8s, 16s, 32s, 64s, then 120s). Permanent outcomes (Forbidden / NotSignedIn /
        /// TooLarge) must NOT call this. No-op once clean or shutting down.</summary>
        private void ArmAutoSyncBackoff()
        {
            int delay = Math.Min(4000 << Math.Min(_autoSyncFails, 5), 120000);
            _autoSyncFails++;
            ArmAutoSyncRetry(delay);
        }

        // ---- Activity + presence coordinator ----

        /// <summary>True when the user has interacted with the plugin within the activity window.
        /// Drives the backup pull: an idle device has nothing consuming a pulled change, so it
        /// shouldn't poll. Reading is lock-free; the UI stamps it via <see cref="NoteUserActivity"/>.</summary>
        internal bool IsUserActive
        {
            get
            {
                long t = System.Threading.Interlocked.Read(ref _lastActivityUtcTicks);
                if (t == 0) return false;
                return (DateTime.UtcNow - new DateTime(t, DateTimeKind.Utc)) < ActivityIdleWindow;
            }
        }

        /// <summary>UI hook: call on any interaction with the plugin (and on panel load). Stamps
        /// activity; if we had gone idle, this is a WAKE and we reconcile sync state once (refresh
        /// presence, re-arm the heartbeat gate, run the drift backstop, catch up if a peer is online).
        /// Cheap and idempotent: it does no network work unless the idle->active edge is crossed.</summary>
        internal void NoteUserActivity()
        {
            if (_shuttingDown) return;
            long now = DateTime.UtcNow.Ticks;
            long prev = System.Threading.Interlocked.Exchange(ref _lastActivityUtcTicks, now);
            bool wasIdle = prev == 0 || (now - prev) >= ActivityIdleWindow.Ticks;
            if (wasIdle) ReconcileSyncState(ignoreActivity: true);
        }

        /// <summary>Probe whether another of this account's sessions is currently online and cache the
        /// answer. This is the ONLY thing that drives the pull + heartbeat gates, and it runs only on
        /// wake / Account-tab load (never on a timer). Reuses a recent result so rapid wakes don't
        /// re-call get_my_sessions. An unreachable probe keeps the prior belief (doesn't thrash gates).</summary>
        internal async Task RefreshPresenceAsync(bool force)
        {
            if (_shuttingDown || _sessionClient == null || _auth == null || !_auth.IsSignedIn)
            {
                if (_hasActivePeer) { _hasActivePeer = false; try { UpdateSessionHeartbeatTimer(); } catch { } }
                return;
            }
            if (!force)
            {
                long checkedAt = System.Threading.Interlocked.Read(ref _presenceCheckedUtcTicks);
                if (checkedAt != 0 && (DateTime.UtcNow - new DateTime(checkedAt, DateTimeKind.Utc)) < PresenceCacheTtl)
                    return;   // recent enough; reuse the cached _hasActivePeer
            }
            if (System.Threading.Interlocked.CompareExchange(ref _presenceBusy, 1, 0) != 0) return;
            try
            {
                var sessions = await _sessionClient
                    .GetMySessionsAsync(System.Threading.CancellationToken.None).ConfigureAwait(false);
                if (sessions == null) return;   // unreachable / not configured: leave the gate as-is
                ApplySessionsForPresence(sessions);
            }
            catch (Exception ex) { SimHub.Logging.Current.Info("[TF4ALL] Presence probe error: " + ex.Message); }
            finally { System.Threading.Interlocked.Exchange(ref _presenceBusy, 0); }
        }

        /// <summary>Derive "is another session online" from a session list and update the gates. The
        /// Account tab already loads get_my_sessions to show the session list, so it feeds this for
        /// free (opening that tab refreshes presence without an extra call).</summary>
        internal void ApplySessionsForPresence(System.Collections.Generic.List<SessionClient.SessionRow> sessions)
        {
            if (sessions == null) return;
            bool peer = false;
            var now = DateTime.UtcNow;
            foreach (var s in sessions)
            {
                if (s == null || s.IsCurrent) continue;
                DateTime? seen = s.LastSeen ?? s.LastActive ?? s.CreatedAt;
                if (seen.HasValue && (now - seen.Value) < PeerOnlineWindow) { peer = true; break; }
            }
            System.Threading.Interlocked.Exchange(ref _presenceCheckedUtcTicks, now.Ticks);
            if (peer != _hasActivePeer)
            {
                _hasActivePeer = peer;
                try { UpdateSessionHeartbeatTimer(); } catch { }   // start/stop the heartbeat to match
                // A peer just came ONLINE: the pull loop stopped the last time its gate saw
                // no peer (that return doesn't re-arm), and nothing else restarts it until a
                // wake/sign-in reconcile. Without this kick, a peer detected here (e.g. the
                // Account tab feeding this method) got a heartbeat but no pulls, so edits
                // from the other PC never arrived. Reset the backoff so the first polls are
                // snappy, mirroring ReconcileSyncState. The offline flip needs nothing: the
                // loop's next tick sees no peer and stops itself.
                if (peer)
                {
                    _pullNoChangeStreak = 0;
                    try { UpdateAutoPullTimer(); } catch { }
                }
            }
        }

        // Library drift backstop, relocated off the (now gated) pull tick so it still runs for a solo
        // user. Catches a local library mutation that didn't arm the push directly (e.g. files changed
        // by an external tool while the plugin was idle/closed); a real in-app edit already armed it.
        // Cheap: a metadata fingerprint gates the authoritative content-vs-baseline compare.
        private void RunLibraryDriftCheck()
        {
            if (_shuttingDown || Settings == null || !Settings.AutoSyncBackupEnabled) return;
            if (_backupClient == null || _auth == null || !_auth.IsSignedIn) return;
            if (_backupDirty) return;   // already pending: nothing new to detect
            try
            {
                string fp = BackupLibrary.Fingerprint(UserLibraryFolderForBackup());
                if (!string.Equals(fp, _lastLibFingerprint, StringComparison.Ordinal))
                {
                    if (LocalLibraryDiffersFromBaseline()) RequestAutoBackup();
                    _lastLibFingerprint = fp;
                }
            }
            catch { /* fingerprint / compare is best-effort */ }
        }

        /// <summary>One-shot reconcile: run the drift backstop, refresh presence, re-arm the heartbeat
        /// gate, and (if a peer is online) fire an immediate catch-up pull. Called on wake, startup,
        /// and every sign-in/identity flip. <paramref name="ignoreActivity"/> lets the catch-up pull
        /// bypass the activity gate (the user just woke, or this is an explicit startup reconcile),
        /// while the peer gate still applies so a solo device never pulls.</summary>
        private void ReconcileSyncState(bool ignoreActivity)
        {
            if (_shuttingDown) return;
            Task.Run(async () =>
            {
                try
                {
                    try { RunLibraryDriftCheck(); } catch { }
                    await RefreshPresenceAsync(force: true).ConfigureAwait(false);
                    if (_hasActivePeer)
                    {
                        _pullNoChangeStreak = 0;   // wake / sign-in: reset backoff so the catch-up + next polls are snappy
                        RunAutoPull(ignoreActivity);
                    }
                }
                catch (Exception ex) { SimHub.Logging.Current.Info("[TF4ALL] Sync reconcile error: " + ex.Message); }
            });
        }

        // ---- Auto-pull (poll the cloud; fast-forward when local is clean, else silent smart-merge) ----

        /// <summary>Kick the cloud poll loop. Idempotent; call on startup, sign-in/out, and the auto-sync
        /// toggle. The timer is one-shot and re-arms itself from RunAutoPull (adaptive backoff). Each tick
        /// HARD-gates on (user active) AND (a peer is online): when those fail the loop simply stops (no
        /// re-arm) and a wake / sign-in / toggle re-kicks it here, so a solo or idle user makes zero backup
        /// calls. Kicking it regardless of sign-in state avoids a startup race where a session restored
        /// after Init would otherwise never begin polling.</summary>
        public void UpdateAutoPullTimer()
        {
            if (_shuttingDown) return;
            unchecked { _autoPullGen++; }   // invalidate any tick scheduled under the old state
            try
            {
                if (_autoPullTimer == null)
                    _autoPullTimer = new System.Threading.Timer(_ => RunAutoPull(), null,
                        System.Threading.Timeout.Infinite, System.Threading.Timeout.Infinite);
                // The timer is one-shot and re-arms itself from RunAutoPull (adaptive backoff). Kick a
                // base-cadence tick: it self-gates and only keeps the loop alive while active + a peer
                // is online, otherwise the loop stops and a wake / sign-in / toggle re-kicks it here.
                _autoPullTimer.Change(AutoPullBaseMs, System.Threading.Timeout.Infinite);
            }
            catch { /* timer disposed during shutdown */ }
        }

        // Next pull interval from the no-change streak: 60s -> 5min -> 10min as unchanged polls pile up.
        private int NextPullDelayMs()
        {
            int s = _pullNoChangeStreak;
            if (s >= PullMaxAfter) return AutoPullMaxMs;
            if (s >= PullMidAfter) return AutoPullMidMs;
            return AutoPullBaseMs;
        }

        // Re-arm the one-shot pull timer for the next tick (floored). Called from RunAutoPull's tail.
        private void ArmNextAutoPull(int delayMs)
        {
            if (_shuttingDown || _autoPullTimer == null) return;
            try { _autoPullTimer.Change(Math.Max(AutoPullFloorMs, delayMs), System.Threading.Timeout.Infinite); }
            catch { /* timer disposed during shutdown */ }
        }

        // ---- Revoke heartbeat (sign this device out promptly if its session was revoked elsewhere) ----

        /// <summary>Start/stop the session-revoke heartbeat. Idempotent; call on startup, every identity
        /// flip, and whenever presence changes. Gated on 2+ sessions: a lone session can't be revoked by
        /// anyone (the RPC refuses to revoke the caller's own current session), so heartbeating it is
        /// pure waste. When solo, revocation is still enforced server-side and caught lazily on the next
        /// authenticated call / token refresh / Account-tab poke, so this only changes promptness, never
        /// enforcement. Resumes automatically the moment a second session is detected.</summary>
        public void UpdateSessionHeartbeatTimer()
        {
            bool want = !_shuttingDown && _sessionClient != null && _auth != null && _auth.IsSignedIn && _hasActivePeer;
            unchecked { _sessionHeartbeatGen++; }   // invalidate any tick scheduled under stale state
            try
            {
                if (want)
                {
                    if (_sessionHeartbeatTimer == null)
                        _sessionHeartbeatTimer = new System.Threading.Timer(_ => RunSessionHeartbeat(), null,
                            System.Threading.Timeout.Infinite, System.Threading.Timeout.Infinite);
                    _sessionHeartbeatTimer.Change(60000, 180000);   // first check ~60s after sign-in, then every 3 min
                }
                else
                {
                    _sessionHeartbeatTimer?.Change(System.Threading.Timeout.Infinite, System.Threading.Timeout.Infinite);
                }
            }
            catch { /* timer disposed during shutdown */ }
        }

        /// <summary>Fire one heartbeat check right now (e.g. when the Account tab opens) so a
        /// revoke that just happened is noticed without waiting for the next timer tick.</summary>
        internal void PokeSessionHeartbeat() => RunSessionHeartbeat();

        // One heartbeat tick. Asks the server whether THIS device's session still exists; on a
        // DEFINITIVE revoked answer (HTTP 200 + boolean false) it signs the device out locally.
        // Active, and every Unknown (network/unreachable/4xx/5xx/timeout/parse), are ignored, so
        // an outage never signs a healthy device out - mirrors GetAccessTokenAsync's "clear only
        // on a definitive refresh rejection" discipline.
        private void RunSessionHeartbeat()
        {
            int gen = _sessionHeartbeatGen;
            // Single-flight: skip if a previous tick is still in flight (slow network).
            if (System.Threading.Interlocked.CompareExchange(ref _sessionHeartbeatBusy, 1, 0) != 0) return;
            Task.Run(async () =>
            {
                try
                {
                    if (_shuttingDown || _sessionClient == null || _auth == null || !_auth.IsSignedIn) return;
                    // The heartbeat doubles as a device-metadata upsert: it records this
                    // device's name, last-used wheel, and plugin version (so the Account
                    // session list can identify it) while returning the same liveness
                    // tri-state. Identity (session_id/user_id) is server-derived from the
                    // JWT; these args only DESCRIBE this device.
                    string deviceName = Environment.MachineName;
                    string wheel      = Settings?.LastUsedWheel;
                    string version    = CurrentVersionString();
                    SessionStatus status = await _sessionClient
                        .SessionHeartbeatAsync(deviceName, wheel, version, System.Threading.CancellationToken.None)
                        .ConfigureAwait(false);
                    // Re-assert state after the await: a sign-out / account switch / shutdown during
                    // the call makes this result stale, so it must not act.
                    if (gen != _sessionHeartbeatGen || _shuttingDown || _auth == null || !_auth.IsSignedIn) return;
                    if (status != SessionStatus.Revoked) return;   // Active or Unknown: leave the session alone

                    SimHub.Logging.Current.Info("[TF4ALL] Session was revoked from another device; signing this device out.");
                    // Programmatic sign-out: suppress the account-switch tuning prompt
                    // (nobody clicked anything on this PC; a modal over a possible race
                    // would be exactly the surprise class the prompt exists to prevent).
                    // The flag is set on the same thread that fires the identity event.
                    var disp = System.Windows.Application.Current?.Dispatcher;
                    if (disp != null && !disp.CheckAccess())
                        disp.Invoke(() => { try { _suppressNextIdentityPrompt = true; _auth.SignOut(); } catch { } });
                    else
                    {
                        _suppressNextIdentityPrompt = true;
                        _auth.SignOut();
                    }
                }
                catch (Exception ex) { SimHub.Logging.Current.Info("[TF4ALL] Session heartbeat error: " + ex.Message); }
                finally { System.Threading.Interlocked.Exchange(ref _sessionHeartbeatBusy, 0); }
            });
        }

        // One poll tick. Cheap revision check first; only downloads + applies when the cloud
        // actually moved. Defers while a session is live (re-applying effects / rebinding the
        // telemetry source would blip FFB). Single-flights with manual/auto ops via _backupOp.
        // Hard-gated on (a peer is online) so a solo user never pulls, and on (user active) so an
        // idle device doesn't poll either; the wake/startup reconcile passes ignoreActivity to fire
        // a one-shot catch-up without waiting for the next interaction.
        private void RunAutoPull(bool ignoreActivity = false)
        {
            int gen = _autoPullGen;
            Task.Run(async () =>
            {
                if (_shuttingDown || Settings == null || !Settings.AutoSyncBackupEnabled) return;
                if (_backupClient == null || _auth == null || !_auth.IsSignedIn) return;
                if (!_hasActivePeer) return;                                      // solo: nobody else could have written
                if (!ignoreActivity && !IsUserActive) return;                     // idle: nothing is consuming a pulled change
                // Mid-game: don't apply (re-applying effects / rebinding the telemetry source
                // would blip FFB), but DO re-arm. This gate runs before the finally-block
                // re-arm, so a bare return here killed the loop for the rest of the session
                // whenever a tick landed during a race: the user is active with a peer online,
                // yet no wake event fires when the game ends, and changes from the other PC
                // never arrive. Re-arming keeps the current backoff cadence and costs zero
                // network calls per in-game tick (we return before any RPC).
                if (IsGameRunning) { ArmNextAutoPull(NextPullDelayMs()); return; }
                // Capture the account we started under. Re-assert after EVERY await before applying,
                // uploading, or stamping, so a sign-out / account switch during the (up to 90s)
                // download can't apply or upload one account's data under another's identity.
                string idAtStart = _auth.SignedInUserId ?? "";
                bool StillValid() => gen == _autoPullGen && !_shuttingDown
                    && _auth != null && _auth.IsSignedIn && Settings != null && Settings.AutoSyncBackupEnabled
                    && string.Equals(_auth.SignedInUserId ?? "", idAtStart, StringComparison.Ordinal);
                if (!await _backupOp.WaitAsync(0).ConfigureAwait(false)) { ArmNextAutoPull(AutoPullBaseMs); return; }  // contended: retry soon
                bool changed = false;
                try
                {
                    var (rev, cloudRev) = await _backupClient.GetRevisionAsync().ConfigureAwait(false);
                    if (rev != BackupTransfer.Success) return;                    // NotFound (no cloud yet) / transient: nothing to pull
                    string last = Settings?.BackupLastSyncedRevision ?? "";
                    if (string.Equals(cloudRev ?? "", last, StringComparison.Ordinal))
                        return;   // cloud unchanged. (Un-armed local drift is caught by RunLibraryDriftCheck on wake/startup.)
                    if (!StillValid()) return;

                    var (dl, json) = await _backupClient.DownloadAsync().ConfigureAwait(false);
                    if (dl != BackupTransfer.Success || !StillValid()) return;    // account/state may have changed during the download
                    var cloudEnv = SafeParse(json);
                    if (cloudEnv == null) return;

                    if (!_backupDirty)
                    {
                        // Local clean: fast-forward to the cloud (no merge, nothing to lose).
                        // If a local edit landed during the download, bail so the next tick merges
                        // instead of this fast-forward clobbering it.
                        if (!StillValid() || _backupDirty) return;
                        ApplyRestoredEnvelope(cloudEnv, propagateDeletes: true);
                        if (StillValid()) await StampSyncedRevisionAsync().ConfigureAwait(false);
                        SimHub.Logging.Current.Info("[TF4ALL] Auto-sync: pulled a newer backup from your other device.");
                    }
                    else
                    {
                        // Both sides changed: silent field-level 3-way merge. Preset libraries union
                        // newest-wins; the portable settings merge per field against the last-synced
                        // baseline, so each PC's edits to DIFFERENT fields both survive. Upload the
                        // merge first (cloud is the shared truth), then apply locally.
                        int changeGen = _backupChangeGen;   // detect a local edit during build+upload
                        var localEnv = await Task.Run(() => BuildEnvelopeLocked()).ConfigureAwait(false);
                        Newtonsoft.Json.Linq.JObject baseSettings = null, baseForza = null;
                        System.Collections.Generic.Dictionary<string, string> baseLib = null;
                        try
                        {
                            string bj = Settings?.BackupLastSyncedEnvelopeJson;
                            if (!string.IsNullOrEmpty(bj))
                            {
                                var bo = Newtonsoft.Json.Linq.JObject.Parse(bj);
                                baseSettings = bo["Settings"] as Newtonsoft.Json.Linq.JObject;
                                baseForza    = bo["Forza"]    as Newtonsoft.Json.Linq.JObject;
                                if (bo["Lib"] is Newtonsoft.Json.Linq.JObject libBase)
                                {
                                    baseLib = new System.Collections.Generic.Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                                    foreach (var p in libBase.Properties()) baseLib[p.Name] = (string)p.Value;
                                }
                            }
                        }
                        catch { /* missing/bad baseline: the 3-way merge degrades gracefully */ }
                        var merged = BackupService.Merge(localEnv, cloudEnv, baseSettings, baseForza, baseLib, Environment.MachineName, DateTime.UtcNow);
                        // A local edit that lands after the changeGen snapshot makes
                        // `merged` stale. Applying stale content would overwrite the
                        // newer on-disk edit with the pre-edit copy (and the uploaded
                        // cloud copy lacks the edit too, so it would be silently lost
                        // from BOTH sides). Mirror the fast-forward guard: bail before
                        // publishing/applying, leaving _backupDirty set and the
                        // baseline un-stamped, so the next tick re-merges from fresh
                        // disk state and the edit survives and gets pushed.
                        if (changeGen != _backupChangeGen) return;   // edit during build: don't publish a stale merge
                        var up = await _backupClient.UploadAsync(BackupService.Serialize(merged)).ConfigureAwait(false);
                        if (up != BackupTransfer.Success || !StillValid()) return;   // not a supporter / account changed: leave dirty
                        if (changeGen != _backupChangeGen) return;   // edit during upload: same reasoning, don't clobber it locally
                        _backupDirty = false;
                        ApplyRestoredEnvelope(merged, propagateDeletes: true);
                        if (StillValid()) await StampSyncedRevisionAsync().ConfigureAwait(false);
                        SimHub.Logging.Current.Info("[TF4ALL] Auto-sync: merged your changes with your other device.");
                    }
                    changed = true;   // a newer cloud revision was pulled/merged
                }
                catch (Exception ex) { SimHub.Logging.Current.Info("[TF4ALL] Auto-pull error: " + ex.Message); }
                finally
                {
                    _backupOp.Release();
                    // Re-arm the loop with adaptive backoff. A change snaps back to the snappy base
                    // cadence; a run that found nothing (a peer left running idle keeps producing
                    // unchanged polls) stretches the interval 60s -> 5min -> 10min. Only re-arms while a
                    // peer is still believed online; an idle/solo run returns before this and the loop
                    // stops, restarting on the next wake.
                    if (!_shuttingDown && _hasActivePeer)
                    {
                        if (changed) _pullNoChangeStreak = 0; else _pullNoChangeStreak++;
                        ArmNextAutoPull(changed ? AutoPullBaseMs : NextPullDelayMs());
                    }
                }
            });
        }

        // Backstop for the auto-push: true if the on-disk preset library differs from the
        // last-synced baseline. catches a local mutation (delete/rename/duplicate/default change)
        // that didn't arm the push directly, so it still syncs within a poll cycle. Library-only
        // (file content hashes) so settings counters that auto-increment can't false-trigger it.
        private bool LocalLibraryDiffersFromBaseline()
        {
            try
            {
                string bj = Settings?.BackupLastSyncedEnvelopeJson;
                if (string.IsNullOrEmpty(bj)) return false;   // never synced yet: a real change arms normally
                var baseLib = Newtonsoft.Json.Linq.JObject.Parse(bj)["Lib"] as Newtonsoft.Json.Linq.JObject;
                var cur = BackupLibrary.Manifest(UserLibraryFolderForBackup());
                if (cur.Count != (baseLib?.Count ?? 0)) return true;
                if (baseLib != null)
                    foreach (var kv in cur)
                    {
                        var bv = baseLib[kv.Key];
                        if (bv == null || (string)bv != kv.Value) return true;
                    }
                return false;
            }
            catch { return false; }
        }

        // ---- small result helpers ----
        private static BackupOutcome Fail(BackupStatus s, string msg) => new BackupOutcome { Status = s, Message = msg };
        private BackupEnvelope SafeParse(string json)
        {
            try { return BackupService.Parse(json); }
            catch (Exception ex) { SimHub.Logging.Current.Info("[TF4ALL] Backup envelope parse failed: " + ex.Message); return null; }
        }
        private static BackupOutcome FromTransfer(BackupTransfer t, string ctx)
        {
            switch (t)
            {
                case BackupTransfer.NotSignedIn:   return Fail(BackupStatus.NotSignedIn, "Sign-in expired; sign in again.");
                case BackupTransfer.Forbidden:     return Fail(BackupStatus.Forbidden, "Backup is for supporters (coming soon).");
                case BackupTransfer.NotConfigured: return Fail(BackupStatus.NotConfigured, "Backup is not configured.");
                case BackupTransfer.TooLarge:      return Fail(BackupStatus.TooLarge, ctx + ": the backup is too large.");
                case BackupTransfer.NotFound:      return Fail(BackupStatus.NothingToRestore, "No cloud backup found.");
                default:                           return Fail(BackupStatus.Failed, ctx + ".");
            }
        }

        // ---------- capture targeting ----------

        // Curated exe-basename → friendly label map for known sims. AC's
        // "acs" exe is too short for the fuzzy fallback to match safely
        // (collisions with random 3-letter process names), so the curated
        // dict stays the primary lookup. The fuzzy fallback handles unknown
        // games where the exe name resembles the SimHub GameName, and a
        // per-game user override (Settings.AudioCaptureExeOverrides) covers
        // anything neither catches.
        private static readonly Dictionary<string, string> ExeLabels = BuildExeLabels(new Dictionary<string, string[]>
        {
            { "AssettoCorsa",             new[] { "AssettoCorsa", "acs" } },
            { "AssettoCorsaCompetizione", new[] { "AC2-Win64-Shipping", "acc" } },
            { "iRacing",                  new[] { "iRacingSim64DX11", "iRacingSim", "iracing" } },
            { "RaceRoomRacingExperience", new[] { "RRRE64", "RRRE" } },
            { "F1_22",                    new[] { "F1_22", "F1_22_dx12" } },
            { "F1_23",                    new[] { "F1_23", "F1_23_dx12" } },
            { "AutomobilistaII",          new[] { "AMS2", "AMS2AVX" } },
            // Forza Horizon: SimHub's GameName ("FH4"/"FH5"/"FH6") is too short
            // for the >= 4 char fuzzy-match guard, so map the canonical exe
            // names explicitly. FH4/FH5 confirmed; FH6 is an educated guess
            // by Playground's naming pattern and will be corrected once the
            // retail build ships.
            { "FH4",                      new[] { "ForzaHorizon4" } },
            { "FH5",                      new[] { "ForzaHorizon5" } },
            { "FH6",                      new[] { "ForzaHorizon6" } },
            // Forza Motorsport (2023): the exe is nothing like the game name
            // (confirmed live on the Steam build, 2026-07-03), so the fuzzy
            // matcher can never find it. Audio capture reported "no supported
            // game" for FM8 until this entry.
            { "FM8",                      new[] { "forza_gaming.desktop.x64_release_final" } },
            // Farming Simulator: the exe expands the year ("FarmingSimulator
            // 2025Game") while SimHub's GameName abbreviates it
            // ("FarmingSimulator25"), so the fuzzy substring match can never
            // bridge them (owner hit, 2026-08-08; FS25 exe confirmed live,
            // FS22/FS19 follow GIANTS' consistent naming pattern).
            { "FarmingSimulator25",       new[] { "FarmingSimulator2025Game" } },
            { "FarmingSimulator22",       new[] { "FarmingSimulator2022Game" } },
            { "FarmingSimulator19",       new[] { "FarmingSimulator2019Game" } },
        });

        private static Dictionary<string, string> BuildExeLabels(Dictionary<string, string[]> games)
        {
            var d = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (var kv in games)
                foreach (var exe in kv.Value)
                    d[exe] = kv.Key;
            return d;
        }

        // SimHub stores user-added "Custom Game" profiles in CustomGames.json
        // under the SimHub install dir's PluginsData folder. Each entry has
        // Code (the "Custom_<guid>" string SimHub reports as data.GameName),
        // Name (the friendly name the user typed), and ProcessNames
        // (comma-separated exe basenames the user configured for detection).
        // We pull the same data SimHub uses for game detection, the user
        // doesn't have to configure their exe in two places.
        private sealed class CustomGameInfo
        {
            public string Name;
            public string[] ProcessNames;     // basenames (no .exe), case-insensitive lookup
        }
        private Dictionary<string, CustomGameInfo> _customGamesCache;
        private DateTime _customGamesCacheLoadedAt;
        private const int CustomGamesCacheStaleSeconds = 60;

        /// <summary>Resolve a SimHub Custom_xxx GameName to its user-configured
        /// friendly name and exe list. Returns null for non-custom games or
        /// when the entry isn't present. Cached for 60 s; cache is bypassed
        /// when the requested code isn't already cached, so newly-added
        /// custom games are picked up within one capture tick.</summary>
        private CustomGameInfo TryGetCustomGameInfo(string gameCode)
        {
            if (string.IsNullOrEmpty(gameCode)
                || !gameCode.StartsWith("Custom_", StringComparison.OrdinalIgnoreCase))
                return null;

            var now = DateTime.UtcNow;
            bool cacheStale = _customGamesCache == null
                              || (now - _customGamesCacheLoadedAt).TotalSeconds > CustomGamesCacheStaleSeconds;
            bool cacheMissForCode = _customGamesCache != null && !_customGamesCache.ContainsKey(gameCode);
            if (cacheStale || cacheMissForCode) LoadCustomGames();

            return _customGamesCache != null && _customGamesCache.TryGetValue(gameCode, out var info) ? info : null;
        }

        private void LoadCustomGames()
        {
            var newCache = new Dictionary<string, CustomGameInfo>(StringComparer.OrdinalIgnoreCase);
            try
            {
                // Plugin DLL lives in the SimHub install dir, so this resolves
                // wherever SimHub is installed.
                string simHubDir = Path.GetDirectoryName(typeof(TrueforcePlugin).Assembly.Location);
                string path = Path.Combine(simHubDir, "PluginsData", "CustomGames.json");
                if (File.Exists(path))
                {
                    string json = File.ReadAllText(path);
                    var arr = Newtonsoft.Json.Linq.JArray.Parse(json);
                    foreach (var item in arr)
                    {
                        string code = item["Code"]?.ToString();
                        if (string.IsNullOrEmpty(code)) continue;
                        string name = item["Name"]?.ToString()?.Trim();
                        if (string.IsNullOrEmpty(name)) name = code;
                        string procStr = item["ProcessNames"]?.ToString() ?? "";
                        var procs = new List<string>();
                        foreach (var raw in procStr.Split(','))
                        {
                            string p = raw.Trim();
                            if (p.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                                p = p.Substring(0, p.Length - 4);
                            if (!string.IsNullOrEmpty(p)) procs.Add(p);
                        }
                        newCache[code] = new CustomGameInfo
                        {
                            Name = name,
                            ProcessNames = procs.ToArray(),
                        };
                    }
                }
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info($"[TF4ALL] Could not read CustomGames.json: {ex.Message}");
            }
            _customGamesCache = newCache;
            _customGamesCacheLoadedAt = DateTime.UtcNow;
        }

        /// <summary>True if <paramref name="procName"/> looks like a sensible
        /// match for SimHub's <paramref name="gameName"/>. Compares after
        /// stripping non-alphanumeric chars (so "NASCAR 25" matches "NASCAR25"
        /// and "Nascar25-Win64-Shipping"), case-insensitive, with substring
        /// containment in either direction. Empty inputs never match.</summary>
        private static bool ProcessMatchesGameName(string procName, string gameName)
        {
            string normProc = NormalizeForMatch(procName);
            string normGame = NormalizeForMatch(gameName);
            // Require at least 4 chars on the shorter side so generic 1-3
            // letter names ("F1") don't pull in wildcards across the system.
            int min = Math.Min(normProc.Length, normGame.Length);
            if (min < 4) return false;
            return normProc.IndexOf(normGame, StringComparison.OrdinalIgnoreCase) >= 0
                || normGame.IndexOf(normProc, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string NormalizeForMatch(string s)
        {
            if (string.IsNullOrEmpty(s)) return string.Empty;
            var sb = new System.Text.StringBuilder(s.Length);
            foreach (char c in s)
                if (char.IsLetterOrDigit(c)) sb.Append(c);
            return sb.ToString();
        }

        // ---- pause-vs-quit disambiguation via the real process table ----
        // SimHub detects games from their telemetry stream, so the instant a
        // title goes quiet SimHub reports it as "not running". Forza Horizon
        // stops its Data Out the moment you open the pause menu, which made the
        // plugin announce "no game running" while the user was simply paused.
        // To tell a genuine quit from a pause we look for the actual game
        // process. The scan walks the whole process table, far too heavy for
        // the ~60 Hz settings tick that reads this, so the result is cached for
        // a couple of seconds. Only ever read from the UI thread (status pill +
        // wheel-quiet diagnostic), so no lock is needed.
        private string _gameProcCachedLabel;
        private long   _gameProcCachedAtTicks;
        private static readonly long GameProcRescanTicks = Stopwatch.Frequency * 2;  // 2 s

        /// <summary>True when a known racing-game process is alive right now,
        /// whether or not it's currently emitting telemetry. Lets callers tell
        /// "paused / in a menu" (process up, telemetry quiet) apart from "game
        /// closed" (process gone), instead of trusting SimHub's telemetry-based
        /// detection, which drops out the instant a Forza pause stops the Data
        /// Out feed. <paramref name="label"/> is the matched game's friendly
        /// name, or null when nothing matched. Only ever returns true for a game
        /// SimHub named earlier this session (the only thing a pause can be
        /// "paused from"), which also keeps an idle SimHub from walking the
        /// process table forever. Result cached ~2 s.</summary>
        public bool IsKnownGameProcessRunning(out string label)
        {
            label = null;
            // Nothing was ever detected this session: there's no paused game to
            // rescue, so skip the process walk entirely.
            if (string.IsNullOrEmpty(_lastNamedGame)) return false;

            long now = Stopwatch.GetTimestamp();
            if (_gameProcCachedAtTicks != 0 && now - _gameProcCachedAtTicks < GameProcRescanTicks)
            {
                label = _gameProcCachedLabel;
                return label != null;
            }
            _gameProcCachedLabel   = ScanForGameProcess();
            _gameProcCachedAtTicks = now;
            label = _gameProcCachedLabel;
            return label != null;
        }

        // Walk the process table once for a known game exe. Match priority
        // mirrors the audio-capture scan: the curated exe map first, then a
        // fuzzy match against the last game SimHub named (so an unmapped title
        // whose exe resembles its name still rescues across a pause). Every
        // Process handle is disposed; only the friendly label is returned.
        private string ScanForGameProcess()
        {
            string fuzzyTarget = _lastNamedGame;
            Process[] all;
            try { all = Process.GetProcesses(); }
            catch { return null; }

            string found = null;
            foreach (var p in all)
            {
                if (found == null)
                {
                    string pn = null;
                    try { pn = p.ProcessName; } catch { /* exited mid-walk */ }
                    if (!string.IsNullOrEmpty(pn))
                    {
                        if (ExeLabels.TryGetValue(pn, out string lbl))
                            found = lbl;
                        else if (!string.IsNullOrEmpty(fuzzyTarget)
                                 && ProcessMatchesGameName(pn, fuzzyTarget))
                            found = fuzzyTarget;
                    }
                }
                try { p.Dispose(); } catch { }
            }
            return found;
        }

        // The Process handle for the game we're currently capturing (or null).
        // We hold this so per-tick alive-checks use HasExited (cheap, uses the
        // existing handle) instead of re-walking the process table.
        private Process _capturedProcess;

        private void CapturePollLoop()
        {
            // Initial settle delay so plugin Init can finish on the SimHub side
            // before we start hammering the process table.
            Thread.Sleep(500);
            while (!_shuttingDown)
            {
                CaptureTick();
                // 1 Hz polling. Sleep in small slices so shutdown is responsive.
                for (int i = 0; i < 10 && !_shuttingDown; i++)
                    Thread.Sleep(100);
            }
        }

        private void CaptureTick()
        {
            if (_shuttingDown || _audio == null) return;

            try
            {
                // Fast path: if we already have a captured process, just check
                // whether it's still alive. No process-table scan.
                if (_capturedProcess != null)
                {
                    bool stillAlive = false;
                    try { stillAlive = !_capturedProcess.HasExited; } catch { /* invalid handle */ }
                    if (stillAlive) return;

                    // Process exited, tear down and fall through to the scan.
                    SimHub.Logging.Current.Info($"[TF4ALL] Captured process {_capturedProcess.Id} exited; releasing.");
                    try { _capturedProcess.Dispose(); } catch { }
                    _capturedProcess = null;
                    _audio.Stop();
                    _helperHost?.SetTargetPid(0);
                    ExitStreamingGcMode();
                    MaybeAutoDumpFfbTraceOnGameExit();
                }

                // Scan path: walk the process table once. Match priority:
                //   1. Per-game user override (Settings.AudioCaptureExeOverrides)
                //     , highest priority so users can fix any miss.
                //   2. Curated exe→label dict (known-quirky exes like ACC's
                //      "AC2-Win64-Shipping" or AC's short "acs").
                //   3. SimHub Custom-game ProcessNames (read from
                //      CustomGames.json, same source SimHub uses for game
                //      detection, so the user only configures their exe once).
                //   4. Fuzzy match against the active GameName (or the
                //      Custom-game friendly Name) so non-custom games whose
                //      exe naturally resembles their SimHub name auto-resolve.
                // Disposes every Process we don't keep so handles aren't leaked.
                Process keep = null;
                string label = null;
                string activeGame = _activeGame;   // snapshot for thread safety
                string overrideExe = null;
                if (Settings?.AudioCaptureExeOverrides != null
                    && !string.IsNullOrEmpty(activeGame)
                    && Settings.AudioCaptureExeOverrides.TryGetValue(activeGame, out var ovr))
                    overrideExe = ovr;
                CustomGameInfo customInfo = TryGetCustomGameInfo(activeGame);
                HashSet<string> customProcs = null;
                if (customInfo?.ProcessNames != null && customInfo.ProcessNames.Length > 0)
                    customProcs = new HashSet<string>(customInfo.ProcessNames, StringComparer.OrdinalIgnoreCase);
                string fuzzyTarget = !string.IsNullOrEmpty(customInfo?.Name) ? customInfo.Name : activeGame;
                string overrideLabel = customInfo?.Name ?? activeGame;

                Process[] all;
                try { all = Process.GetProcesses(); }
                catch { all = Array.Empty<Process>(); }

                foreach (var p in all)
                {
                    if (keep != null) { p.Dispose(); continue; }
                    if (overrideExe != null
                        && p.ProcessName.Equals(overrideExe, StringComparison.OrdinalIgnoreCase))
                    {
                        keep = p;
                        label = overrideLabel;
                        continue;
                    }
                    if (ExeLabels.TryGetValue(p.ProcessName, out string lbl))
                    {
                        keep = p;
                        label = lbl;
                        continue;
                    }
                    if (customProcs != null && customProcs.Contains(p.ProcessName))
                    {
                        keep = p;
                        label = customInfo.Name;
                        continue;
                    }
                    if (!string.IsNullOrEmpty(fuzzyTarget)
                        && ProcessMatchesGameName(p.ProcessName, fuzzyTarget))
                    {
                        keep = p;
                        label = fuzzyTarget;
                        continue;
                    }
                    p.Dispose();
                }

                if (keep == null)
                {
                    _captureStatus = "Idle (no supported game running)";
                    return;
                }

                // The snapshot above can be older than the process it matched:
                // on game exit the poll re-captured the freshly dead PID 23 ms
                // after releasing it (FS close log, 2026-08-08), re-entering
                // streaming GC mode and re-arming game state for a corpse.
                bool keepExited = false;
                try { keepExited = keep.HasExited; } catch { keepExited = true; }
                if (keepExited)
                {
                    try { keep.Dispose(); } catch { }
                    _captureStatus = "Idle (no supported game running)";
                    return;
                }

                _capturedProcess = keep;
                _audio.Start(keep.Id);
                _helperHost?.SetTargetPid(keep.Id);
                EnterStreamingGcMode();
                _captureStatus = $"Capturing {label} (PID {keep.Id})";
                SimHub.Logging.Current.Info($"[TF4ALL] {_captureStatus}.");
            }
            catch (Exception ex)
            {
                _captureStatus = $"Capture error: {ex.Message}";
                SimHub.Logging.Current.Error("[TF4ALL] Capture retarget failed", ex);
            }
        }
        // ---------- producer ----------

        // The sidechain ducking (tier ladder + airborne fold) and the silence
        // floor moved to the Engine assembly in phase 0c (DuckingController,
        // EngineLoop.SilenceFloor) so the replay harness runs the exact
        // production code. Their rationale comments live there. The producer
        // loop below forwards its per-tick work into EngineLoop.RunOneTick.

        /// <summary>Adapts the live device field to the engine's sample sink.
        /// Reads _device per push so replug/watchdog swaps and the null (device
        /// gone) case behave exactly as the old inline PushFloats call.</summary>
        private sealed class DeviceSink : ISampleSink
        {
            private readonly TrueforcePlugin _p;
            public DeviceSink(TrueforcePlugin p) { _p = p; }
            public void Push(float[] samples, int count) => _p._device?.PushFloats(samples, count);
        }

        private void ProducerLoop()
        {
            // Put the synthesis thread in the MMCSS "Pro Audio" band at NORMAL
            // priority (just below the 1 kHz pump's HIGH), so it is no longer
            // the one render-stage thread left outside real-time scheduling.
            // It feeds the device ring, so when it gets preempted the ring
            // underruns and the auto-ratchet inflates latency; this keeps it
            // scheduled promptly under game/GC load. Reverted when the thread
            // exits (and best-effort: a no-op if MMCSS is unavailable).
            using (TrueforceForAll.Core.MmcssScope.Enter(
                       "Pro Audio", TrueforceForAll.Core.MmcssScope.PriorityNormal))
                ProducerLoopCore();
        }

        private void ProducerLoopCore()
        {
            float[] buf = new float[BatchSamples];

            while (!_shuttingDown)
            {
                // Master disable: skip rendering entirely. The wheel was told
                // to Stop by SetPluginEnabled (live toggle) or by
                // SyncDeviceToPluginEnabled (bring-up with the toggle already
                // off, restore/import/account switch; issue #37), so it's
                // running on native FFB.
                // Sleep ~the duration of one batch (4 samples × 0.25 ms) before
                // re-checking, to avoid a hot spin.
                if (Settings != null && !Settings.PluginEnabled)
                {
                    Thread.Sleep(20);
                    continue;
                }

                // No device right now (not yet attached, or torn down while
                // the recovery watchdog re-attaches). Rendering would just be
                // discarded by the null PushFloats below, so idle instead of
                // hot-spinning the CPU for the seconds/minutes the wheel may
                // be gone. The watchdog flips _device back and we resume.
                if (_device == null)
                {
                    Thread.Sleep(20);
                    continue;
                }

                // Engine loop not built yet: Init starts this thread inside
                // device bring-up, BEFORE InitPipeline constructs _engineLoop
                // (tens of ms later, after the orphan sweep and helper spawn).
                // Without this gate the first tick NREs into the silent
                // shutdown catch below and the wheel is dead for the session
                // while the device happily streams keepalives.
                var loop = _engineLoop;
                if (loop == null)
                {
                    Thread.Sleep(20);
                    continue;
                }

                // Auto-ratchet check (cheap when the per-second window hasn't
                // elapsed). Fires the ring-bumped event on this thread; UI
                // marshals to its own thread for the modal.
                try { CheckAutoRatchet(); } catch { }

                // One engine tick: ducking, 500 Hz effect tick on resampled
                // frames, render, silence floor, push. Render/ducking/effect
                // exceptions are contained inside RunOneTick (logged via the
                // rate-limited callback, batch cleared to silence); only sink
                // exceptions reach here, and a dead device is the shutdown
                // signal, exactly as the old inline PushFloats catch. The
                // ducking depth folds in the ui-tabs master enable: off means
                // depth 0, continuous effects never dipped, tuning preserved
                // (the airborne stage has its own opt-ins inside).
                try
                {
                    // Keep the ducker's audio ref current: the capture source
                    // is created after Init and can be retargeted live.
                    _ducking.Audio = _audio;
                    // Live toggle: UseBandArbiter is volatile, written here on
                    // the producer thread, read on the engine thread.
                    _ducking.UseBandArbiter = Settings?.DuckFrequencyAware ?? false;
                    loop.RunOneTick(buf, Stopwatch.GetTimestamp(),
                        (Settings?.DuckingEnabled ?? true) ? (Settings?.DuckDepth ?? 0.5f) : 0f,
                        Settings?.DuckAttackMs  ?? 5.0f,
                        Settings?.DuckReleaseMs ?? 80.0f,
                        ex => LogProducerError("render", ex));
                }
                catch
                {
                    break;
                }

                // Signal-scope tap for the dash's Scope screen: buf still
                // holds this tick's rendered samples after RunOneTick has
                // pushed them. Own catch so a scope bug can never be
                // mistaken for the dead-device shutdown signal above.
                try { DashScopeTick(buf, BatchSamples); } catch { }

                // Bank earned seat time for the one-and-done word-of-mouth
                // prompt. Cheap: one Stopwatch read + a gate; only writes the
                // settings file once every StreamFlushIntervalSeconds.
                try { AccumulateStreamingTime(); } catch { }
            }
        }

        // Producer-loop error rate limiter: log at most one render exception
        // per 5 seconds so a sustained bad-frame source doesn't spam the log
        // and stall the producer on I/O.
        private long _lastProducerErrTicks;
        private void LogProducerError(string phase, Exception ex)
        {
            long now = System.Diagnostics.Stopwatch.GetTimestamp();
            long sinceTicks = now - _lastProducerErrTicks;
            if (_lastProducerErrTicks != 0 && sinceTicks < System.Diagnostics.Stopwatch.Frequency * 5)
                return;
            _lastProducerErrTicks = now;
            try
            {
                SimHub.Logging.Current.Error(
                    $"[TF4ALL] producer {phase} error (rate-limited 1/5s): {ex.GetType().Name}: {ex.Message}");
            }
            catch { }
        }

        // Polled from DataUpdate's hot path. Detects a missing / faulted
        // device and re-attaches it transparently. Inline cost is just the
        // gating checks; the blocking bring-up (HID open + ~136 ms init
        // sequence + tap spawn) is offloaded to the thread pool so SimHub's
        // tick never stalls. Single-flight via _recoveryInProgress.
        private void MaybeRecoverDevice()
        {
            if (_shuttingDown || System.Threading.Volatile.Read(ref _recoveryInProgress) != 0) return;

            var d = _device;
            bool needsRecovery = d == null || d.StreamFaulted;
            if (!needsRecovery) return;

            // G HUB holds the wheel's HID exclusively; opening would just
            // fail. Skip while it's running; the first tick after the user
            // closes G HUB clears this gate and recovery proceeds, so the
            // wheel comes back with no plugin reload.
            if (_isGHubRunning) return;

            long now = Stopwatch.GetTimestamp();
            if (_lastRecoveryAttemptTicks != 0
                && now - _lastRecoveryAttemptTicks < RecoveryIntervalTicks)
                return;
            _lastRecoveryAttemptTicks = now;
            // Atomically claim the single-flight slot; if the UI-thread probe
            // already holds it, bail so the two can't both run a bring-up.
            if (System.Threading.Interlocked.CompareExchange(ref _recoveryInProgress, 1, 0) != 0) return;

            System.Threading.ThreadPool.QueueUserWorkItem(_ =>
            {
                try
                {
                    // Dispose the faulted device + its FFB tap (null-safe if
                    // there was no device yet). The plugin-lifetime producer
                    // thread is intentionally left running; it idles while
                    // _device is null and resumes the instant it's back.
                    CleanupDevice();
                    if (_shuttingDown) return;
                    bool ok = TryBringUpDevice();
                    SimHub.Logging.Current.Info(ok
                        ? "[TF4ALL] Wheel re-attached; stream resumed."
                        : "[TF4ALL] Wheel re-attach failed; will keep retrying.");

                    // EXPERIMENTAL: retry the driver-LED channel open if it
                    // failed during Init (typical when the wheel wasn't
                    // enumerable yet). Only runs when the driver intercept is
                    // on AND its control channel opened; otherwise skipped.
                    if (ok && _driverChannel != null && _driverLedChannel == null
                        && Settings != null && Settings.ExperimentalDriverIntercept)
                    {
                        try
                        {
                            var ch = new WheelLedChannel(m => SimHub.Logging.Current.Info(m));
                            if (ch.OpenAndResolve())
                            {
                                _driverLedChannel = ch;
                                SimHub.Logging.Current.Info("[TF4ALL] driver-LED channel opened on wheel re-attach.");
                            }
                            else
                            {
                                ch.Dispose();
                            }
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Warn($"[TF4ALL] driver-LED retry threw: {ex.GetType().Name}: {ex.Message}");
                        }
                    }
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Error("[TF4ALL] Wheel re-attach crashed", ex);
                }
                finally
                {
                    System.Threading.Interlocked.Exchange(ref _recoveryInProgress, 0);
                }
            });
        }

        /// <summary>True when the FFB tap has decoded a game FFB target off
        /// the USB bus within <paramref name="maxAgeMs"/>. Proves the tap is
        /// genuinely mirroring the game's force feedback, not merely
        /// "started", which is what the Diagnostics self-test needs to tell a
        /// live pass-through from a tap that attached but is seeing nothing.
        /// Returns false (not an error) when no FFB-producing game is running;
        /// the caller phrases that case accordingly.</summary>
        public bool FfbTapTargetFresh(int maxAgeMs)
        {
            var tap = _ffbTap;
            return tap != null && tap.TryGetFreshFfbTarget(maxAgeMs).HasValue;
        }

        /// <summary>Active staged device probe for the Diagnostics self-test.
        /// Non-destructive when the device is already healthy (returns a note,
        /// does NOT reopen a working wheel). When the stream is down/faulted
        /// it runs a real bring-up, discovery, then open + init + tap +
        /// stream via TryBringUpDevice, and reports each stage's outcome
        /// using the now-accurate status strings (open/init failures surface
        /// with their exception text via StreamStatus). Blocking (~150 ms for
        /// the init sequence); callers invoke it off the UI thread. Shares
        /// the _recoveryInProgress single-flight with the watchdog so the two
        /// can't run a bring-up at the same time.</summary>
        public string RunActiveDeviceProbe()
        {
            var d = _device;
            if (d != null && !d.StreamFaulted)
                return "Device already healthy: active probe skipped (it never "
                     + "reopens a working wheel). Status lines above are live.";

            if (_isGHubRunning)
                return "Cannot probe: Logitech G HUB is running and holds the "
                     + "wheel's HID. Close G HUB, then run the self-test again.";

            // Atomically claim the single-flight slot shared with the watchdog;
            // if it's already held, don't start a second bring-up.
            if (System.Threading.Interlocked.CompareExchange(ref _recoveryInProgress, 1, 0) != 0)
                return "A re-attach is already in progress. Wait a moment and "
                     + "run the self-test again.";

            _lastRecoveryAttemptTicks = Stopwatch.GetTimestamp();
            var sb = new System.Text.StringBuilder();
            try
            {
                var matches = WheelDiscovery.FindAll();
                if (matches.Count == 0)
                {
                    sb.AppendLine("[FAIL] Discovery: no supported wheel on the bus.");
                    sb.Append("        Plug in a G PRO / RS50 / G923 and close G HUB.");
                    return sb.ToString();
                }
                sb.AppendLine($"[OK]   Discovery: {WheelDiscovery.DisplayModel(matches[0])} "
                    + $"(VID 0x{matches[0].Vid:X4}, PID 0x{matches[0].Pid:X4})");

                CleanupDevice();
                if (_shuttingDown) return "Aborted (plugin shutting down).";

                bool ok = TryBringUpDevice();
                sb.AppendLine((ok ? "[OK]   " : "[FAIL] ")
                    + "Open + init sequence + stream: "
                    + (StreamStatus ?? "(unknown)"));
                sb.AppendLine("       Wheel:  " + (WheelStatus ?? "(unknown)"));
                sb.Append("       FFB tap: " + (FfbTapStatus ?? "(not started)"));
                return sb.ToString();
            }
            catch (Exception ex)
            {
                return sb + "\n[FAIL] Probe crashed: " + ex.Message;
            }
            finally
            {
                System.Threading.Interlocked.Exchange(ref _recoveryInProgress, 0);
            }
        }

        private void CleanupDevice()
        {
            // _fsPipeSource is deliberately NOT disposed here: this method
            // runs on every wheel recovery cycle, and the FS source's
            // lifecycle is the GAME session, not the device (unlike the tap
            // and the steering reader below, which device init recreates).
            // Disposing it here killed the pipe server on the first wheel
            // hiccup and, with _fsPipeSource null, also disabled the SimHub
            // fallback evaluator (hit live, 2026-08-07). It is torn down on
            // leaving FS (SwapTelemetrySourceLocked) and at plugin End.
            try { _ffbTap?.Dispose(); } catch { }
            _ffbTap = null;
            try { _steeringReader?.Dispose(); } catch { }
            _steeringReader = null;
            try { _device?.Dispose(); } catch { }
            _device = null;
        }

        // Persist the user-picked USBPcap path and restart the FFB tap with
        // the new probe. Returns true if the tap is now running. Called from
        // the settings panel's Browse action. The caller has already
        // validated the path; we don't re-validate here.
        public bool ApplyUsbPcapPathOverride(string usbPcapCmdPath)
        {
            if (Settings == null) return false;
            Settings.UsbPcapCmdPathOverride = usbPcapCmdPath ?? "";
            try { PersistSettingsCore(); } catch { }
            return RestartFfbTap();
        }

        // Resolve the FFB-tap interface+address override in precedence order:
        // env var (debug/testing) > persisted manual picker (Settings) > auto.
        // Returns (null, 0) when neither override is set, which the tap reads
        // as "auto-discover".
        private (string iface, int dev) ResolveUsbPcapOverride()
        {
            string ifaceEnv = Environment.GetEnvironmentVariable("SIMHUBTF_USBPCAP_INTERFACE");
            if (!string.IsNullOrEmpty(ifaceEnv)
                && int.TryParse(Environment.GetEnvironmentVariable("SIMHUBTF_USBPCAP_DEVICE"), out var devEnv)
                && devEnv > 0)
            {
                return (ifaceEnv, devEnv);
            }
            if (Settings != null
                && !string.IsNullOrEmpty(Settings.ManualUsbPcapInterface)
                && Settings.ManualUsbPcapDeviceAddress > 0)
            {
                return (Settings.ManualUsbPcapInterface, Settings.ManualUsbPcapDeviceAddress);
            }
            return (null, 0);
        }

        // Persist the user-picked USB device address + USBPcap interface from
        // the manual picker dialog and restart the FFB tap to apply it. Empty
        // iface OR zero address clears the override (= back to auto-discover).
        // Called from SettingsControl's "Pick device manually" dialog.
        public bool ApplyManualUsbPcapDevice(string iface, int deviceAddress, ushort vid = 0, ushort pid = 0)
        {
            if (Settings == null) return false;
            Settings.ManualUsbPcapInterface     = iface ?? "";
            Settings.ManualUsbPcapDeviceAddress = deviceAddress > 0 ? deviceAddress : 0;
            // Remember the pinned device's identity so the tap can follow THIS
            // device to a new address after a replug, never switching wheels.
            Settings.ManualUsbPcapVid           = deviceAddress > 0 ? vid : 0;
            Settings.ManualUsbPcapPid           = deviceAddress > 0 ? pid : 0;
            try { PersistSettingsCore(); } catch { }
            SimHub.Logging.Current.Info(
                $"[TF4ALL] Manual USB device {(deviceAddress > 0 ? $"set to {iface} dev {deviceAddress}" : "cleared")}.");
            return RestartFfbTap();
        }

        // Wire the FFB tap's self-heal callbacks. Shared by both tap-creation
        // sites so they stay consistent.
        // Dev/test (NOFFB access code): makes the tap see the wheel and the
        // game's FFB on the wire but never extract it, so the no-FFB self-heal
        // (-A retry, then the warning) can be exercised on a working wheel.
        private bool _simulateNoFfb;
        public bool DebugToggleSimulateNoFfb()
        {
            _simulateNoFfb = !_simulateNoFfb;
            if (_ffbTap != null) _ffbTap.SimulateNoFfbCapture = _simulateNoFfb;
            if (!_simulateNoFfb) _noFfbCaptureNotice = null;
            SimHub.Logging.Current.Info($"[TF4ALL] Simulate-no-FFB-capture {(_simulateNoFfb ? "ON" : "OFF")}.");
            return _simulateNoFfb;
        }

        // Opt-in experimental FFB-capture path, shared by the Diagnostics
        // checkbox and the FFBX access code. Persists Settings.ExperimentalFfbCapture,
        // applies it to the live tap, and re-arms the feature-index resolver so
        // the change takes effect without a SimHub restart. Off = shipped behaviour.
        public void SetExperimentalFfbCapture(bool on)
        {
            if (Settings != null) Settings.ExperimentalFfbCapture = on;
            PersistSettings();
            // The tap gets the EFFECTIVE value: inside Farming Simulator the
            // widened rules stay on regardless of the global toggle.
            ApplyEffectiveExperimentalCapture();
            SimHub.Logging.Current.Info($"[TF4ALL] Experimental FFB capture {(on ? "ON" : "OFF")}.");
        }

        // Effective experimental capture: currently just the user's global
        // opt-in. An FS-forces-it-on clause lived here for one build and was
        // reverted the same evening: the owner's G PRO trace (2026-08-07)
        // proved FS sends only a CONSTANT heartbeat on the 0x12 path
        // (12 ff 0e 2d 01 86 00, byte-identical for 3676 packets), so
        // extraction there can only ever decode garbage (it read the
        // constant as a hard-left force). FS force feedback is owned by
        // spring mode instead, which replaces the target wholesale.
        private bool EffectiveExperimentalCapture()
        {
            return Settings?.ExperimentalFfbCapture ?? false;
        }

        private void ApplyEffectiveExperimentalCapture()
        {
            var tap = _ffbTap;
            if (tap == null) return;
            bool want = EffectiveExperimentalCapture();
            if (tap.ExperimentalCapture == want) return;
            tap.ExperimentalCapture = want;
            tap.ResetFeatureIndexResolution();
            if (want && !(Settings?.ExperimentalFfbCapture ?? false))
                SimHub.Logging.Current.Info(
                    "[TF4ALL] Experimental FFB detection enabled automatically for Farming Simulator " +
                    "(its wheel FFB rides the report-0x12 path); the global setting is unchanged.");
        }

        public bool DebugToggleExperimentalCapture()
        {
            bool on = !(Settings?.ExperimentalFfbCapture ?? false);
            SetExperimentalFfbCapture(on);
            return on;
        }

        // ---------- Tap-free AC FFB (ACFFB access code) ----------

        // Persists Settings.AcShmFfbEnabled and applies it to the live AC
        // source immediately (the latch is otherwise armed at source
        // construction on the next game swap). Turning it off also drops any
        // latched force so the provider can't consume a final stale value.
        public void SetAcShmFfb(bool on)
        {
            if (Settings != null) Settings.AcShmFfbEnabled = on;
            PersistSettings();
            var src = _telemetrySource as AcSharedMemoryTelemetrySource;
            if (src != null)
            {
                src.FfbLatchEnabled = on;
                if (!on) src.ClearLastFfbTarget();
            }
            SimHub.Logging.Current.Info($"[TF4ALL] AC shared-memory FFB {(on ? "ON" : "OFF")}.");
        }

        public bool DebugToggleAcShmFfb()
        {
            bool on = !(Settings?.AcShmFfbEnabled ?? false);
            SetAcShmFfb(on);
            return on;
        }

        // True while the tap-free AC path is armed AND recently delivering,
        // used to keep the tap's no-FFB escalation quiet (it gates a warning,
        // not the force itself, hence the more lenient window than the
        // provider's 250 ms so momentary gaps don't flap the watchdog).
        private bool AcShmFfbSupplying()
        {
            if (!(Settings?.AcShmFfbEnabled ?? false)) return false;
            return (_telemetrySource as AcSharedMemoryTelemetrySource)
                ?.TryGetFreshFfbTarget(1000).HasValue ?? false;
        }

        // ---------- Issue #13: stop the Trueforce stream while paused (test toggle) ----------

        // True while we have stopped the stream for a pause, so we only fire
        // SendStopCommand / SendStartCommand on the pause/resume edges.
        private bool _stopStreamPauseActive;
        // A real pause stops telemetry for far longer than this; the threshold
        // only has to clear normal inter-frame jitter (Forza runs 60-160 Hz).
        private const double StopStreamPauseStaleMs = 250.0;
        // Telemetry must read active continuously for this long before we restart
        // the stream, so a quick-travel / teleport flap can't re-engage us.
        private const long ResumeHoldMs = 300;
        private long _resumeCandidateSinceTicks;   // 0 = no resume pending

        // Drive the device in/out of Trueforce mode on pause edges when the
        // StopStreamOnPause toggle is on. Stopping the stream (vs streaming a
        // zero force) is what lets the wheel revert to its native FFB and the
        // game's own auto-center, which is the only thing confirmed to stop the
        // G923/FH6 full-lock (issue #13). Called every DataUpdate so it keeps
        // ticking even when telemetry has stopped. Default-off: when the toggle
        // is off this is a no-op and the existing return-zero pause-release
        // (the FfbTargetProvider lambda) stays in charge.
        private void UpdateStopStreamOnPauseGate()
        {
            // A late SimHub tick landing inside End()'s teardown window must
            // not command the device: the stop direction would send Stop+Pause
            // as the last wire traffic (exiting Trueforce mode off-center =
            // firmware autocenter snap, and silencing the End() center-drain),
            // and the resume direction would spuriously re-enter Trueforce
            // mode on a dying stream (2026-08-08 review). End() owns the
            // device from here on.
            if (_shuttingDown) return;

            // We may only actively hold the stream stopped while the toggle is
            // on AND we have a live game/source to judge pause state against.
            // In every other case (toggle off, plugin disabled, no device, no
            // active game, no source) we must NOT leave the stream stopped: if
            // we previously stopped it for a pause, resume now so the device is
            // never stranded paused. A stranded pause silently kills both the
            // Test buttons and in-game FFB until the toggle is flipped, because
            // the early-return below used to skip the resume once the game
            // closed (a pause nulls _activeGame). Only resume when the plugin
            // is still meant to be driving the wheel.
            var src = _telemetrySource;
            // Mode B exemption: leaving Trueforce mode on pause exists so the
            // GAME's native FFB can own menus (issue #13, Horizon). In Mode B
            // there is no game FFB — releasing the wheel hands it to the
            // firmware autocenter, which rings violently against nothing
            // (fourth wheel test: menu spazz). Keep streaming instead: the
            // pause-release in the FFB provider already returns zero force on
            // raceOn=0, and while we stream the wheel ignores every other
            // force source, so menus are free AND silent.
            //
            // Farming Simulator is exempt BY GAME NAME, not by armed mode:
            // spring mode arms with a game-name dwell several seconds after
            // the source attaches, and on a SimHub start with FS already
            // running this gate fired inside that window (02:08:43 in the
            // 2026-08-08 start-pull log) — the wheel got enter/leave/enter
            // Trueforce churn in seven seconds, and each hand-back lets the
            // firmware autocenter snap an off-center wheel. FS has no native
            // FFB worth reverting to (our model replaces it outright), so
            // the gate must never fire there.
            bool canGate = Settings != null && Settings.StopStreamOnPause
                           && Settings.PluginEnabled && _device != null
                           && src != null && !string.IsNullOrEmpty(_activeGame)
                           && _forceMode == ForceModeOff
                           && !_activeGame.StartsWith("FarmingSimulator", StringComparison.Ordinal);
            if (!canGate)
            {
                if (_stopStreamPauseActive)
                {
                    lock (_enableDeviceLock)
                    {
                        if (Settings != null && Settings.PluginEnabled && _device != null)
                        {
                            _ffbTap?.ClearLastFfbTarget();
                            _device.BeginResumeRamp();
                            _device.Resume();
                            _device.SendStartCommand();
                        }
                        _stopStreamPauseActive = false;
                    }
                }
                _resumeCandidateSinceTicks = 0;
                return;
            }

            // Paused = the game's own session flag is down (authoritative, or the
            // physics proxy with no telemetry), OR telemetry has actually stopped
            // flowing. The staleness arm is what catches FH6 fast-travel /
            // teleport / race-start, where Forza halts UDP so IsRaceOn freezes at
            // 1 and IsSessionActive never reports the pause on its own.
            bool paused = (!src.IsSessionActive && (src.HasAuthoritativeSessionState || src.MeasuredHz <= 0))
                          || src.MsSinceLastFrame > StopStreamPauseStaleMs;

            if (paused)
            {
                _resumeCandidateSinceTicks = 0;   // cancel any pending resume
                if (!_stopStreamPauseActive)
                {
                    // Commands + flag under the enable lock, so the reconciler
                    // can never observe "paused but gate flag not yet set" and
                    // resume a stream this gate is deliberately holding out of
                    // Trueforce mode (issue #13 exposure).
                    lock (_enableDeviceLock)
                    {
                        _device.SendStopCommand();
                        _device.Pause();
                        _stopStreamPauseActive = true;
                    }
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] StopStreamOnPause: paused, left Trueforce mode so the wheel reverts to native FFB.");
                }
                // Keep the held force cleared the WHOLE time we're stopped, not
                // just at the pause instant: the tap keeps capturing while paused,
                // so turning the wheel against the game's auto-center would
                // otherwise land a strong counter-force in the tap that replays
                // on the next restart and slams the wheel (issue #13).
                _ffbTap?.ClearLastFfbTarget();
                return;
            }

            // Not paused. If we never stopped, nothing to do.
            if (!_stopStreamPauseActive) { _resumeCandidateSinceTicks = 0; return; }

            // Stopped + telemetry back: wait out the hysteresis so a one-frame
            // flap mid-transition can't restart us, and stay cleared until we do.
            long now = System.Diagnostics.Stopwatch.GetTimestamp();
            if (_resumeCandidateSinceTicks == 0) _resumeCandidateSinceTicks = now;
            long heldMs = (now - _resumeCandidateSinceTicks) * 1000L / System.Diagnostics.Stopwatch.Frequency;
            if (heldMs < ResumeHoldMs)
            {
                _ffbTap?.ClearLastFfbTarget();
                return;
            }

            // Restart from a clean slate: discard anything the tap grabbed during
            // the pause / transition so the first force we emit is the game's
            // current FFB, not a stale captured snapshot.
            _ffbTap?.ClearLastFfbTarget();
            bool resumed = false;
            lock (_enableDeviceLock)
            {
                // Re-read the master toggle inside the lock: a disable (live
                // toggle, or a restore/import reconcile) landing after canGate
                // was computed must not be overwritten by this resume, or the
                // keepalive pump would run while "disabled" (the issue #37
                // shape). Skipping still clears the gate flag: the disable owns
                // the paused device now, and re-enabling goes through
                // SetPluginEnabled's own Resume.
                if (Settings != null && Settings.PluginEnabled && _device != null)
                {
                    _device.BeginResumeRamp();
                    _device.Resume();
                    _device.SendStartCommand();
                    resumed = true;
                }
                _stopStreamPauseActive = false;
            }
            _resumeCandidateSinceTicks = 0;
            if (resumed)
                SimHub.Logging.Current.Info(
                    "[TF4ALL] StopStreamOnPause: resumed, restarted Trueforce stream.");
        }

        // NOLOCK access code / future UI. Persists Settings.StopStreamOnPause.
        // When turning it off mid-pause, the gate resumes the stream on its next
        // tick so we never strand the wheel with no stream.
        public void SetStopStreamOnPause(bool on)
        {
            if (Settings != null) Settings.StopStreamOnPause = on;
            PersistSettings();
            SimHub.Logging.Current.Info($"[TF4ALL] StopStreamOnPause {(on ? "ON" : "OFF")}.");
        }

        public bool DebugToggleStopStreamOnPause()
        {
            bool on = !(Settings?.StopStreamOnPause ?? false);
            SetStopStreamOnPause(on);
            return on;
        }

        // SUPPORT TOOL (IRRAW access code). Born as a throwaway bring-up spike
        // whose three questions below ARE answered (the direct reader exists
        // because of the answers); PROMOTED to a keeper on 2026-08-14, owner's
        // call, because shipping the reflection-based iRacing path to a fleet
        // of unknown SimHub builds gave it a second job the delete-me note
        // never anticipated: when a user's iRacing integration misbehaves,
        // "type IRRAW and send the log" dumps what THEIR SimHub actually
        // exposes (property names, dictionary contents, freshness counters)
        // with no debugger and no repro on our side. The original questions
        // stay below because their methodology is the documentation.
        //
        // Q1 Does StatusDataBase.GetRawDataObject() hand a third-party plugin a
        //    live, per-tick-populated iRacing object (expected runtime type
        //    IRacingReader.DataSampleEx, with a .Telemetry of type
        //    iRacingSDK.Telemetry)?
        // Q2 Does SteeringWheelTorque carry non-zero values while iRacing's own
        //    in-sim force feedback is DISABLED?
        // Q3 Is the 360 Hz sub-tick array SteeringWheelTorque_ST reachable?
        //    iRacingSDK.Telemetry derives from Dictionary of string to object,
        //    but _ST is not among its typed properties, so the only way in is
        //    the dictionary.
        //
        // No hard assembly reference is taken on iRacingSDK.dll or
        // ICarsReader.dll: SimHub can rename or drop either at any time and a
        // compile-time reference would take the whole plugin down with it.
        // Everything here is name-based reflection plus one cast to the BCL
        // interface IDictionary of string to object, which the SDK's Telemetry
        // type inherits from its Dictionary base and which costs us nothing.
        // Every path is wrapped so a missing member logs a line instead of
        // throwing into SimHub's data pump.
        //
        // Rate: one full dump on arming, then one line every 5 s. Disarmed the
        // per-tick cost is a single volatile bool read; armed it is one int
        // increment. Nothing allocates or logs on a normal tick.
        private volatile bool _irRawProbeArmed;
        private bool _irRawProbeFullPending;
        private long _irRawProbeNextTicks;
        private int  _irRawProbeSamples;
        // SimHub DataUpdate ticks since arming. Printed alongside the sim's own
        // SessionTime so Q1 is answerable from the log: if SessionTime advances
        // about 5.0 while this advances about 300, the object is repopulated
        // every tick. A frozen SessionTime against a climbing tick count means
        // the raw object is stale.
        private int  _irRawProbeHostTicks;
        private const double IrRawProbePeriodSec = 5.0;
        // Surface state is watched EVERY tick, not on the 5 s cadence: a kerb
        // strike lasts a fraction of a second, so a periodic sample would miss
        // every one of them. Logging on CHANGE is what maps the enum values.
        private string _irRawLastSurface;

        /// <summary>IRRAW access code: arm/disarm the throwaway iRacing raw
        /// telemetry probe. Returns the new armed state. Not persisted.</summary>
        public bool DebugToggleIracingRawProbe()
        {
            _irRawProbeArmed = !_irRawProbeArmed;
            _irRawProbeFullPending = _irRawProbeArmed;
            _irRawProbeNextTicks   = 0;
            _irRawProbeSamples     = 0;
            _irRawProbeHostTicks   = 0;
            SimHub.Logging.Current.Info(
                "[TF4ALL] IRRAW iRacing raw-telemetry probe "
                + (_irRawProbeArmed ? "ARMED. Get on track, then toggle iRacing's own force feedback off and on." : "OFF."));
            return _irRawProbeArmed;
        }

        // Called from DataUpdate on every SimHub tick.
        private void IrRawProbeTick(GameData data)
        {
            // Cheapest possible early-out, and the shipped state.
            if (!_irRawProbeArmed) return;
            _irRawProbeHostTicks++;

            // Surface watch runs on EVERY tick, ahead of the periodic gate. Drive
            // over a kerb, a gravel trap and the grass: each transition logs one
            // line, and those lines are the enum mapping we need for curb thump.
            try
            {
                var ndS = data != null ? data.NewData : null;
                if (ndS != null && data.GameRunning == true)
                {
                    object rawS = ndS.GetRawDataObject();
                    if (rawS != null)
                    {
                        object telS = rawS;
                        var tp = rawS.GetType().GetProperty("Telemetry",
                            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
                        if (tp != null && tp.CanRead && tp.GetIndexParameters().Length == 0)
                        {
                            object t2 = tp.GetValue(rawS, null);
                            if (t2 != null) telS = t2;
                        }
                        var dS = telS as IDictionary<string, object>;
                        string surf = "mat=" + IrRawRead(telS, dS, "PlayerTrackSurfaceMaterial")
                                    + " surf=" + IrRawRead(telS, dS, "PlayerTrackSurface");
                        if (!string.Equals(surf, _irRawLastSurface, StringComparison.Ordinal))
                        {
                            _irRawLastSurface = surf;
                            SimHub.Logging.Current.Info(
                                "[TF4ALL] IRRAW surface CHANGE " + surf
                                + " speed=" + IrRawRead(telS, dS, "Speed")
                                + " hostTicks=" + _irRawProbeHostTicks.ToString(System.Globalization.CultureInfo.InvariantCulture));
                        }
                    }
                }
            }
            catch { /* throwaway probe, never disturb the data pump */ }

            bool full = _irRawProbeFullPending;
            long now  = Stopwatch.GetTimestamp();
            if (!full && now < _irRawProbeNextTicks) return;
            _irRawProbeNextTicks = now + (long)(Stopwatch.Frequency * IrRawProbePeriodSec);
            _irRawProbeFullPending = false;

            try
            {
                var nd = data != null ? data.NewData : null;
                if (data == null || data.GameRunning != true || nd == null)
                {
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] IRRAW no running game or no NewData this tick (hostTicks="
                        + _irRawProbeHostTicks.ToString(System.Globalization.CultureInfo.InvariantCulture) + ").");
                    // Re-arm the full dump so the first real in-car tick still
                    // produces one.
                    _irRawProbeFullPending = full;
                    return;
                }

                object raw = null;
                string rawErr = null;
                try { raw = nd.GetRawDataObject(); }
                catch (Exception ex) { rawErr = ex.GetType().Name + ": " + ex.Message; }

                if (raw == null)
                {
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] IRRAW Q1=NO game=" + (data.GameName ?? "?")
                        + " GetRawDataObject() returned null"
                        + (rawErr != null ? " and threw " + rawErr : " with no exception")
                        + ". Q2 and Q3 cannot be answered from this path.");
                    return;
                }

                var rawType = raw.GetType();

                // The SDK's per-tick telemetry lives on a .Telemetry property of
                // the raw sample. Resolved by NAME so a renamed assembly still
                // works; if there is no such property we fall back to treating
                // the raw object itself as the telemetry surface.
                object tel = raw;
                string telSource = "raw object itself (no .Telemetry property)";
                try
                {
                    var telProp = rawType.GetProperty("Telemetry",
                        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
                    if (telProp != null && telProp.CanRead && telProp.GetIndexParameters().Length == 0)
                    {
                        object t = telProp.GetValue(raw, null);
                        if (t != null) { tel = t; telSource = "raw.Telemetry"; }
                        else telSource = "raw.Telemetry was null";
                    }
                }
                catch (Exception ex) { telSource = "raw.Telemetry threw " + ex.GetType().Name; }

                var telType = tel.GetType();

                // Q3's route in. iRacingSDK.Telemetry derives from
                // Dictionary of string to object, and that base type lives in
                // mscorlib, so this cast reaches the raw variable bag without
                // referencing the SDK at all.
                var dict = tel as IDictionary<string, object>;

                string stDesc;
                if (dict == null)
                {
                    stDesc = "UNREACHABLE (telemetry object is not IDictionary<string,object>)";
                }
                else
                {
                    object stVal = null;
                    bool   stFound = false;
                    string stErr = null;
                    try { stFound = dict.TryGetValue("SteeringWheelTorque_ST", out stVal); }
                    catch (Exception ex) { stErr = ex.GetType().Name + ": " + ex.Message; }
                    if (stErr != null)      stDesc = "THREW " + stErr;
                    else if (!stFound)      stDesc = "key absent";
                    else                    stDesc = IrRawDescribeSubTick(stVal);
                }

                if (full)
                {
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] IRRAW arming dump: game=" + (data.GameName ?? "?")
                        + " rawType=" + rawType.FullName
                        + " rawAsm=" + rawType.Assembly.GetName().Name
                        + " telFrom=" + telSource
                        + " telType=" + telType.FullName
                        + " telAsm=" + telType.Assembly.GetName().Name
                        + " telBase=" + (telType.BaseType != null ? telType.BaseType.FullName : "null")
                        + " isIDictionary=" + (dict != null ? "True" : "False")
                        + " dictCount=" + (dict != null
                            ? dict.Count.ToString(System.Globalization.CultureInfo.InvariantCulture) : "n/a")
                        + " typedPropsInclInherited=" + telType.GetProperties(
                            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance).Length
                            .ToString(System.Globalization.CultureInfo.InvariantCulture) + ".");
                    try
                    {
                        SimHub.Logging.Current.Info("[TF4ALL] IRRAW rawAsmPath=" + rawType.Assembly.Location);
                    }
                    catch { }

                    IrRawDumpSessionInfo(raw);

                    if (dict != null)
                    {
                        var stKeys    = new List<string>();
                        var steerKeys = new List<string>();
                        try
                        {
                            foreach (var k in dict.Keys)
                            {
                                if (string.IsNullOrEmpty(k)) continue;
                                if (k.EndsWith("_ST", StringComparison.Ordinal)) stKeys.Add(k);
                                if (k.IndexOf("Steer", StringComparison.OrdinalIgnoreCase) >= 0
                                    || k.IndexOf("FFB", StringComparison.OrdinalIgnoreCase) >= 0
                                    || k.IndexOf("Torque", StringComparison.OrdinalIgnoreCase) >= 0)
                                    steerKeys.Add(k);
                            }
                            stKeys.Sort(StringComparer.Ordinal);
                            steerKeys.Sort(StringComparer.Ordinal);
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Info(
                                "[TF4ALL] IRRAW key enumeration threw " + ex.GetType().Name + ": " + ex.Message);
                        }
                        SimHub.Logging.Current.Info("[TF4ALL] IRRAW keys ending in _ST ("
                            + stKeys.Count.ToString(System.Globalization.CultureInfo.InvariantCulture) + "): "
                            + (stKeys.Count > 0 ? string.Join(", ", stKeys.ToArray()) : "NONE"));
                        SimHub.Logging.Current.Info("[TF4ALL] IRRAW steering/FFB/torque keys ("
                            + steerKeys.Count.ToString(System.Globalization.CultureInfo.InvariantCulture) + "): "
                            + (steerKeys.Count > 0 ? string.Join(", ", steerKeys.ToArray()) : "NONE"));

                        // FULL key list, once. The earlier probe only printed two
                        // filtered subsets, which is why questions like "is there
                        // an LFE channel" stayed open. Dump everything and settle
                        // what iRacing does and does not publish, permanently.
                        try
                        {
                            var allKeys = new List<string>();
                            foreach (var k in dict.Keys)
                                if (!string.IsNullOrEmpty(k)) allKeys.Add(k);
                            allKeys.Sort(StringComparer.Ordinal);
                            SimHub.Logging.Current.Info("[TF4ALL] IRRAW ALL KEYS ("
                                + allKeys.Count.ToString(System.Globalization.CultureInfo.InvariantCulture) + "):");
                            const int PerLine = 12;
                            for (int i = 0; i < allKeys.Count; i += PerLine)
                            {
                                int n = Math.Min(PerLine, allKeys.Count - i);
                                SimHub.Logging.Current.Info("[TF4ALL] IRRAW keys["
                                    + i.ToString(System.Globalization.CultureInfo.InvariantCulture) + "] "
                                    + string.Join(", ", allKeys.GetRange(i, n).ToArray()));
                            }
                        }
                        catch (Exception ex)
                        {
                            SimHub.Logging.Current.Info(
                                "[TF4ALL] IRRAW full key dump threw " + ex.GetType().Name + ": " + ex.Message);
                        }
                    }
                }

                // Q2 verdict on the line itself, so the log reads without
                // arithmetic. Steering angle is printed too: a zero torque
                // reading only means something if the wheel was being turned.
                double torque;
                bool haveTorque = IrRawTryDouble(tel, dict, "SteeringWheelTorque", out torque);
                string q2 = !haveTorque ? "UNREADABLE"
                          : (torque > 0.01 || torque < -0.01) ? "NONZERO" : "zero";

                _irRawProbeSamples++;
                SimHub.Logging.Current.Info(
                    "[TF4ALL] IRRAW #" + _irRawProbeSamples.ToString(System.Globalization.CultureInfo.InvariantCulture)
                    + " hostTicks=" + _irRawProbeHostTicks.ToString(System.Globalization.CultureInfo.InvariantCulture)
                    + " | Q1 rawType=" + rawType.FullName
                    + " SessionTime=" + IrRawRead(tel, dict, "SessionTime")
                    + " SessionTick=" + IrRawRead(tel, dict, "SessionTick")
                    + " Speed="       + IrRawRead(tel, dict, "Speed")
                    + " | Q2=" + q2
                    + " SteeringFFBEnabled="       + IrRawRead(tel, dict, "SteeringFFBEnabled")
                    + " SteeringWheelTorque="      + IrRawRead(tel, dict, "SteeringWheelTorque")
                    + " SteeringWheelPctTorque="   + IrRawRead(tel, dict, "SteeringWheelPctTorque")
                    + " SteeringWheelPeakForceNm=" + IrRawRead(tel, dict, "SteeringWheelPeakForceNm")
                    + " SteeringWheelAngle="       + IrRawRead(tel, dict, "SteeringWheelAngle")
                    + " SteeringWheelAngleMax="    + IrRawRead(tel, dict, "SteeringWheelAngleMax")
                    + " SteeringWheelMaxForceNm="  + IrRawRead(tel, dict, "SteeringWheelMaxForceNm")
                    + " | surface mat="            + IrRawRead(tel, dict, "PlayerTrackSurfaceMaterial")
                    + " surf="                     + IrRawRead(tel, dict, "PlayerTrackSurface")
                    + " | shockVelLF="             + IrRawRead(tel, dict, "LFshockVel")
                    // Scale for these is unconfirmed. Log them so the [0,1]
                    // normalization can be tuned from real values rather than
                    // guessed at a second time.
                    + " rumblePitchLF="            + IrRawRead(tel, dict, "TireLF_RumblePitch")
                    + " rumblePitchRF="            + IrRawRead(tel, dict, "TireRF_RumblePitch")
                    + " absActive="                + IrRawRead(tel, dict, "BrakeABSactive")
                    // UNIT SETTLER. TelemetryFrame documents m/s^2, but
                    // SimHubTelemetrySource passes StatusDataBase's values
                    // through unconverted. Printing both side by side answers
                    // whether SimHub reports G (ratio ~9.8) or m/s^2 (ratio ~1),
                    // which decides whether every SimHub-fallback game has been
                    // feeding the effects a signal an order of magnitude small.
                    + " | UNITS simhubHeave=" + IrRawNum(nd.AccelerationHeave)
                    + " sdkVertAccel="        + IrRawRead(tel, dict, "VertAccel")
                    + " simhubSway="          + IrRawNum(nd.AccelerationSway)
                    + " sdkLatAccel="         + IrRawRead(tel, dict, "LatAccel")
                    + " | Q3 SteeringWheelTorque_ST=" + stDesc + ".");
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Warn(
                    "[TF4ALL] IRRAW probe error: " + ex.GetType().Name + ": " + ex.Message);
            }
        }

        // Look one named telemetry value up with no compile-time knowledge of
        // the SDK: the generated typed property first (there are a couple of
        // hundred of them), then the dictionary key, which is the only route to
        // anything the generator skipped. src reports which route answered, or
        // why neither did.
        private static bool IrRawValue(object tel, IDictionary<string, object> dict,
                                       string name, out object value, out string src)
        {
            value = null;
            src   = "absent";
            if (tel != null)
            {
                try
                {
                    var p = tel.GetType().GetProperty(name,
                        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
                    if (p != null && p.CanRead && p.GetIndexParameters().Length == 0)
                    {
                        value = p.GetValue(tel, null);
                        src   = "prop";
                        return true;
                    }
                }
                catch (Exception ex) { src = "prop-threw:" + ex.GetType().Name; }
            }
            if (dict != null)
            {
                try
                {
                    object v;
                    if (dict.TryGetValue(name, out v)) { value = v; src = "dict"; return true; }
                }
                catch (Exception ex) { src = "dict-threw:" + ex.GetType().Name; }
            }
            return false;
        }

        private static string IrRawNum(double? v)
        {
            return v.HasValue
                ? v.Value.ToString("F3", System.Globalization.CultureInfo.InvariantCulture)
                : "null";
        }

        private static string IrRawRead(object tel, IDictionary<string, object> dict, string name)
        {
            object v;
            string src;
            if (!IrRawValue(tel, dict, name, out v, out src)) return src;
            string text;
            try { text = Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture); }
            catch { text = "?"; }
            return (text ?? "null") + "[" + src + "]";
        }

        private static bool IrRawTryDouble(object tel, IDictionary<string, object> dict,
                                            string name, out double val)
        {
            val = 0.0;
            object v;
            string src;
            if (!IrRawValue(tel, dict, name, out v, out src) || v == null) return false;
            try { val = Convert.ToDouble(v, System.Globalization.CultureInfo.InvariantCulture); return true; }
            catch { return false; }
        }

        // Car identity and engine data. iRacing puts these in the SESSION INFO
        // YAML, not the per-tick telemetry, which is why the first probe never
        // saw them. What we are looking for, in DriverInfo:
        //   DriverCarEngCylinderCount  -> engine type, the piece CarFacts has to
        //                                 guess for every other game
        //   DriverCarRedLine / DriverCarSLShiftRPM / DriverCarIdleRPM
        //   DriverCarGearNumForward
        // and per-driver: CarScreenName / CarPath / CarID for the friendly name.
        // If the cylinder count is really there, the whole "scrape every iRacing
        // car and look up its engine" fallback is unnecessary.
        private static readonly string[] IrRawSessionKeys = new string[]
        {
            "DriverCarEngCylinderCount", "DriverCarRedLine", "DriverCarIdleRPM",
            "DriverCarSLFirstRPM", "DriverCarSLShiftRPM", "DriverCarSLLastRPM",
            "DriverCarSLBlinkRPM", "DriverCarGearNumForward", "DriverCarVersion",
            "DriverCarIdx", "CarScreenName", "CarScreenNameShort", "CarPath",
            "CarID", "CarClassShortName", "CarClassID",
        };

        private static void IrRawDumpSessionInfo(object raw)
        {
            try
            {
                const System.Reflection.BindingFlags Pub =
                    System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance;
                object sess = null;
                string sessVia = "none";
                foreach (var candidate in new string[] { "SessionData", "SessionInfo", "Session" })
                {
                    var p = raw.GetType().GetProperty(candidate, Pub);
                    if (p != null && p.CanRead && p.GetIndexParameters().Length == 0)
                    {
                        object v = p.GetValue(raw, null);
                        if (v != null) { sess = v; sessVia = candidate; break; }
                    }
                }
                if (sess == null)
                {
                    SimHub.Logging.Current.Info(
                        "[TF4ALL] IRRAW session info: no SessionData/SessionInfo/Session property on "
                        + raw.GetType().FullName + ". Car name and engine data cannot come from this route.");
                    return;
                }

                SimHub.Logging.Current.Info("[TF4ALL] IRRAW session info via ." + sessVia
                    + " type=" + sess.GetType().FullName);

                // Case 1: it is the raw YAML text. Scan it for the keys we care
                // about; iRacing indents them, so match on the trimmed key.
                string yaml = sess as string;
                if (yaml == null)
                {
                    // Raw is a FIELD on iRacingSDK.SessionData, not a property.
                    // The first pass only looked for a property, so the YAML scan
                    // never ran and we saw just the SDK's parsed subset. Same
                    // class of miss as typed-property versus dictionary.
                    string[] names = { "Raw", "Yaml", "Text", "YamlText" };
                    for (int i = 0; i < names.Length && yaml == null; i++)
                    {
                        var p = sess.GetType().GetProperty(names[i], Pub);
                        if (p != null && p.PropertyType == typeof(string) && p.CanRead)
                        { yaml = p.GetValue(sess, null) as string; continue; }
                        var fi = sess.GetType().GetField(names[i], Pub);
                        if (fi != null && fi.FieldType == typeof(string))
                            yaml = fi.GetValue(sess) as string;
                    }
                    if (yaml == null)
                    {
                        var fieldNames = new List<string>();
                        foreach (var fi2 in sess.GetType().GetFields(Pub)) fieldNames.Add(fi2.Name + ":" + fi2.FieldType.Name);
                        SimHub.Logging.Current.Info("[TF4ALL] IRRAW session fields: "
                            + string.Join(", ", fieldNames.ToArray()));
                    }
                }
                if (yaml != null)
                {
                    int hits = 0;
                    foreach (var line in yaml.Split('\n'))
                    {
                        string t = line.Trim();
                        int c = t.IndexOf(':');
                        if (c <= 0) continue;
                        string key = t.Substring(0, c).Trim();
                        for (int i = 0; i < IrRawSessionKeys.Length; i++)
                        {
                            if (!string.Equals(key, IrRawSessionKeys[i], StringComparison.Ordinal)) continue;
                            SimHub.Logging.Current.Info("[TF4ALL] IRRAW session   " + t);
                            hits++;
                            break;
                        }
                        if (hits > 60) break;   // a full grid repeats the per-driver keys
                    }
                    SimHub.Logging.Current.Info("[TF4ALL] IRRAW session info: YAML scan found "
                        + hits.ToString(System.Globalization.CultureInfo.InvariantCulture)
                        + " matching keys (yamlLen="
                        + yaml.Length.ToString(System.Globalization.CultureInfo.InvariantCulture) + ").");
                    return;
                }

                // Case 2: the SDK parsed it into objects. Walk DriverInfo's
                // scalar properties, which is where the engine data lives.
                var diProp = sess.GetType().GetProperty("DriverInfo", Pub);
                object di = diProp != null ? diProp.GetValue(sess, null) : null;
                if (di == null)
                {
                    var names = new List<string>();
                    foreach (var p in sess.GetType().GetProperties(Pub)) names.Add(p.Name);
                    names.Sort(StringComparer.Ordinal);
                    SimHub.Logging.Current.Info("[TF4ALL] IRRAW session info: no DriverInfo. Top-level: "
                        + string.Join(", ", names.ToArray()));
                    return;
                }
                var sb = new System.Text.StringBuilder();
                foreach (var p in di.GetType().GetProperties(Pub))
                {
                    if (p.GetIndexParameters().Length != 0 || !p.CanRead) continue;
                    var pt = p.PropertyType;
                    if (pt != typeof(string) && !pt.IsPrimitive && !pt.IsEnum) continue;
                    object v = null;
                    try { v = p.GetValue(di, null); } catch { }
                    if (sb.Length > 0) sb.Append(' ');
                    sb.Append(p.Name).Append('=').Append(Convert.ToString(v,
                        System.Globalization.CultureInfo.InvariantCulture) ?? "null");
                }
                SimHub.Logging.Current.Info("[TF4ALL] IRRAW session DriverInfo: " + sb.ToString());
            }
            catch (Exception ex)
            {
                SimHub.Logging.Current.Info(
                    "[TF4ALL] IRRAW session info threw " + ex.GetType().Name + ": " + ex.Message);
            }
        }

        // Render a sub-tick value as type, length and its elements. Printing the
        // elements is the point: six DIFFERENT numbers means genuine 360 Hz
        // sub-tick data, six copies of one number means the sim padded a single
        // 60 Hz sample and the array buys us nothing.
        private static string IrRawDescribeSubTick(object v)
        {
            if (v == null) return "present but null";
            var arr = v as Array;
            if (arr == null)
            {
                string scalar;
                try { scalar = Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture); }
                catch { scalar = "?"; }
                return "present, NOT an array, type=" + v.GetType().FullName + ", value=" + scalar;
            }
            var sb = new System.Text.StringBuilder();
            sb.Append("present, type=").Append(v.GetType().FullName)
              .Append(", len=").Append(arr.Length.ToString(System.Globalization.CultureInfo.InvariantCulture))
              .Append(", [");
            int n = arr.Length < 8 ? arr.Length : 8;
            for (int i = 0; i < n; i++)
            {
                if (i > 0) sb.Append(' ');
                object e = null;
                try { e = arr.GetValue(i); } catch { }
                string text;
                try { text = Convert.ToString(e, System.Globalization.CultureInfo.InvariantCulture); }
                catch { text = "?"; }
                sb.Append(text ?? "null");
            }
            if (n < arr.Length) sb.Append(" ...");
            sb.Append(']');
            return sb.ToString();
        }

        private void WireFfbTapCallbacks(UsbPcapFfbTap tap)
        {
            if (tap == null) return;

            // Re-apply the dev/test no-FFB simulation across tap restarts.
            tap.SimulateNoFfbCapture = _simulateNoFfb;

            // Re-apply the experimental capture opt-in across tap restarts,
            // using the effective value (forced on inside Farming Simulator).
            tap.ExperimentalCapture = EffectiveExperimentalCapture();

            // Per-wheel identity (mescon, 2026-07): seed the HID++ 0x8123
            // feature-index resolver (RS50 = 0x10, else the G PRO's 0x0e) and
            // open the RS50 report-0x12 path without the FFBX opt-in. Seed
            // only: the tap's resolver stays live; a dead-silent wrong seed
            // self-heals (see SetFfbFeatureIndexSeed for the confirm-lock
            // limit). With no wheel matched yet (vid/pid 0, string null) this
            // is exactly the historical behavior: seed 0x0e, RS50 gate off.
            tap.Rs50Identified = WheelDiscovery.IsRs50(_hidWheelPid, _hidWheelProductString);
            tap.SetFfbFeatureIndexSeed(
                WheelDiscovery.FfbFeatureIndexSeedFor(_hidWheelPid, _hidWheelProductString));

            // Heartbeat for the liveness watchdog: our stream's packets-sent
            // count. Reads the current device each call, so it survives device
            // swaps. While streaming this climbs ~1 kHz.
            // Mode B gate: in full synthesis the game sends NO classic FFB, so
            // "we're streaming but the capture parses nothing" is the NORMAL
            // state, and the watchdog would otherwise restart the tap (with
            // its multi-second bus scans) every ~15 s all session (observed on
            // FM8, 2026-07-05). Freezing the probe makes the delta read 0 →
            // watchdog inert; the moment Mode B disarms the count resumes
            // climbing and the watchdog (and a fresh tap) come right back.
            tap.SetSendActivityProbe(() => _forceMode != ForceModeOff ? 0 : (_device?.PacketsSent ?? 0));

            // The tap healed a drifted address (same wheel identity, new USBPcap
            // location after a replug/re-enumeration). If the user has a manual
            // override pinned, persist the corrected address so it survives a
            // restart. Runs on the tap's reader thread; just a settings write,
            // the tap has already retargeted itself, so no restart here.
            tap.OnDeviceRelocated = (iface, addr) =>
            {
                try
                {
                    if (Settings != null && HasManualUsbPcapDevice
                        && (Settings.ManualUsbPcapInterface != iface
                            || Settings.ManualUsbPcapDeviceAddress != addr))
                    {
                        Settings.ManualUsbPcapInterface     = iface ?? "";
                        Settings.ManualUsbPcapDeviceAddress = addr > 0 ? addr : 0;
                        PersistSettingsCore();
                        SimHub.Logging.Current.Info(
                            $"[TF4ALL] Updated saved USB device override to {iface} dev {addr} (wheel re-enumerated).");
                    }
                }
                catch { }
            };

            // The tap is on the right wheel and the game is driving, but no force
            // feedback reaches our capture even in whole-bus mode. Surface it.
            tap.OnNoFfbWarning = msg =>
            {
                // If experimental FFB detection is off, point the user at it:
                // a wheel sending force in a shape the default path doesn't
                // recognize (e.g. RS50 on report 0x12) is exactly this case.
                // Skip the hint for an identified RS50: its report-0x12 path
                // is already open, so the toggle wouldn't do what the hint
                // implies (it would only lower the resolver sample floor).
                if (Settings != null && !Settings.ExperimentalFfbCapture
                    && !WheelDiscovery.IsRs50(_hidWheelPid, _hidWheelProductString))
                    msg += " If your wheel should have force feedback, try turning on 'Enable experimental FFB detection' (Effects tab, under FFB tweaks), then drive a few seconds.";
                _noFfbCaptureNotice = msg;
                SimHub.Logging.Current.Warn($"[TF4ALL] {msg}");
            };
        }

        // True when the user has a manual USB-device override active.
        public bool HasManualUsbPcapDevice =>
            Settings != null
            && !string.IsNullOrEmpty(Settings.ManualUsbPcapInterface)
            && Settings.ManualUsbPcapDeviceAddress > 0;

        // Read-only snapshot of where the active tap is currently capturing.
        // Used by the picker to surface "ACTIVE" on the right row, and to
        // include the active device in the list even when a fresh descriptor
        // scan misses it (the tap's USBPcap process can shadow the picker's
        // scan on the same interface).
        public string ActiveFfbTapInterface     => _ffbTap?.CurrentInterface;
        public int    ActiveFfbTapDeviceAddress => _ffbTap?.CurrentDeviceAddress ?? 0;

        // Dispose the FFB tap WITHOUT restarting it. Used by the manual-
        // device picker while it runs its descriptor scan: USBPcap captures
        // from another process on the same interface can prevent injected
        // descriptors from reaching our parallel scan. The picker calls
        // RestartFfbTap() on close to resume capture.
        public void StopFfbTap()
        {
            try { _ffbTap?.Dispose(); } catch { }
            _ffbTap = null;
            try { _steeringReader?.Dispose(); } catch { }
            _steeringReader = null;
        }

        // Dispose the current FFB tap and spawn a fresh one. Used after the
        // user changes the USBPcap override path or reinstalls USBPcap so
        // the new binary takes effect without restarting SimHub. No-op when
        // no device is active (the next device init will pick up the new
        // setting automatically).
        public bool RestartFfbTap()
        {
            if (_device == null) return false;

            try { _ffbTap?.Dispose(); } catch { }
            _ffbTap = null;
            try { _steeringReader?.Dispose(); } catch { }
            _steeringReader = null;

            var (ifaceOverride, devOverride) = ResolveUsbPcapOverride();
            _ffbTap = new UsbPcapFfbTap(ifaceOverride, devOverride, Settings?.UsbPcapCmdPathOverride)
            {
                Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                HostElevated = IsRunningElevated,
            };
            if (_hidWheelVid != 0 || _hidWheelPid != 0)
                _ffbTap.SetHidDiscoveredWheel(_hidWheelVid, _hidWheelPid);
            _ffbTap.SetOverrideIdentity((ushort)(Settings?.ManualUsbPcapVid ?? 0), (ushort)(Settings?.ManualUsbPcapPid ?? 0));
            WireFfbTapCallbacks(_ffbTap);
            ApplyUsbBytesLoggingSetting();

            // Recreate the physical steering reader the stop path disposed.
            // Symmetry fix: this method rebuilt the tap but forgot the reader,
            // so a picker session or USBPcap reinstall silently cost the
            // damper + Direct centering their low-lag position source (and
            // the stationary spring its pause coverage) until the next full
            // device bring-up. The reader's own self-heal can't help here: a
            // nulled FIELD has no dead session to resurrect. Mirrors the
            // bring-up creation site; failure is non-fatal (consumers fall
            // back to game steering, same as everywhere else).
            if (_hidWheelVid != 0 || _hidWheelPid != 0)
            {
                try
                {
                    _steeringReader = new WheelSteeringReader(_hidWheelVid, _hidWheelPid)
                    {
                        Logger = msg => SimHub.Logging.Current.Info($"[TF4ALL] {msg}"),
                    };
                    _steeringReader.Start();
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Warn($"[TF4ALL] Steering reader failed to restart: {ex.Message}");
                    _steeringReader = null;
                }
            }

            return _ffbTap.Start();
        }

        // Returns the path where usb-trace.pcap should live: alongside
        // SimHub's log dir, so the Export Logs zip picks it up next to the
        // .txt logs without any additional plumbing. Computed from the host
        // process path rather than our assembly path because we live in
        // PluginsData but SimHub's log dir is at the install root. Written
        // as a real pcap with DLT_USBPCAP so Wireshark opens it directly.
        public static string GetUsbTraceLogPath()
        {
            string simHubRoot = System.IO.Path.GetDirectoryName(
                System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName);
            return System.IO.Path.Combine(simHubRoot, "usb-trace.pcap");
        }

        // Apply the persisted LogUsbBytesEnabled flag to the live FFB tap.
        // Called after each tap (re)start and from the Diagnostics toggle
        // handler. Idempotent and safe on a null tap.
        public void ApplyUsbBytesLoggingSetting()
        {
            if (_ffbTap == null) return;
            bool enabled = Settings?.LogUsbBytesEnabled ?? false;
            _ffbTap.SetRawPacketLogPath(enabled ? GetUsbTraceLogPath() : null);
        }

        // Toggle the raw USB packet log. Persists the new state and applies
        // it to the live tap immediately. Called from the Diagnostics
        // checkbox in SettingsControl.
        public void SetUsbBytesLoggingEnabled(bool enabled)
        {
            if (Settings == null) return;
            if (Settings.LogUsbBytesEnabled == enabled) return;
            Settings.LogUsbBytesEnabled = enabled;
            try { PersistSettingsCore(); } catch { }
            ApplyUsbBytesLoggingSetting();
            SimHub.Logging.Current.Info($"[TF4ALL] USB byte logging {(enabled ? "enabled" : "disabled")}.");
        }

        // Launches the bundled USBPcap installer (silent /S, elevated). Called
        // from the settings panel's Reinstall action when USBPcap is missing
        // or broken. Runs the wait + restart on a background thread so the
        // SimHub UI thread doesn't freeze during the install. Status updates
        // surface through the existing FfbTapStatus -> FfbTapText polling.
        public void ReinstallUsbPcapAsync()
        {
            string pluginDir = System.IO.Path.GetDirectoryName(typeof(TrueforcePlugin).Assembly.Location);
            string setup = System.IO.Path.Combine(pluginDir, "vendor", "USBPcapSetup.exe");
            if (!System.IO.File.Exists(setup))
            {
                SimHub.Logging.Current.Warn($"[TF4ALL] USBPcap setup not found at {setup}. Was the plugin installed via the official installer?");
                return;
            }
            // Authenticode signature verification on the bundled USBPcap
            // installer was added as part of the B8 audit response and
            // removed shortly after. The realistic threat model for this
            // file is local-disk tampering between install and reinstall
            // (low risk on a single-user Windows account), and the
            // generic WinVerifyTrust pass didn't gate on our publisher
            // cert specifically, so it would pass for any cert-signed
            // installer an attacker substituted. The HTTPS + repo pin on
            // the main plugin update path (still enforced via
            // ChannelValidation.IsTrustedGitHubReleaseUrl) carries the
            // actual defence. ChannelValidation.VerifyAuthenticodeSignature
            // is left in place for future re-enablement if we ever sign
            // releases with a pinned publisher cert.

            ThreadPool.QueueUserWorkItem(_ =>
            {
                try
                {
                    var psi = new ProcessStartInfo(setup, "/S")
                    {
                        UseShellExecute = true, // required for the runas verb
                        Verb = "runas",         // triggers UAC; USBPcap install needs admin
                        CreateNoWindow = true,
                        WindowStyle = ProcessWindowStyle.Hidden,
                    };
                    using (var proc = Process.Start(psi))
                    {
                        proc?.WaitForExit();
                    }
                    SimHub.Logging.Current.Info("[TF4ALL] USBPcap installer finished. Re-probing.");

                    // Clear any user-set override so the fresh install gets
                    // picked up from the default Program Files paths.
                    if (Settings != null) Settings.UsbPcapCmdPathOverride = "";
                    try { PersistSettingsCore(); } catch { }
                    RestartFfbTap();
                }
                catch (System.ComponentModel.Win32Exception)
                {
                    // User cancelled the UAC prompt, or another shell-execute
                    // failure. Swallow without restarting the tap.
                    SimHub.Logging.Current.Info("[TF4ALL] USBPcap install cancelled or blocked by UAC.");
                }
                catch (Exception ex)
                {
                    SimHub.Logging.Current.Error("[TF4ALL] USBPcap install failed", ex);
                }
            });
        }
    }
}
